window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"pd-20501","module":"panduan","diff":2,"exam":"省考","prompt":"小区设置四色垃圾桶，居民将厨余、可回收、有害和其他垃圾分别投放。垃圾分类是指按一定规定或标准，将垃圾分类储存、分类投放和分类搬运，从而转变成公共资源的一系列活动的总称。根据上述定义，下列同样属于垃圾分类的是：","options":["学校组织学生将废纸、塑料瓶分类投放并回收利用","环卫工人清晨清扫街道","保洁员将所有垃圾混装运走","居民将垃圾装袋后统一堆放在楼道口"],"answer":0,"explanation":"垃圾分类的要件是：按标准分类、分类储存投放、实现资源化利用。「学校组织学生将废纸、塑料瓶分类投放并回收利用」完全符合上述要件；其余选项分别存在以下问题：混装混运未实行分类；统一堆放未分类投放；清扫作业不属于垃圾分类。故选A。"},{"id":"pd-20502","module":"panduan","diff":3,"exam":"国考","prompt":"犹豫：迟疑\n下列与题干词项逻辑关系最相近的是：","options":["车厢：火车","背水一战：韩信","手指：手","慌张：慌忙"],"answer":3,"explanation":"题干「犹豫」与「迟疑」为近义关系；「慌张」与「慌忙」也是近义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20503","module":"panduan","diff":3,"exam":"省考","prompt":"裁缝：缝纫机\n下列与题干词项逻辑关系最相近的是：","options":["咖啡：饮品","草木皆兵：苻坚","京剧：戏曲","司机：方向盘"],"answer":3,"explanation":"题干「裁缝」与「缝纫机」为职业与其专用工具的对应；「司机」与「方向盘」也是职业与其专用工具的对应，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20504","module":"panduan","diff":2,"exam":"医疗编","prompt":"考古学家认为某处遗址是古代的粮仓。以下哪项如果为真，最能支持该判断？","options":["遗址内发现了大量炭化谷物堆积以及防潮防鼠的设施遗迹","遗址的规模较大","遗址位于古城墙附近","遗址出土了少量陶器"],"answer":0,"explanation":"炭化谷物和防潮设施是粮仓功能的直接证据，最能支持该判断。故选A。"},{"id":"pd-20505","module":"panduan","diff":1,"exam":"事业编","prompt":"裙子：服装\n下列与题干词项逻辑关系最相近的是：","options":["天：地","闻鸡起舞：祖逖","豆浆：饮品","疲惫：困倦"],"answer":2,"explanation":"题干「裙子」与「服装」为种属包含关系；「豆浆」与「饮品」也是种属包含关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20506","module":"panduan","diff":3,"exam":"国考","prompt":"班里发生了一件事：刚拖过的地面被踩脏了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“不是我踩脏地面的。”；乙说：“不是我踩脏地面的。”；丙说：“是乙踩脏地面的。”；丁说：“是乙踩脏地面的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["乙","甲","丙","丁"],"answer":0,"explanation":"只有一人说真话。逐一假设验证可知，乙的话为真，其余三人的话均为假。故选A。"},{"id":"pd-20507","module":"panduan","diff":2,"exam":"国考","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“是丁拿走钥匙的。”；乙说：“是甲拿走钥匙的。”；丙说：“不是我拿走钥匙的。”；丁说：“不是我拿走钥匙的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["丁","乙","甲","丙"],"answer":0,"explanation":"只有一人说真话。逐一假设验证可知，丁的话为真，其余三人的话均为假。故选A。"},{"id":"pd-20508","module":"panduan","diff":1,"exam":"教师编","prompt":"小张、小王、小李、小赵、小刘五人比较跑步速度。已知：小李比小王快；小王比小赵快；小张比小刘快；小王比小张快；小赵不是最快的。这五人的跑步速度从快到慢排序，谁排第一？","options":["小赵","小李","小王","小刘"],"answer":1,"explanation":"由题干条件逐步推理，可得五人跑步速度从快到慢的完整排序为：小李＞小王＞小张＞小赵＞小刘。因此排第一的是小李。故选B。"},{"id":"pd-20509","module":"panduan","diff":2,"exam":"事业编","prompt":"所有的微波炉都是家电，所有的家具都不是家电。由此可以推出：","options":["有的微波炉是家具","有的家具是微波炉","所有的家具都是微波炉","所有的家具都不是微波炉"],"answer":3,"explanation":"微波炉都包含于家电，而家具与家电完全排斥，所以家具与微波炉也完全排斥，即所有的家具都不是微波炉；其余选项与题干矛盾或不能必然推出。故选D。"},{"id":"pd-20510","module":"panduan","diff":1,"exam":"省考","prompt":"某药企称其感冒药见效快，因为服药患者通常两天内症状明显缓解。以下哪项如果为真，最能削弱该说法？","options":["部分患者服药后出现嗜睡反应","普通感冒本身通常两三天内就会自行缓解，不服药也是如此","该感冒药的主要成分较为常见","该感冒药为非处方药品"],"answer":1,"explanation":"症状缓解是感冒自愈的结果，与药物无关，切断了服药与缓解之间的因果联系。故选B。"},{"id":"pd-20511","module":"panduan","diff":2,"exam":"国考","prompt":"孙某自动投案，但只交代部分罪行，隐瞒了主要犯罪事实。自首是指犯罪以后自动投案，如实供述自己的罪行的行为。根据上述定义，下列不属于自首的是：","options":["赵某犯罪后委托家人代为报警，本人在原地等候，到案后如实交代罪行","周某因交通肇事被现场查获，谎称车辆是他人驾驶","李某盗窃后内心不安，主动到公安机关交代了全部盗窃事实","王某作案后潜逃，在通缉期间向当地派出所投案，并如实供述了罪行"],"answer":1,"explanation":"自首的要件是：自动投案、如实供述自己的罪行。「周某因交通肇事被现场查获，谎称车辆是他人驾驶」不符合要件：未如实供述自己的罪行；其余选项均符合自首的全部要件。故选B。"},{"id":"pd-20512","module":"panduan","diff":2,"exam":"医疗编","prompt":"雄鹰：翱翔\n下列与题干词项逻辑关系最相近的是：","options":["鲜花：绽放","砖块：墙壁","浙江：杭州","公开：秘密"],"answer":0,"explanation":"题干「雄鹰」与「翱翔」为主谓关系；「鲜花」与「绽放」也是主谓关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20513","module":"panduan","diff":1,"exam":"事业编","prompt":"新老师第一次上课妙语连珠，学生此后一直认为他学识渊博。首因效应是指交往双方形成的第一次印象对今后交往关系的影响，即先入为主带来的效果。根据上述定义，下列同样属于首因效应的是：","options":["小张因好友极力推荐而对某人产生好感","共事多年后，同事对小王形成了全面深入的了解","小陈最近一次表现出色，大家改变了对他的原有看法","小赵与新同事初次见面时热情周到，同事此后对他印象颇佳"],"answer":3,"explanation":"首因效应的要件是：第一次接触、第一印象、对后续交往产生持续影响。「小赵与新同事初次见面时热情周到，同事此后对他印象颇佳」完全符合上述要件；其余选项分别存在以下问题：长期相处形成的认识不是第一印象；好感来自他人评价，不是初次接触的直接印象；最近表现改变印象属于近因效应。故选D。"},{"id":"pd-20514","module":"panduan","diff":2,"exam":"国考","prompt":"指鹿为马：赵高\n下列与题干词项逻辑关系最相近的是：","options":["相声：曲艺","《水浒传》：施耐庵","纸上谈兵：赵括","秦朝：嬴政"],"answer":2,"explanation":"题干「指鹿为马」与「赵高」为成语典故与其主人公的对应；「纸上谈兵」与「赵括」也是成语典故与其主人公的对应，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20515","module":"panduan","diff":1,"exam":"省考","prompt":"有的护士是值夜班的人，所有的值夜班的人都是工作辛苦的人。由此可以推出：","options":["所有的工作辛苦的人都是护士","所有的护士都是工作辛苦的人","有的护士是工作辛苦的人","有的护士不是工作辛苦的人"],"answer":2,"explanation":"有的护士是值夜班的人，而值夜班的人都属于工作辛苦的人，所以这部分护士也属于工作辛苦的人，即有的护士是工作辛苦的人；不能扩大为全称结论，其余选项均不必然成立。故选C。"},{"id":"pd-20516","module":"panduan","diff":1,"exam":"省考","prompt":"企业新增两条高排放生产线。碳中和是指在一定时期内，通过植树造林、节能减排等方式，抵消自身产生的二氧化碳排放，实现二氧化碳净零排放。根据上述定义，下列不属于碳中和的是：","options":["某会议购买林业碳汇抵消活动产生的全部碳排放，实现碳中和办会","某城市通过能源转型与森林碳汇，使全市年度碳排放与吸收相抵","某家庭通过节约用电减少了部分碳排放","某企业通过技术改造减少排放，并植树造林抵消剩余排放量，实现年度净零排放"],"answer":2,"explanation":"碳中和的要件是：一定时期内、以植树造林或节能减排等方式抵消排放、实现净零排放。「某家庭通过节约用电减少了部分碳排放」不符合要件：仅减少部分排放，未实现抵消与净零；其余选项均符合碳中和的全部要件。故选C。"},{"id":"pd-20517","module":"panduan","diff":1,"exam":"事业编","prompt":"键盘：电脑\n下列与题干词项逻辑关系最相近的是：","options":["保护：环境","龙井：杭州","表盘：手表","商量：商议"],"answer":2,"explanation":"题干「键盘」与「电脑」为组成关系；「表盘」与「手表」也是组成关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20518","module":"panduan","diff":1,"exam":"医疗编","prompt":"如果课前预习，那么听课更有针对性；如果听课更有针对性，那么学习效果提升。由此可以推出：","options":["如果学习效果提升，那么课前预习","如果没有课前预习，那么学习效果不佳","如果听课更有针对性，那么课前预习","如果课前预习，那么学习效果提升"],"answer":3,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果课前预习，那么学习效果提升；其余选项均属无效推理。故选D。"},{"id":"pd-20519","module":"panduan","diff":2,"exam":"国考","prompt":"如果消防设施完好，那么火灾损失减小。现已确认火灾损失没有减小。由此可以推出：","options":["消防设施完好","如果消防设施不完好，那么火灾损失没有减小","消防设施完好，尽管火灾损失没有减小","消防设施不完好"],"answer":3,"explanation":"充分条件命题否定后件就要否定前件。由火灾损失没有减小，可以推出消防设施不完好；其余选项均不能由题干必然推出。故选D。"},{"id":"pd-20520","module":"panduan","diff":3,"exam":"医疗编","prompt":"如果市场行情好转，那么公司盈利增加；如果公司盈利增加，那么员工待遇改善。由此可以推出：","options":["如果公司盈利增加，那么市场行情好转","如果市场行情没有好转，那么员工待遇没有改善","如果市场行情好转，那么员工待遇改善","如果员工待遇改善，那么市场行情好转"],"answer":2,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果市场行情好转，那么员工待遇改善；其余选项均属无效推理。故选C。"},{"id":"pd-20521","module":"panduan","diff":2,"exam":"国考","prompt":"所有的法官都是司法人员，所有的医生都不是司法人员。由此可以推出：","options":["所有的医生都是法官","有的法官是医生","有的医生是法官","所有的医生都不是法官"],"answer":3,"explanation":"法官都包含于司法人员，而医生与司法人员完全排斥，所以医生与法官也完全排斥，即所有的医生都不是法官；其余选项与题干矛盾或不能必然推出。故选D。"},{"id":"pd-20522","module":"panduan","diff":1,"exam":"国考","prompt":"退休后的老周报名老年大学学习书法，此前他也参加过单位组织的各类培训。终身教育是指人们在一生各阶段中所受各种教育的总和，包括正规教育与非正规教育，贯穿人的一生。根据上述定义，下列同样属于终身教育的是：","options":["在职教师利用假期参加网络研修课程，不断更新教学知识","公司为新员工组织入职培训","小赵全日制读完本科后便停止了学习","小学生按照课表上课"],"answer":0,"explanation":"终身教育的要件是：贯穿一生各阶段、包括正规与非正规教育。「在职教师利用假期参加网络研修课程，不断更新教学知识」完全符合上述要件；其余选项分别存在以下问题：仅接受某一阶段教育，未贯穿一生；仅属正规教育的一个片段；单一阶段的培训不构成终身教育。故选A。"},{"id":"pd-20523","module":"panduan","diff":2,"exam":"国考","prompt":"完整：残缺\n下列与题干词项逻辑关系最相近的是：","options":["医生：医院","天平：称重","司机：方向盘","安全：危险"],"answer":3,"explanation":"题干「完整」与「残缺」为反义关系；「安全」与「危险」也是反义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20524","module":"panduan","diff":3,"exam":"教师编","prompt":"总经理授权区域经理在一定额度内自主决定促销方案。授权是指管理者将职权委授给下属，并为其提供必要的条件，使下属能在职权范围内自主处理事务的过程。根据上述定义，下列同样属于授权的是：","options":["公司实行总经理一人拍板制，大小事项均由其决定","领导临时出差，委托同事代为收发文件","部门经理把某项目的日常决策权交给组长，并提供经费支持，由组长自主安排","经理把琐碎事务交给助理，但所有决定仍须逐级请示"],"answer":2,"explanation":"授权的要件是：授予职权、提供必要条件、下属可自主处理事务。「部门经理把某项目的日常决策权交给组长，并提供经费支持，由组长自主安排」完全符合上述要件；其余选项分别存在以下问题：下属无自主决定权，属于事务分派而非授权；权力集中于一人，与授权相反；委托代理事务未授予职权。故选C。"},{"id":"pd-20525","module":"panduan","diff":1,"exam":"国考","prompt":"如果小华认真复习，那么小华考试通过；如果小华考试通过，那么小华顺利升学。由此可以推出：","options":["如果小华考试通过，那么小华认真复习","如果小华认真复习，那么小华顺利升学","如果小华没有认真复习，那么小华没能顺利升学","如果小华顺利升学，那么小华认真复习"],"answer":1,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果小华认真复习，那么小华顺利升学；其余选项均属无效推理。故选B。"},{"id":"pd-20526","module":"panduan","diff":3,"exam":"国考","prompt":"如果航班准点起飞，那么旅客按时到达。现已确认旅客没能按时到达。由此可以推出：","options":["航班准点起飞，尽管旅客没能按时到达","航班准点起飞","航班没有准点起飞","如果航班没有准点起飞，那么旅客没能按时到达"],"answer":2,"explanation":"充分条件命题否定后件就要否定前件。由旅客没能按时到达，可以推出航班没有准点起飞；其余选项均不能由题干必然推出。故选C。"},{"id":"pd-20527","module":"panduan","diff":2,"exam":"国考","prompt":"屋顶：房子\n下列与题干词项逻辑关系最相近的是：","options":["商人：收藏家","桌腿：桌子","摄影师：相机","理论：实践"],"answer":1,"explanation":"题干「屋顶」与「房子」为组成关系；「桌腿」与「桌子」也是组成关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20528","module":"panduan","diff":1,"exam":"省考","prompt":"如果课前预习，那么听课更有针对性。现已确认听课缺乏针对性。由此可以推出：","options":["课前预习","课前预习，尽管听课缺乏针对性","没有课前预习","如果没有课前预习，那么听课缺乏针对性"],"answer":2,"explanation":"充分条件命题否定后件就要否定前件。由听课缺乏针对性，可以推出没有课前预习；其余选项均不能由题干必然推出。故选C。"},{"id":"pd-20529","module":"panduan","diff":3,"exam":"医疗编","prompt":"某路段安装路灯后，夜间交通事故明显减少，交警部门认为是路灯改善了夜间视线。以下哪项如果为真，最能削弱该结论？","options":["新路灯采用了节能照明技术","夜间事故多发生在凌晨时段","同期该路段夜间车流量因附近商圈搬迁减少了一半","该路段还重新施划了交通标线"],"answer":2,"explanation":"车流量大幅减少才是事故减少的原因，属于另有他因。故选C。"},{"id":"pd-20530","module":"panduan","diff":2,"exam":"省考","prompt":"甲、乙、丙、丁、戊五人比较身高。已知：乙比戊高；甲比丙高；乙比丁高；甲不是最高的。这五人的身高从高到矮排序，谁排第一？","options":["丁","乙","戊","甲"],"answer":1,"explanation":"由题干条件逐步推理，可得五人身高从高到矮的完整排序为：乙＞甲＞丁＞戊＞丙。因此排第一的是乙。故选B。"},{"id":"pd-20531","module":"panduan","diff":2,"exam":"国考","prompt":"小李整理个人通讯录中的两百个联系人。大数据是指规模巨大、类型多样、增长快速，无法用常规软件工具在合理时间内完成采集、处理和分析的数据集合及相关技术。根据上述定义，下列不属于大数据的是：","options":["科研机构汇集全球气象站多年的观测数据，进行大规模分析建模","文员将会议记录录入文档保存","交通部门整合全市摄像头与车载定位产生的海量数据，实时分析路况","某平台汇集数亿用户的浏览和交易记录，通过分布式计算挖掘消费趋势"],"answer":1,"explanation":"大数据的要件是：规模巨大、类型多样、常规工具难以处理。「文员将会议记录录入文档保存」不符合要件：常规录入不属于大数据范畴；其余选项均符合大数据的全部要件。故选B。"},{"id":"pd-20532","module":"panduan","diff":3,"exam":"省考","prompt":"老周多次求职被拒后，不再投递简历，觉得努力也没用。习得性无助是指个体经历反复失败或挫折后，感到一切都无法控制，从而产生无能为力、放弃努力的心理状态。根据上述定义，下列同样属于习得性无助的是：","options":["小孙因身体不适暂停训练，康复后继续投入","小狗多次尝试跳出隔板均告失败后，即使隔板降低也不再尝试","小钱考试失利后总结教训，加倍努力备考","小吴第一次学游泳呛水，有些害怕但仍坚持练习"],"answer":1,"explanation":"习得性无助的要件是：反复失败或挫折、感到无法控制、放弃努力。「小狗多次尝试跳出隔板均告失败后，即使隔板降低也不再尝试」完全符合上述要件；其余选项分别存在以下问题：失败后积极归因并加倍努力，与放弃努力相反；初次挫折后仍坚持尝试，未形成无助感；暂停训练有客观原因，并非放弃努力。故选B。"},{"id":"pd-20533","module":"panduan","diff":2,"exam":"省考","prompt":"班里发生了一件事：图书角的一本书被弄破了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“是王五弄破图书的。”；李四说：“不是我弄破图书的。”；王五说：“是赵六弄破图书的。”；赵六说：“不是我弄破图书的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["王五","赵六","张三","李四"],"answer":1,"explanation":"只有一人说真话。逐一假设验证可知，赵六的话为真，其余三人的话均为假。故选B。"},{"id":"pd-20534","module":"panduan","diff":2,"exam":"教师编","prompt":"花瓣：花朵\n下列与题干词项逻辑关系最相近的是：","options":["勤奋：勤恳","鳞片：鱼","保守：开放","眼镜：矫正视力"],"answer":1,"explanation":"题干「花瓣」与「花朵」为组成关系；「鳞片」与「鱼」也是组成关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20535","module":"panduan","diff":1,"exam":"国考","prompt":"并非（商品质优价廉并且商品畅销）。由此可以推出：","options":["商品质优价廉或者商品畅销","商品并非质优价廉并且商品不畅销","如果商品并非质优价廉，那么商品畅销","商品并非质优价廉或者商品不畅销"],"answer":3,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（商品质优价廉并且商品畅销），等值于“商品并非质优价廉或者商品不畅销”；其余选项均不符合德摩根定律。故选D。"},{"id":"pd-20536","module":"panduan","diff":1,"exam":"国考","prompt":"小钱、小郑、小冯、小许、小何五人比较体重。已知：小郑比小钱重；小何比小郑重；小许比小冯重；小许比小钱重；小何不是最重的。这五人的体重从重到轻排序，谁排第一？","options":["小许","小冯","小何","小钱"],"answer":0,"explanation":"由题干条件逐步推理，可得五人体重从重到轻的完整排序为：小许＞小何＞小郑＞小冯＞小钱。因此排第一的是小许。故选A。"},{"id":"pd-20537","module":"panduan","diff":2,"exam":"医疗编","prompt":"城市居民利用假期到乡村度假。城市化是指人口向城镇集聚、乡村地区转变为城镇地区，城镇数量增加和规模扩大的过程。根据上述定义，下列不属于城市化的是：","options":["某乡实施农村危房改造，村容焕然一新","某县撤县设区，大量农村人口进入城区就业定居，城区面积不断扩大","因工业园区建设，周边村庄逐步改造为街道，村民转为城镇居民","某市近十年城镇人口占比从百分之四十升至百分之七十，新城区不断扩展"],"answer":0,"explanation":"城市化的要件是：人口向城镇集聚、乡村转变为城镇、城镇规模扩大。「某乡实施农村危房改造，村容焕然一新」不符合要件：乡村建设未改变乡村性质；其余选项均符合城市化的全部要件。故选A。"},{"id":"pd-20539","module":"panduan","diff":2,"exam":"国考","prompt":"班里发生了一件事：桌上的零食不见了。老师询问小王、小李、小张、小刘四人，四人的说法如下：小王说：“是小张拿走零食的。”；小李说：“是小张拿走零食的。”；小张说：“不是我拿走零食的。”；小刘说：“不是我拿走零食的。”。四人中只有3人说真话。由此可以推出，拿走零食的是：","options":["小李","小王","小张","小刘"],"answer":2,"explanation":"只有三人说假话。逐一假设验证：只有假设小张拿走零食时，四句话中为假的才恰好3句，符合题干条件，故小张拿走零食。故选C。"},{"id":"pd-20540","module":"panduan","diff":2,"exam":"事业编","prompt":"公司墙上的标语口号仅挂在墙上，无人践行。企业文化是企业在长期经营中形成的、为全体成员共同遵循的价值观念和行为规范的总和。根据上述定义，下列不属于企业文化的是：","options":["某科技公司的创新文化深入人心，员工主动提出改进建议蔚然成风","某公司多年倡导客户第一，员工言行处处体现这一理念","老字号企业的诚信经营观念代代相传，成为全体店员的自觉行为","公司办公楼进行了豪华装修"],"answer":3,"explanation":"企业文化的要件是：长期经营中形成、全体成员共同遵循、价值观念与行为规范。「公司办公楼进行了豪华装修」不符合要件：办公环境属于物质层面，不是价值观念；其余选项均符合企业文化的全部要件。故选D。"},{"id":"pd-20541","module":"panduan","diff":2,"exam":"省考","prompt":"如果天下雨，那么地面变湿；如果地面变湿，那么行人行走不便。由此可以推出：","options":["如果地面变湿，那么天下雨","如果天下雨，那么行人行走不便","如果天没下雨，那么行走不受影响","如果行人行走不便，那么天下雨"],"answer":1,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果天下雨，那么行人行走不便；其余选项均属无效推理。故选B。"},{"id":"pd-20542","module":"panduan","diff":2,"exam":"事业编","prompt":"并非（保持乐观心态并且压力得到缓解）。由此可以推出：","options":["如果心态悲观，那么压力得到缓解","心态悲观或者压力得不到缓解","保持乐观心态或者压力得到缓解","心态悲观并且压力得不到缓解"],"answer":1,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（保持乐观心态并且压力得到缓解），等值于“心态悲观或者压力得不到缓解”；其余选项均不符合德摩根定律。故选B。"},{"id":"pd-20543","module":"panduan","diff":2,"exam":"国考","prompt":"并非（课前预习并且听课更有针对性）。由此可以推出：","options":["课前预习或者听课更有针对性","没有课前预习或者听课缺乏针对性","没有课前预习并且听课缺乏针对性","如果没有课前预习，那么听课更有针对性"],"answer":1,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（课前预习并且听课更有针对性），等值于“没有课前预习或者听课缺乏针对性”；其余选项均不符合德摩根定律。故选B。"},{"id":"pd-20544","module":"panduan","diff":2,"exam":"事业编","prompt":"小张、小王、小李、小赵四人来自的城市各不相同，分别是北京、上海、广州、深圳。已知：小赵来自的城市不是上海；小赵来自的城市不是深圳；小王来自北京；小张来自的城市不是广州；小李来自的城市不是深圳。由此可以推出，小李来自：","options":["深圳","北京","广州","上海"],"answer":3,"explanation":"由题干条件逐一排除可得：小张来自深圳；小王来自北京；小李来自上海；小赵来自广州。因此小李来自上海。故选D。"},{"id":"pd-20545","module":"panduan","diff":2,"exam":"国考","prompt":"如果实验设计严谨，那么实验结论可靠；如果实验结论可靠，那么研究获得认可。由此可以推出：","options":["如果实验结论可靠，那么实验设计严谨","如果研究获得认可，那么实验设计严谨","如果实验设计严谨，那么研究获得认可","如果实验设计不严谨，那么研究难以获得认可"],"answer":2,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果实验设计严谨，那么研究获得认可；其余选项均属无效推理。故选C。"},{"id":"pd-20546","module":"panduan","diff":2,"exam":"省考","prompt":"研究人员认为，某块化石属于一个此前未知的新物种。上述论证最可能基于的前提是：","options":["该化石的关键特征与所有已知物种均存在本质区别","化石出土地层年代久远","研究人员具备丰富的发掘经验","该化石保存状态较为完整"],"answer":0,"explanation":"只有与已知物种存在本质区别，才能认定其为新物种，该项是结论成立的必要前提。故选A。"},{"id":"pd-20547","module":"panduan","diff":1,"exam":"教师编","prompt":"如果小华认真复习，那么小华考试通过。现已确认小华考试没通过。由此可以推出：","options":["如果小华没有认真复习，那么小华考试没通过","小华认真复习","小华认真复习，尽管小华考试没通过","小华没有认真复习"],"answer":3,"explanation":"充分条件命题否定后件就要否定前件。由小华考试没通过，可以推出小华没有认真复习；其余选项均不能由题干必然推出。故选D。"},{"id":"pd-20548","module":"panduan","diff":2,"exam":"医疗编","prompt":"光明：黑暗\n下列与题干词项逻辑关系最相近的是：","options":["鳞片：鱼","勤劳：懒惰","英国：伦敦","车厢：火车"],"answer":1,"explanation":"题干「光明」与「黑暗」为反义关系；「勤劳」与「懒惰」也是反义关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20549","module":"panduan","diff":2,"exam":"事业编","prompt":"视频网站对同一部影片，学生会员半价，普通会员全价。价格歧视是指经营者对相同的商品或服务，向不同的购买者收取不同价格的行为，且这种价格差异并非基于成本差异。根据上述定义，下列同样属于价格歧视的是：","options":["景区对本地游客和外地游客收取不同门票价格","批发价低于零售价","航空公司头等舱票价高于经济舱","超市对临期食品打折促销"],"answer":0,"explanation":"价格歧视的要件是：相同商品或服务、不同购买者、价格差异并非源于成本差异。「景区对本地游客和外地游客收取不同门票价格」完全符合上述要件；其余选项分别存在以下问题：舱位服务与成本不同，不属于相同商品；商品状态不同，价格差异基于商品差异；批发与零售在包装、服务成本上存在差异。故选A。"},{"id":"pd-20550","module":"panduan","diff":2,"exam":"省考","prompt":"公司组织各部门员工共同分析质量问题的成因，持续优化每个环节。全面质量管理是指以质量为中心，全员参与，通过全过程控制来持续改进产品和服务质量的管理方法。根据上述定义，下列同样属于全面质量管理的是：","options":["某工厂从原料进厂、生产过程到出厂检验层层把关，全体员工参与质量改进小组","企业扩大生产线以提高产量","公司设立质量奖表彰先进员工","质检员在成品出厂前进行抽检"],"answer":0,"explanation":"全面质量管理的要件是：以质量为中心、全员参与、全过程控制、持续改进。「某工厂从原料进厂、生产过程到出厂检验层层把关，全体员工参与质量改进小组」完全符合上述要件；其余选项分别存在以下问题：仅末端检验，未体现全员全过程控制；表彰激励不等于全面质量管理；扩大产量与质量管理无关。故选A。"},{"id":"pd-20551","module":"panduan","diff":1,"exam":"省考","prompt":"某药厂宣称新药A疗效显著，因为临床试验中服用该药的患者大多在一周内痊愈。以下哪项如果为真，最能削弱该宣称？","options":["该疾病本身的自愈率很高，多数患者不服药也能在一周左右痊愈","部分患者服药后感到口干","新药A已获得药品监管部门批准","新药A的生产成本高于传统药物"],"answer":0,"explanation":"该病自愈即可痊愈，说明痊愈并非药物所致，切断了服药与痊愈之间的因果联系。故选A。"},{"id":"pd-20552","module":"panduan","diff":1,"exam":"省考","prompt":"某学校认为，增加体育课课时能够提高学生的体质健康水平。上述论证最可能基于的前提是：","options":["学校拥有标准化运动场","体育课的师资力量充足","学生体质下降的主要原因是日常运动量不足","学生喜欢参加体育活动"],"answer":2,"explanation":"只有当运动不足是体质下降的主要原因时，增加体育课才能改善体质，该项是论证成立的必要前提。故选C。"},{"id":"pd-20553","module":"panduan","diff":1,"exam":"国考","prompt":"皮鞋：鞋类\n下列与题干词项逻辑关系最相近的是：","options":["慌张：慌忙","发动机：汽车","坚强：顽强","卡车：机动车"],"answer":3,"explanation":"题干「皮鞋」与「鞋类」为种属包含关系；「卡车」与「机动车」也是种属包含关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20554","module":"panduan","diff":2,"exam":"国考","prompt":"如果遵守交通规则，那么出行更加安全。现已确认出行安全没有保障。由此可以推出：","options":["遵守交通规则","如果不遵守交通规则，那么出行安全没有保障","不遵守交通规则","遵守交通规则，尽管出行安全没有保障"],"answer":2,"explanation":"充分条件命题否定后件就要否定前件。由出行安全没有保障，可以推出不遵守交通规则；其余选项均不能由题干必然推出。故选C。"},{"id":"pd-20555","module":"panduan","diff":2,"exam":"国考","prompt":"并非（老王坚持早睡并且老王精神饱满）。由此可以推出：","options":["老王不坚持早睡或者老王精神不佳","如果老王不坚持早睡，那么老王精神饱满","老王坚持早睡或者老王精神饱满","老王不坚持早睡并且老王精神不佳"],"answer":0,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（老王坚持早睡并且老王精神饱满），等值于“老王不坚持早睡或者老王精神不佳”；其余选项均不符合德摩根定律。故选A。"},{"id":"pd-20556","module":"panduan","diff":2,"exam":"省考","prompt":"某国收入高度集中于少数人手中，基尼系数接近零点六。基尼系数是衡量收入分配公平程度的指标，数值介于零和一之间，数值越大表示收入差距越大。根据上述定义，下列同样属于基尼系数的是：","options":["某国物价指数持续上涨","某家庭收入明显增加","某国收入分配差距扩大，高收入群体与低收入群体差距拉大，基尼系数上升","某地区失业率上升"],"answer":2,"explanation":"基尼系数的要件是：衡量收入分配差距、数值越大差距越大。「某国收入分配差距扩大，高收入群体与低收入群体差距拉大，基尼系数上升」完全符合上述要件；其余选项分别存在以下问题：物价指数衡量价格水平，与收入分配无关；个体收入变化不能反映整体收入差距；失业率衡量就业状况，不是收入分配指标。故选C。"},{"id":"pd-20557","module":"panduan","diff":2,"exam":"省考","prompt":"四川：成都\n下列与题干词项逻辑关系最相近的是：","options":["白酒：酒类","前进：后退","浙江：杭州","入木三分：王羲之"],"answer":2,"explanation":"题干「四川」与「成都」为省份与其省会的对应；「浙江」与「杭州」也是省份与其省会的对应，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20558","module":"panduan","diff":1,"exam":"事业编","prompt":"小钱考试失利后总结教训，加倍努力备考。习得性无助是指个体经历反复失败或挫折后，感到一切都无法控制，从而产生无能为力、放弃努力的心理状态。根据上述定义，下列不属于习得性无助的是：","options":["小吴第一次学游泳呛水，有些害怕但仍坚持练习","小狗多次尝试跳出隔板均告失败后，即使隔板降低也不再尝试","老周多次求职被拒后，不再投递简历，觉得努力也没用","小赵多次数学考试不及格后，即使题目很简单也不再尝试作答，认为自己天生学不会"],"answer":0,"explanation":"习得性无助的要件是：反复失败或挫折、感到无法控制、放弃努力。「小吴第一次学游泳呛水，有些害怕但仍坚持练习」不符合要件：初次挫折后仍坚持尝试，未形成无助感；其余选项均符合习得性无助的全部要件。故选A。"},{"id":"pd-20559","module":"panduan","diff":1,"exam":"省考","prompt":"某地区消费结构升级，食品支出占比逐年下降，生活水平明显提高。恩格尔系数是食品支出总额占个人消费支出总额的比重，通常用于衡量生活水平，系数越低说明生活水平越高。根据上述定义，下列同样属于恩格尔系数的是：","options":["某国物价普遍上涨导致消费总支出增加","某家庭购买奢侈品的支出大幅增加","小赵家消费总支出中食品所占比重持续降低，生活越来越宽裕","某家庭食品支出的绝对金额逐年增加"],"answer":2,"explanation":"恩格尔系数的要件是：食品支出占消费总支出的比重、反映生活水平。「小赵家消费总支出中食品所占比重持续降低，生活越来越宽裕」完全符合上述要件；其余选项分别存在以下问题：食品支出绝对额不等于其占消费总支出的比重；奢侈品支出不属于食品支出占比的范畴；物价上涨影响的是支出总额，不是食品支出占比。故选C。"},{"id":"pd-20560","module":"panduan","diff":2,"exam":"省考","prompt":"班里发生了一件事：教室里的花瓶被打碎了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“是王五打碎花瓶的。”；李四说：“不是我打碎花瓶的。”；王五说：“不是我打碎花瓶的。”；赵六说：“是张三打碎花瓶的。”。四人中只有1人说真话。由此可以推出，打碎花瓶的是：","options":["赵六","王五","张三","李四"],"answer":3,"explanation":"只有一人说真话。逐一假设验证：只有假设李四打碎花瓶时，四句话中为真的才恰好1句，符合题干条件，故李四打碎花瓶。故选D。"},{"id":"pd-20562","module":"panduan","diff":2,"exam":"事业编","prompt":"气象学家认为，正在接近本市的冷锋将带来明显降水。以下哪项如果为真，最能支持该判断？","options":["气象部门发布了降温提示","卫星云图显示该锋面水汽充沛，且正以预期速度向本市移动","冷锋是常见的天气系统","本市近期气温有所下降"],"answer":1,"explanation":"水汽充沛且移动路径明确，直接支持冷锋带来降水的判断。故选B。"},{"id":"pd-20563","module":"panduan","diff":2,"exam":"省考","prompt":"班里发生了一件事：刚拖过的地面被踩脏了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“是丙踩脏地面的。”；乙说：“不是我踩脏地面的。”；丙说：“不是我踩脏地面的。”；丁说：“是丙踩脏地面的。”。四人中只有1人说真话。由此可以推出，踩脏地面的是：","options":["甲","丙","乙","丁"],"answer":2,"explanation":"只有一人说真话。逐一假设验证：只有假设乙踩脏地面时，四句话中为真的才恰好1句，符合题干条件，故乙踩脏地面。故选C。"},{"id":"pd-20564","module":"panduan","diff":1,"exam":"省考","prompt":"农技站认为，在当地推广某新品种水稻能够提高粮食产量。上述论证最可能基于的前提是：","options":["该新品种能够适应当地的土壤和气候条件","当地农民愿意尝试新品种","种子供应渠道畅通","该品种在其他地区表现优异"],"answer":0,"explanation":"若品种不适应当地条件，便无法保证增产，该项是论证成立的必要前提。故选A。"},{"id":"pd-20565","module":"panduan","diff":1,"exam":"国考","prompt":"某公司认为新员工培训项目提高了员工的工作绩效。以下哪项如果为真，最能支持该结论？","options":["培训在周末进行，不影响日常工作","对比同期未参加培训的同类岗位员工，参训员工的绩效明显更高","参训员工对培训评价良好","培训课程的内容安排紧凑"],"answer":1,"explanation":"设置未参训的对照组进行比较，排除了其他因素，直接支持培训提升绩效的结论。故选B。"},{"id":"pd-20566","module":"panduan","diff":2,"exam":"事业编","prompt":"如果土壤肥沃，那么作物长势良好；如果作物长势良好，那么收成有保障。由此可以推出：","options":["如果作物长势良好，那么土壤肥沃","如果收成有保障，那么土壤肥沃","如果土壤贫瘠，那么收成没有保障","如果土壤肥沃，那么收成有保障"],"answer":3,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果土壤肥沃，那么收成有保障；其余选项均属无效推理。故选D。"},{"id":"pd-20568","module":"panduan","diff":3,"exam":"事业编","prompt":"小赵开店实际支出的房租、水电和进货费用。机会成本是指为了得到某种东西而所要放弃的其他选择中价值最高的那一个。根据上述定义，下列不属于机会成本的是：","options":["周末小张选择加班获得加班费，放弃了外出旅游的愉快体验","小李用一笔钱读研，放弃了年薪十万元的工作机会，这十万元是他读研的机会成本","公司购买设备实际支付的价款","农场主把土地全部用于种植水稻，就放弃了种植蔬菜可能带来的更高收益"],"answer":2,"explanation":"机会成本的要件是：面临多种选择、放弃其他选择、以其中价值最高者计。「公司购买设备实际支付的价款」不符合要件：购买设备的支出是实际花费，不是机会成本；其余选项均符合机会成本的全部要件。故选C。"},{"id":"pd-20569","module":"panduan","diff":1,"exam":"国考","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问小王、小李、小张、小刘四人，四人的说法如下：小王说：“是小李拿走钥匙的。”；小李说：“是小刘拿走钥匙的。”；小张说：“不是我拿走钥匙的。”；小刘说：“不是我拿走钥匙的。”。四人中只有3人说真话。由此可以推出，说假话的是：","options":["小李","小王","小刘","小张"],"answer":0,"explanation":"只有一人说假话。逐一假设验证可知，小李的话为假，其余三人的话均为真。故选A。"},{"id":"pd-20570","module":"panduan","diff":2,"exam":"事业编","prompt":"所有的银杏都是树木，所有的树木都是植物。由此可以推出：","options":["所有的银杏都是植物","有的植物不是银杏","有的银杏不是植物","所有的植物都是银杏"],"answer":0,"explanation":"三段论传递推理：银杏都属于树木，树木都属于植物，所以所有的银杏都是植物；其余选项不能必然推出。故选A。"},{"id":"pd-20571","module":"panduan","diff":2,"exam":"事业编","prompt":"吴承恩：《西游记》：孙悟空\n下列与题干词项逻辑关系最相近的是：","options":["琴：棋：书","沈从文：《边城》：翠翠","梅：兰：竹","服装：上衣：衬衫"],"answer":1,"explanation":"题干三个词为作者、作品与其主人公的对应关系；「沈从文：《边城》：翠翠」也是作者、作品与其主人公的对应关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20572","module":"panduan","diff":2,"exam":"省考","prompt":"如果员工遵守操作规程，那么生产安全得到保障；如果生产安全得到保障，那么企业正常运转。由此可以推出：","options":["如果企业正常运转，那么员工遵守操作规程","如果员工不遵守操作规程，那么企业无法正常运转","如果员工遵守操作规程，那么企业正常运转","如果生产安全得到保障，那么员工遵守操作规程"],"answer":2,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果员工遵守操作规程，那么企业正常运转；其余选项均属无效推理。故选C。"},{"id":"pd-20573","module":"panduan","diff":1,"exam":"省考","prompt":"老李认为程序员都不善言辞，见到新同事小周是程序员，便断定他木讷寡言。刻板印象是指人们对某个群体形成概括而固定的看法，并把这种看法推及该群体中的每一个体。根据上述定义，下列同样属于刻板印象的是：","options":["有人一提到某地区的人就认为他们精明，不问具体是谁","小郑因某人一次失误而全盘否定他","小孙通过与每位同事逐一接触来了解他们","小吴与小李初次见面便觉得对方可靠"],"answer":0,"explanation":"刻板印象的要件是：针对群体的固定看法、不加区分地推及群体中的个体。「有人一提到某地区的人就认为他们精明，不问具体是谁」完全符合上述要件；其余选项分别存在以下问题：逐一了解个体情况，未把群体看法套到个体身上；由个体表现推及其整体，属于晕轮效应；初次见面形成的印象属于首因效应。故选A。"},{"id":"pd-20574","module":"panduan","diff":2,"exam":"国考","prompt":"如果广泛阅读，那么知识面拓宽；如果知识面拓宽，那么视野更加开阔。由此可以推出：","options":["如果没有广泛阅读，那么视野不够开阔","如果广泛阅读，那么视野更加开阔","如果知识面拓宽，那么广泛阅读","如果视野更加开阔，那么广泛阅读"],"answer":1,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果广泛阅读，那么视野更加开阔；其余选项均属无效推理。故选B。"},{"id":"pd-20575","module":"panduan","diff":1,"exam":"省考","prompt":"诚实：诚恳\n下列与题干词项逻辑关系最相近的是：","options":["演员：导演","溪水：流淌","心情：舒畅","贫穷：贫困"],"answer":3,"explanation":"题干「诚实」与「诚恳」为近义关系；「贫穷」与「贫困」也是近义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20576","module":"panduan","diff":1,"exam":"医疗编","prompt":"演员：导演\n下列与题干词项逻辑关系最相近的是：","options":["桌腿：桌子","鳞片：鱼","医生：作家","仔细：认真"],"answer":2,"explanation":"题干「演员」与「导演」为交叉关系；「医生」与「作家」也是交叉关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20577","module":"panduan","diff":2,"exam":"省考","prompt":"勤劳：懒惰\n下列与题干词项逻辑关系最相近的是：","options":["蝴蝶：昆虫","德国：柏林","局部：整体","梅：兰"],"answer":2,"explanation":"题干「勤劳」与「懒惰」为反义关系；「局部」与「整体」也是反义关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20578","module":"panduan","diff":3,"exam":"国考","prompt":"因工业园区建设，周边村庄逐步改造为街道，村民转为城镇居民。城市化是指人口向城镇集聚、乡村地区转变为城镇地区，城镇数量增加和规模扩大的过程。根据上述定义，下列同样属于城市化的是：","options":["城市居民利用假期到乡村度假","某乡实施农村危房改造，村容焕然一新","某村发展乡村旅游，村民收入提高但仍从事农业生产","某市近十年城镇人口占比从百分之四十升至百分之七十，新城区不断扩展"],"answer":3,"explanation":"城市化的要件是：人口向城镇集聚、乡村转变为城镇、城镇规模扩大。「某市近十年城镇人口占比从百分之四十升至百分之七十，新城区不断扩展」完全符合上述要件；其余选项分别存在以下问题：乡村发展未发生人口向城镇集聚；短期度假不是人口向城镇集聚；乡村建设未改变乡村性质。故选D。"},{"id":"pd-20579","module":"panduan","diff":2,"exam":"医疗编","prompt":"小陈、小杨、小吴、小周四人来自的城市各不相同，分别是北京、上海、广州、深圳。已知：小陈来自北京；小周来自广州；小周来自的城市不是深圳；小杨来自的城市不是广州；小杨来自的城市不是上海。由此可以推出，小杨来自：","options":["上海","广州","深圳","北京"],"answer":2,"explanation":"由题干条件逐一排除可得：小陈来自北京；小杨来自深圳；小吴来自上海；小周来自广州。因此小杨来自深圳。故选C。"},{"id":"pd-20580","module":"panduan","diff":3,"exam":"省考","prompt":"募捐者先请路人签名支持环保，路人签名后，再请其捐出少量善款，路人大多同意。登门槛效应是指一个人一旦接受了他人的一个微小要求后，为避免认知失调或给人前后一致的印象，更可能接受更大要求的现象。根据上述定义，下列同样属于登门槛效应的是：","options":["小钱断然拒绝了同事的大额借款请求","老师一次性布置了全部假期作业","推销员先请住户填写一份小问卷，住户答应后，又同意接受产品试用","经理直接要求员工完成高难度任务"],"answer":2,"explanation":"登门槛效应的要件是：先提出微小要求被接受、再提出更大要求、更大要求更易被接受。「推销员先请住户填写一份小问卷，住户答应后，又同意接受产品试用」完全符合上述要件；其余选项分别存在以下问题：没有先提出微小要求作为铺垫；拒绝了请求，未体现由小到大的递进；一次性提出要求，不存在渐进过程。故选C。"},{"id":"pd-20581","module":"panduan","diff":2,"exam":"国考","prompt":"灯泡：台灯\n下列与题干词项逻辑关系最相近的是：","options":["《雷雨》：曹禺","轮胎：汽车","轿车：汽车","明朝：朱元璋"],"answer":1,"explanation":"题干「灯泡」与「台灯」为组成关系；「轮胎」与「汽车」也是组成关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20582","module":"panduan","diff":2,"exam":"事业编","prompt":"学校将全部课时用于应试科目的反复训练。素质教育是指以提高受教育者多方面素质为目标的教育模式，注重德智体美劳全面发展，强调面向全体学生、促进个性发展。根据上述定义，下列不属于素质教育的是：","options":["学校组织学生参加志愿服务和劳动实践，培养多方面素质","某中学开设劳动、艺术、体育等课程，组织社会实践，注重学生全面发展和个性培养","小学开展社团活动，鼓励每个学生至少参加一项兴趣活动，促进多元发展","培训机构只针对考试科目突击提分"],"answer":3,"explanation":"素质教育的要件是：以提高多方面素质为目标、面向全体学生、促进全面发展与个性发展。「培训机构只针对考试科目突击提分」不符合要件：突击提分不属于素质教育；其余选项均符合素质教育的全部要件。故选D。"},{"id":"pd-20583","module":"panduan","diff":1,"exam":"省考","prompt":"只有水资源得到保护，才节约用水。现已确认节约用水。由此可以推出：","options":["水资源得不到保护","如果水资源得到保护，那么节约用水","只有节约用水，才水资源得到保护","水资源得到保护"],"answer":3,"explanation":"「只有水资源得到保护，才节约用水」中，水资源得到保护是节约用水的必要条件，肯定后件就要肯定前件。现已确认节约用水，属于肯定后件，故水资源得到保护必然成立，即水资源得到保护；肯定前件不能推出后件，其余选项均不能必然推出。故选D。"},{"id":"pd-20584","module":"panduan","diff":3,"exam":"国考","prompt":"班里发生了一件事：走廊里的盆栽被碰倒了。老师询问小陈、小杨、小吴、小郑四人，四人的说法如下：小陈说：“是小郑碰倒盆栽的。”；小杨说：“是小郑碰倒盆栽的。”；小吴说：“不是我碰倒盆栽的。”；小郑说：“不是我碰倒盆栽的。”。四人中只有3人说真话。由此可以推出，说假话的是：","options":["小郑","小吴","小陈","小杨"],"answer":0,"explanation":"只有一人说假话。逐一假设验证可知，小郑的话为假，其余三人的话均为真。故选A。"},{"id":"pd-20585","module":"panduan","diff":2,"exam":"省考","prompt":"某企业加大研发投入，凭借技术领先、质量过硬的产品赢得市场。正当竞争是指经营者遵守法律和商业道德，通过提高商品质量、降低成本、改进技术等正当手段开展竞争，以争取交易机会的行为。根据上述定义，下列同样属于正当竞争的是：","options":["某公司以低于成本的价格倾销商品，意图挤垮对手","某商家以质优价廉、服务周到吸引顾客，客流量稳步上升","某企业冒用他人注册商标销售自己的产品","某商家散布竞争对手产品质量有严重问题的虚假信息"],"answer":1,"explanation":"正当竞争的要件是：遵守法律和商业道德、采用正当手段、争取交易机会。「某商家以质优价廉、服务周到吸引顾客，客流量稳步上升」完全符合上述要件；其余选项分别存在以下问题：散布虚假信息属于商业诋毁，是不正当竞争；冒用注册商标违反法律和商业道德；低于成本倾销属于不正当竞争手段。故选B。"},{"id":"pd-20586","module":"panduan","diff":1,"exam":"事业编","prompt":"刘某为躲避债主催债，跳入他人鱼塘躲藏，造成大量鱼群死亡。紧急避险是指为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在发生的危险，不得已采取的损害另一较小合法权益的行为。根据上述定义，下列不属于紧急避险的是：","options":["货车刹车失灵冲下陡坡，司机为避免撞上人群，果断打方向盘撞向路边无人围墙","货轮遇特大风暴即将倾覆，船长下令抛货减损，保住了全船人员的安全","山洪冲向村庄，村干部组织挖开低洼空地引流，淹没了闲置农田却保住了村庄","陈某为省过路费，谎称车内装有危险品强行闯卡，撞坏道口栏杆"],"answer":3,"explanation":"紧急避险的要件是：危险正在发生、不得已而为之、损害的是另一较小合法权益。「陈某为省过路费，谎称车内装有危险品强行闯卡，撞坏道口栏杆」不符合要件：危险系本人虚构，并非真实存在的危险；其余选项均符合紧急避险的全部要件。故选D。"},{"id":"pd-20587","module":"panduan","diff":2,"exam":"省考","prompt":"有的店主是诚信经营者，所有的诚信经营者都是顾客信赖的商家。由此可以推出：","options":["所有的店主都是顾客信赖的商家","所有的顾客信赖的商家都是店主","有的店主不是顾客信赖的商家","有的店主是顾客信赖的商家"],"answer":3,"explanation":"有的店主是诚信经营者，而诚信经营者都属于顾客信赖的商家，所以这部分店主也属于顾客信赖的商家，即有的店主是顾客信赖的商家；不能扩大为全称结论，其余选项均不必然成立。故选D。"},{"id":"pd-20588","module":"panduan","diff":1,"exam":"事业编","prompt":"价格：波动\n下列与题干词项逻辑关系最相近的是：","options":["教师：学校","辽阔：草原","司机：方向盘","鲜花：绽放"],"answer":3,"explanation":"题干「价格」与「波动」为主谓关系；「鲜花」与「绽放」也是主谓关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20589","module":"panduan","diff":2,"exam":"省考","prompt":"某研究发现，经常喝咖啡的人患心脏病的比例更高，因此研究人员认为喝咖啡会导致心脏病。以下哪项如果为真，最能削弱上述论证？","options":["喝茶同样可能引起心悸等不适症状","有些人长期喝咖啡并没有患心脏病","心脏病患者往往遵医嘱减少咖啡摄入，不喝咖啡者中已患病者比例更高","咖啡的口感因人而异，有人喜欢有人不喜欢"],"answer":2,"explanation":"该项指出患心脏病才是减少喝咖啡的原因，属于因果倒置，直接动摇了原论证的因果链条。故选C。"},{"id":"pd-20590","module":"panduan","diff":1,"exam":"事业编","prompt":"某公司组织团建活动后，员工离职率明显下降，人力资源部认为是团建增强了员工归属感。以下哪项如果为真，最能削弱该结论？","options":["团建活动安排在周末进行","团建项目包括户外拓展和聚餐","同期公司普遍上调了薪酬，员工待遇明显改善","部分员工建议增加团建频次"],"answer":2,"explanation":"薪酬上调才是离职率下降的原因，属于另有他因，削弱了团建与归属感的因果联系。故选C。"},{"id":"pd-20591","module":"panduan","diff":2,"exam":"事业编","prompt":"所有的散文都是文学体裁，所有的文学体裁都是文学作品。由此可以推出：","options":["所有的散文都是文学作品","所有的文学作品都是散文","有的散文不是文学作品","有的文学作品不是散文"],"answer":0,"explanation":"三段论传递推理：散文都属于文学体裁，文学体裁都属于文学作品，所以所有的散文都是文学作品；其余选项不能必然推出。故选A。"},{"id":"pd-20592","module":"panduan","diff":1,"exam":"国考","prompt":"小孙通过与每位同事逐一接触来了解他们。刻板印象是指人们对某个群体形成概括而固定的看法，并把这种看法推及该群体中的每一个体。根据上述定义，下列不属于刻板印象的是：","options":["小郑因某人一次失误而全盘否定他","老李认为程序员都不善言辞，见到新同事小周是程序员，便断定他木讷寡言","小王认定学艺术的学生都不拘小节，见到学美术的新生便觉得他一定散漫","有人一提到某地区的人就认为他们精明，不问具体是谁"],"answer":0,"explanation":"刻板印象的要件是：针对群体的固定看法、不加区分地推及群体中的个体。「小郑因某人一次失误而全盘否定他」不符合要件：由个体表现推及其整体，属于晕轮效应；其余选项均符合刻板印象的全部要件。故选A。"},{"id":"pd-20593","module":"panduan","diff":1,"exam":"国考","prompt":"有专家认为，儿童多看教育类节目会更聪明，因为常看此类节目的儿童智力测试得分更高。以下哪项如果为真，最能削弱该专家的观点？","options":["有的儿童不喜欢看电视节目","智力测试的内容定期更新","高学历、重视教育的家长更有可能为孩子选择教育类节目","教育类节目的时长一般在半小时以内"],"answer":2,"explanation":"家长的教育背景才是孩子聪明且常看教育节目的共同原因，属于因果倒置。故选C。"},{"id":"pd-20594","module":"panduan","diff":2,"exam":"国考","prompt":"猪肉价格因疫情短期上涨后回落。通货膨胀是指在信用货币制度下，流通中的货币数量超过经济实际需要，导致物价总水平持续、普遍上涨的现象。根据上述定义，下列不属于通货膨胀的是：","options":["某景区旺季酒店价格上调","某经济体货币大幅贬值，从食品到房租各类价格水平持续攀升","某国货币供给远超实际需要，物价总水平连续两年普遍上涨","某国连年超发货币，市场上几乎所有商品价格持续上涨，货币购买力不断下降"],"answer":0,"explanation":"通货膨胀的要件是：货币超发、物价总水平上涨、持续且普遍。「某景区旺季酒店价格上调」不符合要件：个别行业季节性调价不是通货膨胀；其余选项均符合通货膨胀的全部要件。故选A。"},{"id":"pd-20595","module":"panduan","diff":1,"exam":"国考","prompt":"如果文件及时归档，那么查找资料方便。现已确认查找资料不便。由此可以推出：","options":["如果文件没有及时归档，那么查找资料不便","文件及时归档，尽管查找资料不便","文件及时归档","文件没有及时归档"],"answer":3,"explanation":"充分条件命题否定后件就要否定前件。由查找资料不便，可以推出文件没有及时归档；其余选项均不能由题干必然推出。故选D。"},{"id":"pd-20596","module":"panduan","diff":3,"exam":"国考","prompt":"小张、小王、小李、小赵四人的爱好各不相同，分别是游泳、跑步、读书、摄影。已知：小张的爱好不是读书；小赵的爱好不是摄影；小赵的爱好是读书；小李的爱好不是摄影；小张的爱好是游泳。由此可以推出，小李的爱好是：","options":["摄影","读书","跑步","游泳"],"answer":2,"explanation":"由题干条件逐一排除可得：小张的爱好是游泳；小王的爱好是摄影；小李的爱好是跑步；小赵的爱好是读书。因此小李的爱好是跑步。故选C。"},{"id":"pd-20597","module":"panduan","diff":2,"exam":"省考","prompt":"学校组织学生参加志愿服务和劳动实践，培养多方面素质。素质教育是指以提高受教育者多方面素质为目标的教育模式，注重德智体美劳全面发展，强调面向全体学生、促进个性发展。根据上述定义，下列同样属于素质教育的是：","options":["某中学开设劳动、艺术、体育等课程，组织社会实践，注重学生全面发展和个性培养","学校按分数给学生排名并分设快慢班","培训机构只针对考试科目突击提分","学校将全部课时用于应试科目的反复训练"],"answer":0,"explanation":"素质教育的要件是：以提高多方面素质为目标、面向全体学生、促进全面发展与个性发展。「某中学开设劳动、艺术、体育等课程，组织社会实践，注重学生全面发展和个性培养」完全符合上述要件；其余选项分别存在以下问题：唯应试训练与全面发展背道而驰；突击提分不属于素质教育；唯分数做法违背面向全体、全面发展的要求。故选A。"},{"id":"pd-20598","module":"panduan","diff":2,"exam":"事业编","prompt":"设计师在电脑中建模后，打印机将塑料逐层堆叠成型，制作出手办样品。三维打印是以数字模型文件为基础，通过逐层堆积材料的方式构造物体的增材制造技术。根据上述定义，下列同样属于三维打印的是：","options":["打印机在纸上打印平面图纸","工厂依据数字图纸，用金属粉末逐层烧结出结构复杂的零件","车床切削金属棒料加工出零件","注塑机用模具批量生产塑料杯"],"answer":1,"explanation":"三维打印的要件是：以数字模型为基础、逐层堆积材料、增材制造。「工厂依据数字图纸，用金属粉末逐层烧结出结构复杂的零件」完全符合上述要件；其余选项分别存在以下问题：切削属于减材制造，与逐层堆积相反；模具成型不是逐层堆积；平面打印未构造三维物体。故选B。"},{"id":"pd-20599","module":"panduan","diff":2,"exam":"国考","prompt":"学校发现设施损坏立即修缮，校园秩序始终保持良好。破窗效应是指环境中的不良现象若被放任存在，会诱使人们仿效，甚至变本加厉。根据上述定义，下列不属于破窗效应的是：","options":["社区组织志愿者定期清理小广告，墙面保持整洁","墙面出现第一张小广告无人清理，很快贴满整面墙","厂区一角有人随手扔了垃圾无人管，渐渐地那片空地堆满了杂物","小区一面窗户破损长期无人修，不久后更多窗户被打破，楼道垃圾也多了起来"],"answer":0,"explanation":"破窗效应的要件是：不良现象被放任存在、诱发更多人仿效、情况加剧。「社区组织志愿者定期清理小广告，墙面保持整洁」不符合要件：及时清理切断了不良现象的示范作用；其余选项均符合破窗效应的全部要件。故选A。"},{"id":"pd-20600","module":"panduan","diff":2,"exam":"国考","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问小赵、小钱、小孙、小周四人，四人的说法如下：小赵说：“不是我拿走钥匙的。”；小钱说：“是小赵拿走钥匙的。”；小孙说：“不是我拿走钥匙的。”；小周说：“是小赵拿走钥匙的。”。四人中只有1人说真话。由此可以推出，拿走钥匙的是：","options":["小赵","小周","小钱","小孙"],"answer":3,"explanation":"只有一人说真话。逐一假设验证：只有假设小孙拿走钥匙时，四句话中为真的才恰好1句，符合题干条件，故小孙拿走钥匙。故选D。"},{"id":"pd-20601","module":"panduan","diff":2,"exam":"国考","prompt":"护士：注射器\n下列与题干词项逻辑关系最相近的是：","options":["楷书：书法字体","望梅止渴：曹操","负荆请罪：廉颇","摄影师：相机"],"answer":3,"explanation":"题干「护士」与「注射器」为职业与其专用工具的对应；「摄影师」与「相机」也是职业与其专用工具的对应，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20602","module":"panduan","diff":1,"exam":"国考","prompt":"班里发生了一件事：教室里的花瓶被打碎了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“是乙打碎花瓶的。”；乙说：“是丁打碎花瓶的。”；丙说：“是乙打碎花瓶的。”；丁说：“是乙打碎花瓶的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["乙","丁","丙","甲"],"answer":0,"explanation":"只有一人说真话。逐一假设验证可知，乙的话为真，其余三人的话均为假。故选A。"},{"id":"pd-20603","module":"panduan","diff":2,"exam":"国考","prompt":"小陈、小杨、小吴、小周四人的特长各不相同，分别是书法、绘画、围棋、古琴。已知：小杨的特长不是书法；小陈的特长是书法；小陈的特长不是绘画；小杨的特长是古琴；小周的特长是绘画。由此可以推出，小吴的特长是：","options":["古琴","书法","绘画","围棋"],"answer":3,"explanation":"由题干条件逐一排除可得：小陈的特长是书法；小杨的特长是古琴；小吴的特长是围棋；小周的特长是绘画。因此小吴的特长是围棋。故选D。"},{"id":"pd-20604","module":"panduan","diff":2,"exam":"国考","prompt":"县医院通过视频连线请省城专家为患者远程会诊并调整治疗方案。远程医疗是指医疗机构通过通信技术为异地患者提供诊疗指导等医疗服务的方式。根据上述定义，下列同样属于远程医疗的是：","options":["医院电话通知患者复诊的具体时间","患者乘火车到邻市医院当面就诊","边远地区患者通过远程平台获得上级医院医生的诊疗意见","药店向顾客销售非处方药品"],"answer":2,"explanation":"远程医疗的要件是：医疗机构借助通信技术、为异地患者、提供诊疗服务。「边远地区患者通过远程平台获得上级医院医生的诊疗意见」完全符合上述要件；其余选项分别存在以下问题：当面就诊未借助通信技术远程实施；事务性通知不属于诊疗服务；药店售药不属于医疗机构诊疗行为。故选C。"},{"id":"pd-20605","module":"panduan","diff":2,"exam":"事业编","prompt":"同一航班同一舱位，提前一个月购票三百元，临起飞购票一千五百元。价格歧视是指经营者对相同的商品或服务，向不同的购买者收取不同价格的行为，且这种价格差异并非基于成本差异。根据上述定义，下列同样属于价格歧视的是：","options":["视频网站对同一部影片，学生会员半价，普通会员全价","超市对临期食品打折促销","批发价低于零售价","航空公司头等舱票价高于经济舱"],"answer":0,"explanation":"价格歧视的要件是：相同商品或服务、不同购买者、价格差异并非源于成本差异。「视频网站对同一部影片，学生会员半价，普通会员全价」完全符合上述要件；其余选项分别存在以下问题：舱位服务与成本不同，不属于相同商品；商品状态不同，价格差异基于商品差异；批发与零售在包装、服务成本上存在差异。故选A。"},{"id":"pd-20606","module":"panduan","diff":2,"exam":"省考","prompt":"连锁企业精简区域管理机构，门店店长可直接与总部沟通。扁平化管理是指减少管理层级、扩大管理幅度，使组织结构趋于扁平的管理模式。根据上述定义，下列同样属于扁平化管理的是：","options":["公司扩大招聘规模，员工总数翻倍","公司增设多个管理层级，逐级审批","公司调整了工资结构","公司将原来的七个管理层级压缩为三级，一线员工可直接向总监汇报"],"answer":3,"explanation":"扁平化管理的要件是：减少管理层级、扩大管理幅度。「公司将原来的七个管理层级压缩为三级，一线员工可直接向总监汇报」完全符合上述要件；其余选项分别存在以下问题：层级增加与扁平化方向相反；人员规模变化不等于层级变化；薪酬调整与组织层级无关。故选D。"},{"id":"pd-20607","module":"panduan","diff":1,"exam":"国考","prompt":"棒球：球类运动\n下列与题干词项逻辑关系最相近的是：","options":["厨师：炒勺","画家：教师","楷书：书法字体","山东：济南"],"answer":2,"explanation":"题干「棒球」与「球类运动」为种属包含关系；「楷书」与「书法字体」也是种属包含关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20608","module":"panduan","diff":3,"exam":"国考","prompt":"所有的狮子都是猫科动物，所有的猫科动物都是哺乳动物。由此可以推出：","options":["所有的狮子都是哺乳动物","所有的哺乳动物都是狮子","有的哺乳动物不是狮子","有的狮子不是哺乳动物"],"answer":0,"explanation":"三段论传递推理：狮子都属于猫科动物，猫科动物都属于哺乳动物，所以所有的狮子都是哺乳动物；其余选项不能必然推出。故选A。"},{"id":"pd-20609","module":"panduan","diff":1,"exam":"省考","prompt":"班里发生了一件事：走廊里的盆栽被碰倒了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“是丁碰倒盆栽的。”；乙说：“是丁碰倒盆栽的。”；丙说：“是丁碰倒盆栽的。”；丁说：“是甲碰倒盆栽的。”。四人中只有1人说真话。由此可以推出，碰倒盆栽的是：","options":["甲","丙","丁","乙"],"answer":0,"explanation":"只有一人说真话。逐一假设验证：只有假设甲碰倒盆栽时，四句话中为真的才恰好1句，符合题干条件，故甲碰倒盆栽。故选A。"},{"id":"pd-20610","module":"panduan","diff":1,"exam":"国考","prompt":"并非（考生答题规范并且不必要的失分减少）。由此可以推出：","options":["考生答题规范或者不必要的失分减少","考生答题不规范并且不必要的失分没有减少","如果考生答题不规范，那么不必要的失分减少","考生答题不规范或者不必要的失分没有减少"],"answer":3,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（考生答题规范并且不必要的失分减少），等值于“考生答题不规范或者不必要的失分没有减少”；其余选项均不符合德摩根定律。故选D。"},{"id":"pd-20611","module":"panduan","diff":1,"exam":"国考","prompt":"《西游记》：吴承恩\n下列与题干词项逻辑关系最相近的是：","options":["书页：书本","《红楼梦》：曹雪芹","山东：济南","理论：实践"],"answer":1,"explanation":"题干「《西游记》」与「吴承恩」为作品与其作者的对应；「《红楼梦》」与「曹雪芹」也是作品与其作者的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20612","module":"panduan","diff":2,"exam":"省考","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问小陈、小杨、小吴、小郑四人，四人的说法如下：小陈说：“是小杨拿走钥匙的。”；小杨说：“不是我拿走钥匙的。”；小吴说：“是小杨拿走钥匙的。”；小郑说：“不是我拿走钥匙的。”。四人中只有3人说真话。由此可以推出，拿走钥匙的是：","options":["小郑","小陈","小杨","小吴"],"answer":2,"explanation":"只有三人说假话。逐一假设验证：只有假设小杨拿走钥匙时，四句话中为假的才恰好3句，符合题干条件，故小杨拿走钥匙。故选C。"},{"id":"pd-20613","module":"panduan","diff":1,"exam":"事业编","prompt":"只有肠胃健康，才饮食规律。现已确认饮食规律。由此可以推出：","options":["如果肠胃健康，那么饮食规律","肠胃不健康","只有饮食规律，才肠胃健康","肠胃健康"],"answer":3,"explanation":"「只有肠胃健康，才饮食规律」中，肠胃健康是饮食规律的必要条件，肯定后件就要肯定前件。现已确认饮食规律，属于肯定后件，故肠胃健康必然成立，即肠胃健康；肯定前件不能推出后件，其余选项均不能必然推出。故选D。"},{"id":"pd-20614","module":"panduan","diff":2,"exam":"事业编","prompt":"有的村民是种植果树的人，所有的种植果树的人都是收入提高的人。由此可以推出：","options":["所有的村民都是收入提高的人","有的村民是收入提高的人","有的村民不是收入提高的人","所有的收入提高的人都是村民"],"answer":1,"explanation":"有的村民是种植果树的人，而种植果树的人都属于收入提高的人，所以这部分村民也属于收入提高的人，即有的村民是收入提高的人；不能扩大为全称结论，其余选项均不必然成立。故选B。"},{"id":"pd-20615","module":"panduan","diff":2,"exam":"事业编","prompt":"某研究显示，每天使用手机时间长的青少年近视率更高，因此研究人员认为使用手机导致近视。以下哪项如果为真，最能削弱该结论？","options":["已经近视的青少年看不清屏幕，往往需要更长时间凑近使用手机","手机屏幕的尺寸各不相同","有的青少年使用手机时间不长也近视了","青少年普遍喜欢玩手机游戏"],"answer":0,"explanation":"近视才是长时间使用手机的原因，属于因果倒置，动摇了原结论。故选A。"},{"id":"pd-20616","module":"panduan","diff":2,"exam":"医疗编","prompt":"小赵多次数学考试不及格后，即使题目很简单也不再尝试作答，认为自己天生学不会。习得性无助是指个体经历反复失败或挫折后，感到一切都无法控制，从而产生无能为力、放弃努力的心理状态。根据上述定义，下列同样属于习得性无助的是：","options":["小吴第一次学游泳呛水，有些害怕但仍坚持练习","小孙因身体不适暂停训练，康复后继续投入","小钱考试失利后总结教训，加倍努力备考","老周多次求职被拒后，不再投递简历，觉得努力也没用"],"answer":3,"explanation":"习得性无助的要件是：反复失败或挫折、感到无法控制、放弃努力。「老周多次求职被拒后，不再投递简历，觉得努力也没用」完全符合上述要件；其余选项分别存在以下问题：失败后积极归因并加倍努力，与放弃努力相反；初次挫折后仍坚持尝试，未形成无助感；暂停训练有客观原因，并非放弃努力。故选D。"},{"id":"pd-20617","module":"panduan","diff":3,"exam":"事业编","prompt":"某高校图书馆借阅量逐年下降，馆长认为是电子书普及导致学生不来借书。以下哪项如果为真，最能削弱馆长的判断？","options":["图书馆近年开放时间缩短了一半，很多学生想借书却无法进馆","电子书阅读器价格不断下降","图书馆的藏书种类仍然丰富","该校学生总数保持稳定"],"answer":0,"explanation":"开放时间缩短导致学生无法借书，说明借阅量下降另有原因，属于另有他因。故选A。"},{"id":"pd-20618","module":"panduan","diff":1,"exam":"省考","prompt":"某市禁止燃放烟花爆竹后空气质量明显改善，环保部门认为是禁放措施改善了空气。以下哪项如果为真，最能削弱环保部门的结论？","options":["该市加强了烟花爆竹的销售管理","部分市民对禁放规定表示支持","禁放规定发布前进行了广泛宣传","同期该市多家高污染工厂停产检修，污染物排放大幅减少"],"answer":3,"explanation":"工厂停产才是空气改善的主要原因，属于另有他因，削弱了禁放与空气改善的因果联系。故选D。"},{"id":"pd-20619","module":"panduan","diff":1,"exam":"省考","prompt":"消防演练中大家有序撤离，小陈按照预案行动。从众是指个体在群体压力下，放弃自己的意见或行为，而采取与大多数人一致的意见或行为的现象。根据上述定义，下列不属于从众的是：","options":["看到街边很多人排队购买某奶茶，本来不想喝的小吴也跟着排起了队","小钱主动向先进典型学习，坚持每天早起锻炼","讨论会上见多数人都支持方案二，小郑虽心有疑虑，最终也投了赞成票","会议室里大家都举手赞成，原本持反对意见的小周见状也默默举起了手"],"answer":1,"explanation":"从众的要件是：存在群体压力、个体放弃己见、采取与多数人一致的行为。「小钱主动向先进典型学习，坚持每天早起锻炼」不符合要件：榜样学习是主动模仿，不是群体压力所致；其余选项均符合从众的全部要件。故选B。"},{"id":"pd-20620","module":"panduan","diff":2,"exam":"国考","prompt":"摄影师：相机\n下列与题干词项逻辑关系最相近的是：","options":["拉面：兰州","鳞片：鱼","农民：锄头","洗衣机：家电"],"answer":2,"explanation":"题干「摄影师」与「相机」为职业与其专用工具的对应；「农民」与「锄头」也是职业与其专用工具的对应，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20621","module":"panduan","diff":1,"exam":"国考","prompt":"商量：商议\n下列与题干词项逻辑关系最相近的是：","options":["开始：结束","松树：树木","稀少：罕见","冰箱：家电"],"answer":2,"explanation":"题干「商量」与「商议」为近义关系；「稀少」与「罕见」也是近义关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20622","module":"panduan","diff":2,"exam":"事业编","prompt":"某公司向合作方发出订单：订购某型号水泥200吨，单价及交货时间均已明确。要约是希望与他人订立合同的意思表示，内容具体确定，并表明经受要约人承诺，要约人即受该意思表示约束。根据上述定义，下列同样属于要约的是：","options":["某公司发布广告称：本月商品一律八折，欢迎选购","甲公司向乙公司发函：愿以每吨5000元购买钢材100吨，10日内答复有效","甲公司向乙公司询问：你们的水泥多少钱一吨","钱某与朋友闲聊时说真想买辆车，未提任何具体条件"],"answer":1,"explanation":"要约的要件是：内容具体确定、表明经承诺即受约束、向希望缔约的相对人发出。「甲公司向乙公司发函：愿以每吨5000元购买钢材100吨，10日内答复有效」完全符合上述要件；其余选项分别存在以下问题：商业广告内容不具体，属于要约邀请；意思表示内容不具体确定；询价行为不含有订立合同的确定意思。故选B。"},{"id":"pd-20623","module":"panduan","diff":1,"exam":"省考","prompt":"某地区通过测算发现居民收入差距缩小，基尼系数下降。基尼系数是衡量收入分配公平程度的指标，数值介于零和一之间，数值越大表示收入差距越大。根据上述定义，下列同样属于基尼系数的是：","options":["某家庭收入明显增加","某国物价指数持续上涨","某地区失业率上升","某国收入高度集中于少数人手中，基尼系数接近零点六"],"answer":3,"explanation":"基尼系数的要件是：衡量收入分配差距、数值越大差距越大。「某国收入高度集中于少数人手中，基尼系数接近零点六」完全符合上述要件；其余选项分别存在以下问题：物价指数衡量价格水平，与收入分配无关；个体收入变化不能反映整体收入差距；失业率衡量就业状况，不是收入分配指标。故选D。"},{"id":"pd-20624","module":"panduan","diff":3,"exam":"省考","prompt":"孤独：寂寞\n下列与题干词项逻辑关系最相近的是：","options":["瓶盖：瓶子","袖子：衣服","吝啬：大方","坚强：顽强"],"answer":3,"explanation":"题干「孤独」与「寂寞」为近义关系；「坚强」与「顽强」也是近义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20625","module":"panduan","diff":1,"exam":"国考","prompt":"医生建议某药物在餐后服用，认为这样疗效更好。以下哪项如果为真，最能支持医生的建议？","options":["部分患者习惯清晨服药","该药物需要长期规律服用","临床数据显示，餐后服用该药的患者血药浓度更高，症状缓解更快","该药物的价格较为适中"],"answer":2,"explanation":"血药浓度与疗效数据直接支持餐后服用疗效更好的结论。故选C。"},{"id":"pd-20626","module":"panduan","diff":2,"exam":"国考","prompt":"园林专家认为，应当禁止在古树周边施工，以保护古树。上述论证最可能基于的前提是：","options":["古树具有较高的观赏价值","施工会产生噪音","古树已挂牌保护","周边施工会损害古树的根系等生长条件"],"answer":3,"explanation":"只有施工确实危害古树生存，禁止施工才能达到保护目的，该项是论证的必要前提。故选D。"},{"id":"pd-20627","module":"panduan","diff":2,"exam":"事业编","prompt":"所有的哈士奇都是犬类，所有的猫都不是犬类。由此可以推出：","options":["所有的猫都不是哈士奇","有的哈士奇是猫","所有的猫都是哈士奇","有的猫是哈士奇"],"answer":0,"explanation":"哈士奇都包含于犬类，而猫与犬类完全排斥，所以猫与哈士奇也完全排斥，即所有的猫都不是哈士奇；其余选项与题干矛盾或不能必然推出。故选A。"},{"id":"pd-20628","module":"panduan","diff":3,"exam":"医疗编","prompt":"总经理单方面下达指令，要求各部门必须完成规定产量。目标管理是指组织中的上级与下级一起共同制定目标，使组织目标与个人目标紧密结合，并以目标完成情况作为考核依据的管理方法。根据上述定义，下列不属于目标管理的是：","options":["车间主任与工人共同确定月度生产目标，并按完成情况评定绩效","某公司年初由部门经理与员工共同商定年度目标，年底按目标完成情况考核奖惩","公司按员工出勤天数发放工资","项目部与每位成员协商确定季度任务指标，并据此定期检查进度"],"answer":2,"explanation":"目标管理的要件是：上下级共同制定目标、目标与个人结合、以目标完成情况考核。「公司按员工出勤天数发放工资」不符合要件：考核依据是出勤而非目标完成情况；其余选项均符合目标管理的全部要件。故选C。"},{"id":"pd-20629","module":"panduan","diff":2,"exam":"国考","prompt":"某测试车辆依靠激光雷达和摄像头感知路况，自动变道、避让行人并按导航行驶，全程无驾驶员操作。无人驾驶是指车辆在没有人为操作干预的情况下，依靠传感器感知环境、自动规划路线并控制行驶的技术。根据上述定义，下列同样属于无人驾驶的是：","options":["儿童用遥控器操控玩具车行驶","司机使用定速巡航功能保持车速","园区内无人配送车自动规划路线，将包裹送达指定楼栋","倒车影像辅助司机完成泊车"],"answer":2,"explanation":"无人驾驶的要件是：无人为操作干预、传感器感知环境、自动规划并控制行驶。「园区内无人配送车自动规划路线，将包裹送达指定楼栋」完全符合上述要件；其余选项分别存在以下问题：定速巡航仅辅助驾驶，仍需人为操作；泊车由司机完成，影像只是辅助；遥控行驶由人为操控，不具自主性。故选C。"},{"id":"pd-20630","module":"panduan","diff":1,"exam":"医疗编","prompt":"管理员手工录入设备台账。物联网是指通过传感设备，按约定的协议把物品与网络连接起来，进行信息交换和通信，以实现智能化识别、定位、跟踪、监控和管理的技术。根据上述定义，下列不属于物联网的是：","options":["农田里的传感器实时采集土壤温湿度并自动联网上报，系统据此远程控制灌溉","电视机通过U盘播放影片","物流公司为货物加装定位装置，全程联网跟踪货物位置","小区智能水表自动将用水数据传输至水务平台，实现远程抄表"],"answer":1,"explanation":"物联网的要件是：物品通过传感设备联网、按协议通信、实现智能识别监控管理。「电视机通过U盘播放影片」不符合要件：未联网，不涉及信息交换与通信；其余选项均符合物联网的全部要件。故选B。"},{"id":"pd-20631","module":"panduan","diff":3,"exam":"省考","prompt":"学校通过云平台为师生提供在线存储和课件服务，随需求扩容。云计算是指通过网络以按需、易扩展的方式获取计算资源（服务器、存储、软件等）的服务模式，用户无需自建基础设施。根据上述定义，下列同样属于云计算的是：","options":["小李将文件拷贝到自己的移动硬盘保存","公司自建机房并配备专职运维团队","某企业租用云端计算资源完成大规模数据运算，按用量付费","单位在内网搭建共享文件夹供同事下载"],"answer":2,"explanation":"云计算的要件是：通过网络按需获取计算资源、无需自建基础设施、易扩展。「某企业租用云端计算资源完成大规模数据运算，按用量付费」完全符合上述要件；其余选项分别存在以下问题：自建基础设施与云计算模式相反；本地存储未通过网络按需获取资源；局域网共享不属于按需获取云端计算资源。故选C。"},{"id":"pd-20632","module":"panduan","diff":1,"exam":"国考","prompt":"负荆请罪：廉颇\n下列与题干词项逻辑关系最相近的是：","options":["局势：稳定","凿壁偷光：匡衡","缓慢：迅速","《水浒传》：施耐庵"],"answer":1,"explanation":"题干「负荆请罪」与「廉颇」为成语典故与其主人公的对应；「凿壁偷光」与「匡衡」也是成语典故与其主人公的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20633","module":"panduan","diff":3,"exam":"国考","prompt":"稀少：罕见\n下列与题干词项逻辑关系最相近的是：","options":["蜜蜂：采蜜","羽毛：鸟","优良：传统","聪明：睿智"],"answer":3,"explanation":"题干「稀少」与「罕见」为近义关系；「聪明」与「睿智」也是近义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20634","module":"panduan","diff":3,"exam":"省考","prompt":"打击：攻击\n下列与题干词项逻辑关系最相近的是：","options":["楷书：书法字体","骄傲：谦虚","一律：全部","冷漠：热情"],"answer":2,"explanation":"题干「打击」与「攻击」为近义关系；「一律」与「全部」也是近义关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20635","module":"panduan","diff":1,"exam":"事业编","prompt":"韩国：首尔\n下列与题干词项逻辑关系最相近的是：","options":["元朝：忽必烈","崎岖：山路","英国：伦敦","改善：生活"],"answer":2,"explanation":"题干「韩国」与「首尔」为国家与其首都的对应；「英国」与「伦敦」也是国家与其首都的对应，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20636","module":"panduan","diff":2,"exam":"医疗编","prompt":"小陈、小杨、小吴、小周、小孙五人比较跑步速度。已知：小陈比小孙快；小陈比小杨快；小吴比小杨快；小吴比小周快；小吴不是最快的。这五人的跑步速度从快到慢排序，谁排第一？","options":["小杨","小吴","小孙","小陈"],"answer":3,"explanation":"由题干条件逐步推理，可得五人跑步速度从快到慢的完整排序为：小陈＞小吴＞小周＞小杨＞小孙。因此排第一的是小陈。故选D。"},{"id":"pd-20637","module":"panduan","diff":2,"exam":"国考","prompt":"班里发生了一件事：刚拖过的地面被踩脏了。老师询问小王、小李、小张、小刘四人，四人的说法如下：小王说：“不是我踩脏地面的。”；小李说：“是小张踩脏地面的。”；小张说：“是小王踩脏地面的。”；小刘说：“不是我踩脏地面的。”。四人中只有3人说真话。由此可以推出，说假话的是：","options":["小刘","小王","小张","小李"],"answer":2,"explanation":"只有一人说假话。逐一假设验证可知，小张的话为假，其余三人的话均为真。故选C。"},{"id":"pd-20638","module":"panduan","diff":2,"exam":"事业编","prompt":"小张、小王、小李、小赵四人来自的城市各不相同，分别是北京、上海、广州、深圳。已知：小李来自的城市是广州；小张来自的城市不是深圳；小王来自的城市不是深圳；小王来自的城市不是北京。由此可以推出，小张来自的城市是：","options":["深圳","上海","广州","北京"],"answer":3,"explanation":"由题干条件逐一排查：小李来自广州；小张不来自深圳；小王不来自深圳；小王不来自北京。结合四人城市各不相同，可唯一确定小张来自北京。故选D。"},{"id":"pd-20639","module":"panduan","diff":3,"exam":"国考","prompt":"小钱买手机花四千元，比上月贵了五百元。消费者剩余是指消费者愿意支付的最高价格与实际支付价格之间的差额。根据上述定义，下列不属于消费者剩余的是：","options":["小赵原本打算以标价购买图书，结账时恰逢满减，实际少付了三十元","企业以低于成本的价格清仓库存","老王愿以每斤二十元购买樱桃，市场上只卖十二元","小李愿意花三千元购买耳机，恰逢促销只花一千八百元买到"],"answer":1,"explanation":"消费者剩余的要件是：存在支付意愿价格、实际支付更低、二者差额构成剩余。「企业以低于成本的价格清仓库存」不符合要件：清仓定价与企业成本的关系不构成消费者支付意愿差额；其余选项均符合消费者剩余的全部要件。故选B。"},{"id":"pd-20640","module":"panduan","diff":1,"exam":"国考","prompt":"老虎：哺乳动物\n下列与题干词项逻辑关系最相近的是：","options":["生存：死亡","《西游记》：吴承恩","廉价：昂贵","白酒：酒类"],"answer":3,"explanation":"题干「老虎」与「哺乳动物」为种属包含关系；「白酒」与「酒类」也是种属包含关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20641","module":"panduan","diff":3,"exam":"国考","prompt":"提高：降低\n下列与题干词项逻辑关系最相近的是：","options":["高兴：悲伤","明亮：敞亮","背水一战：韩信","梅：兰"],"answer":0,"explanation":"题干「提高」与「降低」为反义关系；「高兴」与「悲伤」也是反义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20642","module":"panduan","diff":2,"exam":"省考","prompt":"流水线机械臂按预设动作重复搬运货物。人工智能是指用计算机系统模拟、延伸和扩展人类的智能活动，使其能够学习、推理、决策并完成通常需要人类智能才能完成的任务的技术。根据上述定义，下列不属于人工智能的是：","options":["某系统通过大量对局自我学习，棋力不断提升，战胜了人类顶尖棋手","某软件通过学习数万份病历，能够辅助医生对影像进行病变识别并给出诊断建议","电子表格软件自动对数据求和","智能音箱能理解用户的语音指令，与用户对话并推荐歌曲"],"answer":2,"explanation":"人工智能的要件是：计算机系统、模拟人类智能、具备学习推理决策能力。「电子表格软件自动对数据求和」不符合要件：自动求和是固定功能，不涉及智能活动；其余选项均符合人工智能的全部要件。故选C。"},{"id":"pd-20643","module":"panduan","diff":2,"exam":"事业编","prompt":"如果项目验收合格，那么团队获得奖金。现已确认团队没获得奖金。由此可以推出：","options":["如果项目验收不合格，那么团队没获得奖金","项目验收合格，尽管团队没获得奖金","项目验收合格","项目验收不合格"],"answer":3,"explanation":"充分条件命题否定后件就要否定前件。由团队没获得奖金，可以推出项目验收不合格；其余选项均不能由题干必然推出。故选D。"},{"id":"pd-20644","module":"panduan","diff":1,"exam":"国考","prompt":"公司扩大招聘规模，员工总数翻倍。扁平化管理是指减少管理层级、扩大管理幅度，使组织结构趋于扁平的管理模式。根据上述定义，下列不属于扁平化管理的是：","options":["公司调整了工资结构","连锁企业精简区域管理机构，门店店长可直接与总部沟通","某互联网企业取消中间管理层，实行项目小组直接对决策层负责","公司将原来的七个管理层级压缩为三级，一线员工可直接向总监汇报"],"answer":0,"explanation":"扁平化管理的要件是：减少管理层级、扩大管理幅度。「公司调整了工资结构」不符合要件：薪酬调整与组织层级无关；其余选项均符合扁平化管理的全部要件。故选A。"},{"id":"pd-20645","module":"panduan","diff":2,"exam":"国考","prompt":"小陈、小杨、小吴、小周、小孙五人比较体重。已知：小周比小陈重；小周比小孙重；小孙比小吴重；小杨比小周重；小周不是最重的。这五人的体重从重到轻排序，谁排第二？","options":["小吴","小孙","小周","小陈"],"answer":2,"explanation":"由题干条件逐步推理，可得五人体重从重到轻的完整排序为：小杨＞小周＞小陈＞小孙＞小吴。因此排第二的是小周。故选C。"},{"id":"pd-20646","module":"panduan","diff":2,"exam":"国考","prompt":"老李年轻时读夜校学技术，中年参加行业培训，退休后仍坚持上网课。终身教育是指人们在一生各阶段中所受各种教育的总和，包括正规教育与非正规教育，贯穿人的一生。根据上述定义，下列同样属于终身教育的是：","options":["公司为新员工组织入职培训","小学生按照课表上课","退休后的老周报名老年大学学习书法，此前他也参加过单位组织的各类培训","小赵全日制读完本科后便停止了学习"],"answer":2,"explanation":"终身教育的要件是：贯穿一生各阶段、包括正规与非正规教育。「退休后的老周报名老年大学学习书法，此前他也参加过单位组织的各类培训」完全符合上述要件；其余选项分别存在以下问题：仅接受某一阶段教育，未贯穿一生；仅属正规教育的一个片段；单一阶段的培训不构成终身教育。故选C。"},{"id":"pd-20647","module":"panduan","diff":3,"exam":"国考","prompt":"钥匙：开锁\n下列与题干词项逻辑关系最相近的是：","options":["桥墩：桥梁","瓶盖：瓶子","眼镜：矫正视力","江：河"],"answer":2,"explanation":"题干「钥匙」与「开锁」为事物与其功能的对应；「眼镜」与「矫正视力」也是事物与其功能的对应，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20648","module":"panduan","diff":2,"exam":"事业编","prompt":"如果坚持储蓄，那么积蓄增加；如果积蓄增加，那么抗风险能力增强。由此可以推出：","options":["如果抗风险能力增强，那么坚持储蓄","如果积蓄增加，那么坚持储蓄","如果坚持储蓄，那么抗风险能力增强","如果没有坚持储蓄，那么抗风险能力没有增强"],"answer":2,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果坚持储蓄，那么抗风险能力增强；其余选项均属无效推理。故选C。"},{"id":"pd-20649","module":"panduan","diff":2,"exam":"国考","prompt":"生态学家认为，恢复湿地能够吸引候鸟栖息。以下哪项如果为真，最能支持该观点？","options":["湿地具有净化水质的功能","候鸟迁徙路线相对固定","湿地修复完成后的越冬季，到此栖息的候鸟种类和数量均创近年新高","当地加强了观鸟设施建设"],"answer":2,"explanation":"修复后候鸟种类数量创新高，直接证明恢复湿地能吸引候鸟栖息。故选C。"},{"id":"pd-20650","module":"panduan","diff":2,"exam":"事业编","prompt":"雨伞：遮雨\n下列与题干词项逻辑关系最相近的是：","options":["农民：田间","谦虚：虚心","手电筒：照明","江：河"],"answer":2,"explanation":"题干「雨伞」与「遮雨」为事物与其功能的对应；「手电筒」与「照明」也是事物与其功能的对应，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20651","module":"panduan","diff":3,"exam":"教师编","prompt":"某培训机构宣称其培训效果显著，因为其学员的考试通过率远高于平均水平。以下哪项如果为真，最能削弱该宣称？","options":["该机构入学筛选严格，录取的学员本身基础就明显好于平均水平","该机构的上课地点交通便利","该机构聘请了经验丰富的授课教师","该机构的培训费用高于同类机构"],"answer":0,"explanation":"学员基础好才是通过率高的原因，属于另有他因，削弱了培训与通过率之间的因果联系。故选A。"},{"id":"pd-20652","module":"panduan","diff":1,"exam":"省考","prompt":"小张因好友极力推荐而对某人产生好感。首因效应是指交往双方形成的第一次印象对今后交往关系的影响，即先入为主带来的效果。根据上述定义，下列不属于首因效应的是：","options":["新老师第一次上课妙语连珠，学生此后一直认为他学识渊博","小陈最近一次表现出色，大家改变了对他的原有看法","面试中小李衣着得体、谈吐从容，面试官虽未细看简历，已对其留下能干的好印象","小赵与新同事初次见面时热情周到，同事此后对他印象颇佳"],"answer":1,"explanation":"首因效应的要件是：第一次接触、第一印象、对后续交往产生持续影响。「小陈最近一次表现出色，大家改变了对他的原有看法」不符合要件：最近表现改变印象属于近因效应；其余选项均符合首因效应的全部要件。故选B。"},{"id":"pd-20653","module":"panduan","diff":2,"exam":"国考","prompt":"小张、小王、小李、小赵四人的养的宠物各不相同，分别是猫、狗、鸟、鱼。已知：小王的养的宠物不是鸟；小赵的养的宠物是鱼；小李的养的宠物不是鱼；小李的养的宠物是狗。由此可以推出，小张的养的宠物是：","options":["鱼","鸟","狗","猫"],"answer":1,"explanation":"由题干条件逐一排除可得：小张的养的宠物是鸟；小王的养的宠物是猫；小李的养的宠物是狗；小赵的养的宠物是鱼。因此小张的养的宠物是鸟。故选B。"},{"id":"pd-20654","module":"panduan","diff":3,"exam":"国考","prompt":"某公司以行业龙头企业的服务流程为参照，逐项对比找出差距并改进。标杆管理是指企业以行业内外最优秀者为基准，将其产品、服务或管理实践与本企业对比、分析、学习，从而改进提高的过程。根据上述定义，下列同样属于标杆管理的是：","options":["医院组织团队赴全国最佳同行学习其护理管理模式，结合实际加以优化","企业聘请顾问提出改进建议","企业根据自身历史数据设定增长目标","公司对员工进行绩效排名"],"answer":0,"explanation":"标杆管理的要件是：以最优秀者为基准、对比分析、学习改进。「医院组织团队赴全国最佳同行学习其护理管理模式，结合实际加以优化」完全符合上述要件；其余选项分别存在以下问题：与自身历史对比，未以最优秀者为基准；绩效排名不涉及向标杆学习；外部咨询不是以标杆为基准的对比学习。故选A。"},{"id":"pd-20655","module":"panduan","diff":3,"exam":"教师编","prompt":"小学生按照课表上课。终身教育是指人们在一生各阶段中所受各种教育的总和，包括正规教育与非正规教育，贯穿人的一生。根据上述定义，下列不属于终身教育的是：","options":["在职教师利用假期参加网络研修课程，不断更新教学知识","公司为新员工组织入职培训","老李年轻时读夜校学技术，中年参加行业培训，退休后仍坚持上网课","退休后的老周报名老年大学学习书法，此前他也参加过单位组织的各类培训"],"answer":1,"explanation":"终身教育的要件是：贯穿一生各阶段、包括正规与非正规教育。「公司为新员工组织入职培训」不符合要件：单一阶段的培训不构成终身教育；其余选项均符合终身教育的全部要件。故选B。"},{"id":"pd-20656","module":"panduan","diff":2,"exam":"省考","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“是王五拿走钥匙的。”；李四说：“是王五拿走钥匙的。”；王五说：“是张三拿走钥匙的。”；赵六说：“是王五拿走钥匙的。”。四人中只有1人说真话。由此可以推出，拿走钥匙的是：","options":["张三","赵六","李四","王五"],"answer":0,"explanation":"只有一人说真话。逐一假设验证：只有假设张三拿走钥匙时，四句话中为真的才恰好1句，符合题干条件，故张三拿走钥匙。故选A。"},{"id":"pd-20657","module":"panduan","diff":1,"exam":"事业编","prompt":"如果小明坚持锻炼，那么小明身体好。现已确认小明身体不好。由此可以推出：","options":["小明坚持锻炼，尽管小明身体不好","小明不坚持锻炼","如果小明不坚持锻炼，那么小明身体不好","小明坚持锻炼"],"answer":1,"explanation":"充分条件命题否定后件就要否定前件。由小明身体不好，可以推出小明不坚持锻炼；其余选项均不能由题干必然推出。故选B。"},{"id":"pd-20659","module":"panduan","diff":2,"exam":"省考","prompt":"某系统通过大量对局自我学习，棋力不断提升，战胜了人类顶尖棋手。人工智能是指用计算机系统模拟、延伸和扩展人类的智能活动，使其能够学习、推理、决策并完成通常需要人类智能才能完成的任务的技术。根据上述定义，下列同样属于人工智能的是：","options":["电子表格软件自动对数据求和","某软件通过学习数万份病历，能够辅助医生对影像进行病变识别并给出诊断建议","流水线机械臂按预设动作重复搬运货物","计算器快速完成四则运算"],"answer":1,"explanation":"人工智能的要件是：计算机系统、模拟人类智能、具备学习推理决策能力。「某软件通过学习数万份病历，能够辅助医生对影像进行病变识别并给出诊断建议」完全符合上述要件；其余选项分别存在以下问题：计算器按固定程序运算，不具备学习推理能力；机械臂执行预设动作，无智能决策；自动求和是固定功能，不涉及智能活动。故选B。"},{"id":"pd-20660","module":"panduan","diff":3,"exam":"事业编","prompt":"班里发生了一件事：走廊里的盆栽被碰倒了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“不是我碰倒盆栽的。”；李四说：“是张三碰倒盆栽的。”；王五说：“是李四碰倒盆栽的。”；赵六说：“是李四碰倒盆栽的。”。四人中只有3人说真话。由此可以推出，碰倒盆栽的是：","options":["张三","王五","赵六","李四"],"answer":3,"explanation":"只有三人说假话。逐一假设验证：只有假设李四碰倒盆栽时，四句话中为假的才恰好3句，符合题干条件，故李四碰倒盆栽。故选D。"},{"id":"pd-20661","module":"panduan","diff":3,"exam":"事业编","prompt":"夜色：朦胧\n下列与题干词项逻辑关系最相近的是：","options":["水稻：粮食作物","法官：法院","日：月","溪水：流淌"],"answer":3,"explanation":"题干「夜色」与「朦胧」为主谓关系；「溪水」与「流淌」也是主谓关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20662","module":"panduan","diff":2,"exam":"省考","prompt":"班里发生了一件事：教室里的花瓶被打碎了。老师询问小赵、小钱、小孙、小周四人，四人的说法如下：小赵说：“是小孙打碎花瓶的。”；小钱说：“不是我打碎花瓶的。”；小孙说：“是小赵打碎花瓶的。”；小周说：“是小赵打碎花瓶的。”。四人中只有1人说真话。由此可以推出，打碎花瓶的是：","options":["小钱","小赵","小孙","小周"],"answer":3,"explanation":"只有一人说真话。逐一假设验证：只有假设小周打碎花瓶时，四句话中为真的才恰好1句，符合题干条件，故小周打碎花瓶。故选D。"},{"id":"pd-20663","module":"panduan","diff":2,"exam":"省考","prompt":"并非（遵守交通规则并且出行更加安全）。由此可以推出：","options":["如果不遵守交通规则，那么出行更加安全","不遵守交通规则并且出行安全没有保障","不遵守交通规则或者出行安全没有保障","遵守交通规则或者出行更加安全"],"answer":2,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（遵守交通规则并且出行更加安全），等值于“不遵守交通规则或者出行安全没有保障”；其余选项均不符合德摩根定律。故选C。"},{"id":"pd-20664","module":"panduan","diff":3,"exam":"国考","prompt":"白菜：蔬菜\n下列与题干词项逻辑关系最相近的是：","options":["卡车：机动车","章节：小说","体温计：测量体温","勤劳：懒惰"],"answer":0,"explanation":"题干「白菜」与「蔬菜」为种属包含关系；「卡车」与「机动车」也是种属包含关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20665","module":"panduan","diff":3,"exam":"国考","prompt":"公司产品被曝光质量问题后，管理层迅速成立专项小组召回产品、安抚客户。危机管理是指组织为应对可能发生或已经发生的危机，进行监测、预警、决策和处置，以减少损失、恢复秩序的过程。根据上述定义，下列同样属于危机管理的是：","options":["某企业建立舆情监测机制，在负面事件发酵前及时回应并启动应急预案","企业按季度例会讨论经营计划","办公室统一采购办公用品","公司在年会上表彰优秀员工"],"answer":0,"explanation":"危机管理的要件是：针对可能或已经发生的危机、监测预警、决策处置。「某企业建立舆情监测机制，在负面事件发酵前及时回应并启动应急预案」完全符合上述要件；其余选项分别存在以下问题：表彰活动与危机应对无关；常规经营计划不属于危机管理；日常采购事务不涉及危机。故选A。"},{"id":"pd-20666","module":"panduan","diff":2,"exam":"省考","prompt":"所有的微波炉都是家电，所有的家电都是电器。由此可以推出：","options":["所有的微波炉都是电器","有的电器不是微波炉","有的微波炉不是电器","所有的电器都是微波炉"],"answer":0,"explanation":"三段论传递推理：微波炉都属于家电，家电都属于电器，所以所有的微波炉都是电器；其余选项不能必然推出。故选A。"},{"id":"pd-20667","module":"panduan","diff":3,"exam":"国考","prompt":"学校为教师制定学期目标，过程中提供支持，期末评价并共同商定改进措施。绩效管理是指组织通过制定绩效计划、过程辅导、考核评价和结果反馈等环节，持续提升个人和组织绩效的管理过程。根据上述定义，下列同样属于绩效管理的是：","options":["公司年底一次性发放奖金，平时不闻不问","公司年初与员工商定考核指标，年中辅导，年底评价并向员工反馈改进方向","员工年终提交一份自我总结即告结束","领导凭个人印象为下属打分"],"answer":1,"explanation":"绩效管理的要件是：制定绩效计划、过程辅导、考核评价、结果反馈，形成完整循环。「公司年初与员工商定考核指标，年中辅导，年底评价并向员工反馈改进方向」完全符合上述要件；其余选项分别存在以下问题：只有考核结果，缺乏计划、辅导和反馈环节；无绩效计划和客观标准；缺少完整的绩效管理循环。故选B。"},{"id":"pd-20668","module":"panduan","diff":2,"exam":"国考","prompt":"所有的银杏都是树木，所有的花卉都不是树木。由此可以推出：","options":["所有的花卉都是银杏","有的银杏是花卉","有的花卉是银杏","所有的花卉都不是银杏"],"answer":3,"explanation":"银杏都包含于树木，而花卉与树木完全排斥，所以花卉与银杏也完全排斥，即所有的花卉都不是银杏；其余选项与题干矛盾或不能必然推出。故选D。"},{"id":"pd-20669","module":"panduan","diff":2,"exam":"国考","prompt":"小陈、小杨、小吴、小周、小孙五人比较体重。已知：小周比小杨重；小孙比小周重；小杨比小陈重；小吴比小周重；小吴不是最重的。这五人的体重从重到轻排序，谁排第二？","options":["小周","小吴","小陈","小孙"],"answer":1,"explanation":"由题干条件逐步推理，可得五人体重从重到轻的完整排序为：小孙＞小吴＞小周＞小杨＞小陈。因此排第二的是小吴。故选B。"},{"id":"pd-20670","module":"panduan","diff":2,"exam":"国考","prompt":"鳞片：鱼\n下列与题干词项逻辑关系最相近的是：","options":["抽屉：桌子","电视机：家电","湖北：武汉","白菜：蔬菜"],"answer":0,"explanation":"题干「鳞片」与「鱼」为组成关系；「抽屉」与「桌子」也是组成关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20671","module":"panduan","diff":3,"exam":"教师编","prompt":"某科技公司的创新文化深入人心，员工主动提出改进建议蔚然成风。企业文化是企业在长期经营中形成的、为全体成员共同遵循的价值观念和行为规范的总和。根据上述定义，下列同样属于企业文化的是：","options":["公司印制了精美的产品说明书","某公司多年倡导客户第一，员工言行处处体现这一理念","公司办公楼进行了豪华装修","公司墙上的标语口号仅挂在墙上，无人践行"],"answer":1,"explanation":"企业文化的要件是：长期经营中形成、全体成员共同遵循、价值观念与行为规范。「某公司多年倡导客户第一，员工言行处处体现这一理念」完全符合上述要件；其余选项分别存在以下问题：口号未被成员共同遵循，未内化为文化；办公环境属于物质层面，不是价值观念；产品说明书是企业产品，不是共同遵循的观念。故选B。"},{"id":"pd-20672","module":"panduan","diff":3,"exam":"教师编","prompt":"物流公司为货物加装定位装置，全程联网跟踪货物位置。物联网是指通过传感设备，按约定的协议把物品与网络连接起来，进行信息交换和通信，以实现智能化识别、定位、跟踪、监控和管理的技术。根据上述定义，下列同样属于物联网的是：","options":["管理员手工录入设备台账","农田里的传感器实时采集土壤温湿度并自动联网上报，系统据此远程控制灌溉","用户用手机浏览新闻网站","电视机通过U盘播放影片"],"answer":1,"explanation":"物联网的要件是：物品通过传感设备联网、按协议通信、实现智能识别监控管理。「农田里的传感器实时采集土壤温湿度并自动联网上报，系统据此远程控制灌溉」完全符合上述要件；其余选项分别存在以下问题：人与网络的连接不属于物物相连；人工录入未通过传感设备联网；未联网，不涉及信息交换与通信。故选B。"},{"id":"pd-20673","module":"panduan","diff":2,"exam":"国考","prompt":"农场主把土地全部用于种植水稻，就放弃了种植蔬菜可能带来的更高收益。机会成本是指为了得到某种东西而所要放弃的其他选择中价值最高的那一个。根据上述定义，下列同样属于机会成本的是：","options":["公司购买设备实际支付的价款","周末小张选择加班获得加班费，放弃了外出旅游的愉快体验","小赵开店实际支出的房租、水电和进货费用","小李贷款买车每月偿还的本息"],"answer":1,"explanation":"机会成本的要件是：面临多种选择、放弃其他选择、以其中价值最高者计。「周末小张选择加班获得加班费，放弃了外出旅游的愉快体验」完全符合上述要件；其余选项分别存在以下问题：实际支出属于会计成本，不是放弃的选择；购买设备的支出是实际花费，不是机会成本；偿还本息是实际支出，不是被放弃的最优选择。故选B。"},{"id":"pd-20674","module":"panduan","diff":2,"exam":"省考","prompt":"渔民：渔网\n下列与题干词项逻辑关系最相近的是：","options":["农民：锄头","三顾茅庐：刘备","骄傲：自满","珍贵：宝贵"],"answer":0,"explanation":"题干「渔民」与「渔网」为职业与其专用工具的对应；「农民」与「锄头」也是职业与其专用工具的对应，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20675","module":"panduan","diff":3,"exam":"教师编","prompt":"并非（航班准点起飞并且旅客按时到达）。由此可以推出：","options":["如果航班没有准点起飞，那么旅客按时到达","航班没有准点起飞并且旅客没能按时到达","航班准点起飞或者旅客按时到达","航班没有准点起飞或者旅客没能按时到达"],"answer":3,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（航班准点起飞并且旅客按时到达），等值于“航班没有准点起飞或者旅客没能按时到达”；其余选项均不符合德摩根定律。故选D。"},{"id":"pd-20676","module":"panduan","diff":3,"exam":"国考","prompt":"小赵经过独立思考，坚持自己认为正确的方案，尽管多数人反对。从众是指个体在群体压力下，放弃自己的意见或行为，而采取与大多数人一致的意见或行为的现象。根据上述定义，下列不属于从众的是：","options":["消防演练中大家有序撤离，小陈按照预案行动","会议室里大家都举手赞成，原本持反对意见的小周见状也默默举起了手","讨论会上见多数人都支持方案二，小郑虽心有疑虑，最终也投了赞成票","看到街边很多人排队购买某奶茶，本来不想喝的小吴也跟着排起了队"],"answer":0,"explanation":"从众的要件是：存在群体压力、个体放弃己见、采取与多数人一致的行为。「消防演练中大家有序撤离，小陈按照预案行动」不符合要件：按预案行动，不存在群体压力下的从众；其余选项均符合从众的全部要件。故选A。"},{"id":"pd-20677","module":"panduan","diff":1,"exam":"国考","prompt":"社区组织志愿者定期清理小广告，墙面保持整洁。破窗效应是指环境中的不良现象若被放任存在，会诱使人们仿效，甚至变本加厉。根据上述定义，下列不属于破窗效应的是：","options":["公司制度严明，员工自觉遵守纪律","墙面出现第一张小广告无人清理，很快贴满整面墙","厂区一角有人随手扔了垃圾无人管，渐渐地那片空地堆满了杂物","小区一面窗户破损长期无人修，不久后更多窗户被打破，楼道垃圾也多了起来"],"answer":0,"explanation":"破窗效应的要件是：不良现象被放任存在、诱发更多人仿效、情况加剧。「公司制度严明，员工自觉遵守纪律」不符合要件：不存在被放任的不良现象；其余选项均符合破窗效应的全部要件。故选A。"},{"id":"pd-20678","module":"panduan","diff":3,"exam":"事业编","prompt":"图书馆管理员认为，增设阅览座位能够提高图书馆的入馆率。上述论证最可能基于的前提是：","options":["图书馆的藏书较为丰富","目前入馆率不高主要是因为座位数量不足","学生有较强的自习需求","图书馆的位置较为便利"],"answer":1,"explanation":"只有座位不足是入馆率低的原因，增设座位才能提高入馆率，该项是必要前提。故选B。"},{"id":"pd-20679","module":"panduan","diff":2,"exam":"事业编","prompt":"烤鸭：北京\n下列与题干词项逻辑关系最相近的是：","options":["护士：注射器","大闸蟹：阳澄湖","勇敢：怯懦","工程师：党员"],"answer":1,"explanation":"题干「烤鸭」与「北京」为产品与其产地的对应；「大闸蟹」与「阳澄湖」也是产品与其产地的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20680","module":"panduan","diff":1,"exam":"国考","prompt":"公司办公楼进行了豪华装修。企业文化是企业在长期经营中形成的、为全体成员共同遵循的价值观念和行为规范的总和。根据上述定义，下列不属于企业文化的是：","options":["老字号企业的诚信经营观念代代相传，成为全体店员的自觉行为","某科技公司的创新文化深入人心，员工主动提出改进建议蔚然成风","某公司多年倡导客户第一，员工言行处处体现这一理念","公司印制了精美的产品说明书"],"answer":3,"explanation":"企业文化的要件是：长期经营中形成、全体成员共同遵循、价值观念与行为规范。「公司印制了精美的产品说明书」不符合要件：产品说明书是企业产品，不是共同遵循的观念；其余选项均符合企业文化的全部要件。故选D。"},{"id":"pd-20681","module":"panduan","diff":1,"exam":"国考","prompt":"患者深夜到急诊科就诊。家庭医生签约服务是指居民与家庭医生团队签订服务协议，团队为其提供连续性、综合性的基本医疗卫生服务。根据上述定义，下列不属于家庭医生签约服务的是：","options":["李奶奶签约后，家庭医生团队为其建立健康档案并持续跟踪管理","某慢性病患者与家庭医生团队签约，获得长期用药指导和定期随访","体检中心为某单位提供一次性集中体检","王大爷与社区家庭医生团队签约，医生定期上门随访并提供健康指导"],"answer":2,"explanation":"家庭医生签约服务的要件是：签订服务协议、家庭医生团队、提供连续性综合性基本医疗服务。「体检中心为某单位提供一次性集中体检」不符合要件：一次性体检不具连续性，且无签约关系；其余选项均符合家庭医生签约服务的全部要件。故选C。"},{"id":"pd-20682","module":"panduan","diff":3,"exam":"国考","prompt":"某系统由多个节点共同维护账本，数据按时间顺序成块链接，篡改任一记录都会被发现。区块链是一种分布式账本技术，将数据按时间顺序打包成块并链接，通过密码学保证不可篡改，由多个节点共同维护。根据上述定义，下列同样属于区块链的是：","options":["小李把合同扫描件存入个人邮箱","公司财务将账目存于总部服务器，由财务总监一人管理","网站数据库管理员可以随时修改用户记录","某供应链平台将每批货物的流转记录上链，各参与方共同记账，任何一方无法单独篡改"],"answer":3,"explanation":"区块链的要件是：分布式账本、按时间成块链接、密码学保证不可篡改、多节点共同维护。「某供应链平台将每批货物的流转记录上链，各参与方共同记账，任何一方无法单独篡改」完全符合上述要件；其余选项分别存在以下问题：中心化存储由单人管理，与分布式相反；单点存储不具分布式特征；记录可被随意修改，不满足不可篡改。故选D。"},{"id":"pd-20683","module":"panduan","diff":1,"exam":"省考","prompt":"公司组织拓展训练，成员在协作任务中增进了信任与默契。团队建设是指通过有组织的活动增进成员信任与协作，提升团队凝聚力和绩效的过程。根据上述定义，下列同样属于团队建设的是：","options":["公司向员工发放节日福利","员工各自在工位上完成本职工作","两个部门召开业务对接会议","部门定期开展协作游戏和经验分享会，团队氛围日益融洽"],"answer":3,"explanation":"团队建设的要件是：有组织的活动、增进信任与协作、提升凝聚力。「部门定期开展协作游戏和经验分享会，团队氛围日益融洽」完全符合上述要件；其余选项分别存在以下问题：各自工作未涉及增进信任协作的有组织活动；发放福利不属于团队建设活动；业务会议以工作对接为目的，不是团队建设。故选D。"},{"id":"pd-20684","module":"panduan","diff":2,"exam":"国考","prompt":"只有工作效率提高，才团队分工明确。现已确认团队分工明确。由此可以推出：","options":["如果工作效率提高，那么团队分工明确","工作效率提高","只有团队分工明确，才工作效率提高","工作效率没有提高"],"answer":1,"explanation":"「只有工作效率提高，才团队分工明确」中，工作效率提高是团队分工明确的必要条件，肯定后件就要肯定前件。现已确认团队分工明确，属于肯定后件，故工作效率提高必然成立，即工作效率提高；肯定前件不能推出后件，其余选项均不能必然推出。故选B。"},{"id":"pd-20685","module":"panduan","diff":3,"exam":"国考","prompt":"农田里的传感器实时采集土壤温湿度并自动联网上报，系统据此远程控制灌溉。物联网是指通过传感设备，按约定的协议把物品与网络连接起来，进行信息交换和通信，以实现智能化识别、定位、跟踪、监控和管理的技术。根据上述定义，下列同样属于物联网的是：","options":["小区智能水表自动将用水数据传输至水务平台，实现远程抄表","管理员手工录入设备台账","电视机通过U盘播放影片","用户用手机浏览新闻网站"],"answer":0,"explanation":"物联网的要件是：物品通过传感设备联网、按协议通信、实现智能识别监控管理。「小区智能水表自动将用水数据传输至水务平台，实现远程抄表」完全符合上述要件；其余选项分别存在以下问题：人与网络的连接不属于物物相连；人工录入未通过传感设备联网；未联网，不涉及信息交换与通信。故选A。"},{"id":"pd-20686","module":"panduan","diff":2,"exam":"国考","prompt":"某县撤县设区，大量农村人口进入城区就业定居，城区面积不断扩大。城市化是指人口向城镇集聚、乡村地区转变为城镇地区，城镇数量增加和规模扩大的过程。根据上述定义，下列同样属于城市化的是：","options":["因工业园区建设，周边村庄逐步改造为街道，村民转为城镇居民","某乡实施农村危房改造，村容焕然一新","某村发展乡村旅游，村民收入提高但仍从事农业生产","城市居民利用假期到乡村度假"],"answer":0,"explanation":"城市化的要件是：人口向城镇集聚、乡村转变为城镇、城镇规模扩大。「因工业园区建设，周边村庄逐步改造为街道，村民转为城镇居民」完全符合上述要件；其余选项分别存在以下问题：乡村发展未发生人口向城镇集聚；短期度假不是人口向城镇集聚；乡村建设未改变乡村性质。故选A。"},{"id":"pd-20687","module":"panduan","diff":1,"exam":"医疗编","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“是李四拿走钥匙的。”；李四说：“是王五拿走钥匙的。”；王五说：“不是我拿走钥匙的。”；赵六说：“不是我拿走钥匙的。”。四人中只有3人说真话。由此可以推出，说假话的是：","options":["赵六","李四","王五","张三"],"answer":1,"explanation":"只有一人说假话。逐一假设验证可知，李四的话为假，其余三人的话均为真。故选B。"},{"id":"pd-20688","module":"panduan","diff":2,"exam":"事业编","prompt":"某家庭食品支出的绝对金额逐年增加。恩格尔系数是食品支出总额占个人消费支出总额的比重，通常用于衡量生活水平，系数越低说明生活水平越高。根据上述定义，下列不属于恩格尔系数的是：","options":["某地区消费结构升级，食品支出占比逐年下降，生活水平明显提高","某家庭收入提高后，食品支出占消费总支出的比重从百分之四十降至百分之二十五","小赵家消费总支出中食品所占比重持续降低，生活越来越宽裕","某家庭购买奢侈品的支出大幅增加"],"answer":3,"explanation":"恩格尔系数的要件是：食品支出占消费总支出的比重、反映生活水平。「某家庭购买奢侈品的支出大幅增加」不符合要件：奢侈品支出不属于食品支出占比的范畴；其余选项均符合恩格尔系数的全部要件。故选D。"},{"id":"pd-20689","module":"panduan","diff":2,"exam":"教师编","prompt":"节约：浪费\n下列与题干词项逻辑关系最相近的是：","options":["英国：伦敦","顿时：立刻","《家》：巴金","高兴：悲伤"],"answer":3,"explanation":"题干「节约」与「浪费」为反义关系；「高兴」与「悲伤」也是反义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20690","module":"panduan","diff":2,"exam":"事业编","prompt":"小陈、小杨、小吴、小周、小孙五人比较体重。已知：小吴比小周重；小周比小杨重；小杨比小陈重；小杨比小孙重；小陈不是最重的。这五人的体重从重到轻排序，谁排第一？","options":["小周","小吴","小孙","小陈"],"answer":1,"explanation":"由题干条件逐步推理，可得五人体重从重到轻的完整排序为：小吴＞小周＞小杨＞小孙＞小陈。因此排第一的是小吴。故选B。"},{"id":"pd-20691","module":"panduan","diff":2,"exam":"事业编","prompt":"患者只是普通感冒也直接到三甲医院排队就诊。分级诊疗是指按照疾病的轻重缓急及治疗难易程度进行分级，常见病、多发病在基层医疗机构诊治，疑难重症转诊至大医院的就医制度。根据上述定义，下列不属于分级诊疗的是：","options":["高血压患者老王平时在社区医院取药随访，病情变化时由社区转诊上级医院","老李感冒发烧先到社区卫生服务中心就诊，医生建议其慢性病在社区随访","患者自行到药店购买药品服用","社区医生发现患者病情复杂，开具转诊单将其转至三甲医院专科诊治"],"answer":2,"explanation":"分级诊疗的要件是：按病情轻重分级、常见病在基层、疑难重症转诊大医院。「患者自行到药店购买药品服用」不符合要件：自行购药不属于分级就诊；其余选项均符合分级诊疗的全部要件。故选C。"},{"id":"pd-20692","module":"panduan","diff":2,"exam":"医疗编","prompt":"老刘收藏邮票，最初几枚让他兴奋不已，随着数量增多，新增邮票带来的快乐逐渐下降。边际效用递减是指在一定时间内，随着消费者对某种商品消费量的连续增加，其从每增加一单位商品中所获得的效用增量是递减的。根据上述定义，下列同样属于边际效用递减的是：","options":["小郑同时消费面包和牛奶获得的满足感","某商品降价后销量大增","小吴连吃饺子，第一个觉得最香，越往后越觉得不过如此","小周工资上涨后购买的商品总量增加"],"answer":2,"explanation":"边际效用递减的要件是：连续消费同一商品、每增加一单位带来的效用增量递减。「小吴连吃饺子，第一个觉得最香，越往后越觉得不过如此」完全符合上述要件；其余选项分别存在以下问题：描述的是收入变化对消费总量的影响，不是同一商品连续消费的效用变化；价格变动引起的需求变化，不是边际效用递减；不同商品的互补消费，不是同一商品连续消费。故选C。"},{"id":"pd-20693","module":"panduan","diff":2,"exam":"事业编","prompt":"缓慢：迅速\n下列与题干词项逻辑关系最相近的是：","options":["洗衣机：家电","砖块：墙壁","棒球：球类运动","保守：开放"],"answer":3,"explanation":"题干「缓慢」与「迅速」为反义关系；「保守」与「开放」也是反义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20694","module":"panduan","diff":2,"exam":"事业编","prompt":"小吴第一次学游泳呛水，有些害怕但仍坚持练习。习得性无助是指个体经历反复失败或挫折后，感到一切都无法控制，从而产生无能为力、放弃努力的心理状态。根据上述定义，下列不属于习得性无助的是：","options":["小孙因身体不适暂停训练，康复后继续投入","小赵多次数学考试不及格后，即使题目很简单也不再尝试作答，认为自己天生学不会","老周多次求职被拒后，不再投递简历，觉得努力也没用","小狗多次尝试跳出隔板均告失败后，即使隔板降低也不再尝试"],"answer":0,"explanation":"习得性无助的要件是：反复失败或挫折、感到无法控制、放弃努力。「小孙因身体不适暂停训练，康复后继续投入」不符合要件：暂停训练有客观原因，并非放弃努力；其余选项均符合习得性无助的全部要件。故选A。"},{"id":"pd-20695","module":"panduan","diff":2,"exam":"省考","prompt":"记者：作家\n下列与题干词项逻辑关系最相近的是：","options":["期望：希望","隐蔽：隐藏","局势：稳定","医生：作家"],"answer":3,"explanation":"题干「记者」与「作家」为交叉关系；「医生」与「作家」也是交叉关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20696","module":"panduan","diff":1,"exam":"省考","prompt":"并非（密码设置复杂并且账号更安全）。由此可以推出：","options":["密码设置复杂或者账号更安全","密码设置简单并且账号不够安全","如果密码设置简单，那么账号更安全","密码设置简单或者账号不够安全"],"answer":3,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（密码设置复杂并且账号更安全），等值于“密码设置简单或者账号不够安全”；其余选项均不符合德摩根定律。故选D。"},{"id":"pd-20697","module":"panduan","diff":2,"exam":"医疗编","prompt":"只有听课更有针对性，才课前预习。现已确认课前预习。由此可以推出：","options":["只有课前预习，才听课更有针对性","听课更有针对性","听课缺乏针对性","如果听课更有针对性，那么课前预习"],"answer":1,"explanation":"「只有听课更有针对性，才课前预习」中，听课更有针对性是课前预习的必要条件，肯定后件就要肯定前件。现已确认课前预习，属于肯定后件，故听课更有针对性必然成立，即听课更有针对性；肯定前件不能推出后件，其余选项均不能必然推出。故选B。"},{"id":"pd-20698","module":"panduan","diff":2,"exam":"医疗编","prompt":"小李把合同扫描件存入个人邮箱。区块链是一种分布式账本技术，将数据按时间顺序打包成块并链接，通过密码学保证不可篡改，由多个节点共同维护。根据上述定义，下列不属于区块链的是：","options":["公益平台将捐款流向记录写入区块链，捐赠人可随时查询且记录不可更改","某系统由多个节点共同维护账本，数据按时间顺序成块链接，篡改任一记录都会被发现","某供应链平台将每批货物的流转记录上链，各参与方共同记账，任何一方无法单独篡改","网站数据库管理员可以随时修改用户记录"],"answer":3,"explanation":"区块链的要件是：分布式账本、按时间成块链接、密码学保证不可篡改、多节点共同维护。「网站数据库管理员可以随时修改用户记录」不符合要件：记录可被随意修改，不满足不可篡改；其余选项均符合区块链的全部要件。故选D。"},{"id":"pd-20699","module":"panduan","diff":2,"exam":"教师编","prompt":"在职教师利用假期参加网络研修课程，不断更新教学知识。终身教育是指人们在一生各阶段中所受各种教育的总和，包括正规教育与非正规教育，贯穿人的一生。根据上述定义，下列同样属于终身教育的是：","options":["小赵全日制读完本科后便停止了学习","老李年轻时读夜校学技术，中年参加行业培训，退休后仍坚持上网课","小学生按照课表上课","公司为新员工组织入职培训"],"answer":1,"explanation":"终身教育的要件是：贯穿一生各阶段、包括正规与非正规教育。「老李年轻时读夜校学技术，中年参加行业培训，退休后仍坚持上网课」完全符合上述要件；其余选项分别存在以下问题：仅接受某一阶段教育，未贯穿一生；仅属正规教育的一个片段；单一阶段的培训不构成终身教育。故选B。"},{"id":"pd-20700","module":"panduan","diff":1,"exam":"国考","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“不是我拿走钥匙的。”；李四说：“是赵六拿走钥匙的。”；王五说：“是李四拿走钥匙的。”；赵六说：“不是我拿走钥匙的。”。四人中只有1人说真话。由此可以推出，拿走钥匙的是：","options":["赵六","李四","王五","张三"],"answer":3,"explanation":"只有一人说真话。逐一假设验证：只有假设张三拿走钥匙时，四句话中为真的才恰好1句，符合题干条件，故张三拿走钥匙。故选D。"},{"id":"pd-20701","module":"panduan","diff":3,"exam":"教师编","prompt":"所有的鲨鱼都是鱼类，所有的鱼类都是水生动物。由此可以推出：","options":["所有的水生动物都是鲨鱼","有的鲨鱼不是水生动物","所有的鲨鱼都是水生动物","有的水生动物不是鲨鱼"],"answer":2,"explanation":"三段论传递推理：鲨鱼都属于鱼类，鱼类都属于水生动物，所以所有的鲨鱼都是水生动物；其余选项不能必然推出。故选C。"},{"id":"pd-20702","module":"panduan","diff":2,"exam":"教师编","prompt":"企业根据自身历史数据设定增长目标。标杆管理是指企业以行业内外最优秀者为基准，将其产品、服务或管理实践与本企业对比、分析、学习，从而改进提高的过程。根据上述定义，下列不属于标杆管理的是：","options":["医院组织团队赴全国最佳同行学习其护理管理模式，结合实际加以优化","企业将行业标杆企业的成本控制指标作为目标，逐月对比追赶","公司对员工进行绩效排名","某公司以行业龙头企业的服务流程为参照，逐项对比找出差距并改进"],"answer":2,"explanation":"标杆管理的要件是：以最优秀者为基准、对比分析、学习改进。「公司对员工进行绩效排名」不符合要件：绩效排名不涉及向标杆学习；其余选项均符合标杆管理的全部要件。故选C。"},{"id":"pd-20703","module":"panduan","diff":2,"exam":"事业编","prompt":"冷漠：热情\n下列与题干词项逻辑关系最相近的是：","options":["三顾茅庐：刘备","抽屉：桌子","精确：粗略","孤独：寂寞"],"answer":2,"explanation":"题干「冷漠」与「热情」为反义关系；「精确」与「粗略」也是反义关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20704","module":"panduan","diff":1,"exam":"国考","prompt":"所有的绿茶都是茶叶饮品，所有的茶叶饮品都是饮品。由此可以推出：","options":["有的绿茶不是饮品","所有的绿茶都是饮品","所有的饮品都是绿茶","有的饮品不是绿茶"],"answer":1,"explanation":"三段论传递推理：绿茶都属于茶叶饮品，茶叶饮品都属于饮品，所以所有的绿茶都是饮品；其余选项不能必然推出。故选B。"},{"id":"pd-20705","module":"panduan","diff":3,"exam":"国考","prompt":"高兴：悲伤\n下列与题干词项逻辑关系最相近的是：","options":["保守：开放","衬衫：服装","云南：昆明","凿壁偷光：匡衡"],"answer":0,"explanation":"题干「高兴」与「悲伤」为反义关系；「保守」与「开放」也是反义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20706","module":"panduan","diff":2,"exam":"省考","prompt":"李某盗窃后内心不安，主动到公安机关交代了全部盗窃事实。自首是指犯罪以后自动投案，如实供述自己的罪行的行为。根据上述定义，下列同样属于自首的是：","options":["王某作案后潜逃，在通缉期间向当地派出所投案，并如实供述了罪行","周某因交通肇事被现场查获，谎称车辆是他人驾驶","孙某自动投案，但只交代部分罪行，隐瞒了主要犯罪事实","钱某作案后被公安机关抓获，在审讯中交代了罪行"],"answer":0,"explanation":"自首的要件是：自动投案、如实供述自己的罪行。「王某作案后潜逃，在通缉期间向当地派出所投案，并如实供述了罪行」完全符合上述要件；其余选项分别存在以下问题：被抓获后被动交代，不属于自动投案；未如实供述主要犯罪事实；未如实供述自己的罪行。故选A。"},{"id":"pd-20707","module":"panduan","diff":1,"exam":"省考","prompt":"县：市：省\n下列与题干词项逻辑关系最相近的是：","options":["克：千克：吨","曹雪芹：《红楼梦》：贾宝玉","赤：橙：黄","吴承恩：《西游记》：孙悟空"],"answer":0,"explanation":"题干三个词为程度或数量依次递进的关系；「克：千克：吨」也是程度或数量依次递进的关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20708","module":"panduan","diff":2,"exam":"国考","prompt":"医生认为，应当让患者停用某药物。上述论证最可能基于的前提是：","options":["停用该药物后，患者的病情不会因此明显加重","患者曾出现轻度不适","该药物价格较为昂贵","该药物需要凭处方购买"],"answer":0,"explanation":"若停药会导致病情明显加重，则不应停药，该项是停药建议成立的必要前提。故选A。"},{"id":"pd-20709","module":"panduan","diff":1,"exam":"省考","prompt":"扇叶：电风扇\n下列与题干词项逻辑关系最相近的是：","options":["笔帽：钢笔","演员：歌手","广东：广州","松树：树木"],"answer":0,"explanation":"题干「扇叶」与「电风扇」为组成关系；「笔帽」与「钢笔」也是组成关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20710","module":"panduan","diff":2,"exam":"事业编","prompt":"并非（饮食规律并且肠胃健康）。由此可以推出：","options":["饮食不规律并且肠胃不健康","如果饮食不规律，那么肠胃健康","饮食不规律或者肠胃不健康","饮食规律或者肠胃健康"],"answer":2,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（饮食规律并且肠胃健康），等值于“饮食不规律或者肠胃不健康”；其余选项均不符合德摩根定律。故选C。"},{"id":"pd-20711","module":"panduan","diff":1,"exam":"教师编","prompt":"所有的本科生都是大学生，所有的小学生都不是大学生。由此可以推出：","options":["有的小学生是本科生","有的本科生是小学生","所有的小学生都不是本科生","所有的小学生都是本科生"],"answer":2,"explanation":"本科生都包含于大学生，而小学生与大学生完全排斥，所以小学生与本科生也完全排斥，即所有的小学生都不是本科生；其余选项与题干矛盾或不能必然推出。故选C。"},{"id":"pd-20712","module":"panduan","diff":3,"exam":"省考","prompt":"研究发现，经常运动的老年人骨折率明显更低，因此医生认为运动能够预防骨折。以下哪项如果为真，最能削弱该结论？","options":["有的老人运动后出现肌肉酸痛","老年人补钙的方式多种多样","身体虚弱、骨质疏松严重的老人根本无法坚持运动，骨折风险本来就高","不同运动的运动强度差别很大"],"answer":2,"explanation":"身体虚弱才是骨折率高且无法运动的原因，属于因果倒置，动摇了运动防骨折的结论。故选C。"},{"id":"pd-20713","module":"panduan","diff":3,"exam":"教师编","prompt":"普洱茶：云南\n下列与题干词项逻辑关系最相近的是：","options":["教师：党员","开始：结束","烤鸭：北京","提高：降低"],"answer":2,"explanation":"题干「普洱茶」与「云南」为产品与其产地的对应；「烤鸭」与「北京」也是产品与其产地的对应，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20714","module":"panduan","diff":2,"exam":"事业编","prompt":"楼道灯坏了，全楼住户都觉得别人会报修，拖了半个月无人处理。责任分散效应是指在群体情境中，个体感到责任被分散到他人身上，从而减少个人援助或努力的现象。根据上述定义，下列同样属于责任分散效应的是：","options":["救援队分工明确，各成员各司其职","值班员小王发现火情后立即报警并组织疏散","街头一位老人摔倒，围观者众多，人人都觉得总会有人去扶，结果无人上前","小赵独自路过，毫不犹豫扶起摔倒的老人"],"answer":2,"explanation":"责任分散效应的要件是：群体情境、责任被分散到他人身上、个人努力或援助减少。「街头一位老人摔倒，围观者众多，人人都觉得总会有人去扶，结果无人上前」完全符合上述要件；其余选项分别存在以下问题：责任明确到人，不存在责任分散；单人情境下没有可分散责任的对象；分工明确使责任落实到个人。故选C。"},{"id":"pd-20715","module":"panduan","diff":2,"exam":"事业编","prompt":"豆浆：饮品\n下列与题干词项逻辑关系最相近的是：","options":["青蛙：两栖动物","江苏：南京","履行：义务","水位：上涨"],"answer":0,"explanation":"题干「豆浆」与「饮品」为种属包含关系；「青蛙」与「两栖动物」也是种属包含关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20716","module":"panduan","diff":2,"exam":"国考","prompt":"小学开展社团活动，鼓励每个学生至少参加一项兴趣活动，促进多元发展。素质教育是指以提高受教育者多方面素质为目标的教育模式，注重德智体美劳全面发展，强调面向全体学生、促进个性发展。根据上述定义，下列同样属于素质教育的是：","options":["学校组织学生参加志愿服务和劳动实践，培养多方面素质","学校将全部课时用于应试科目的反复训练","学校按分数给学生排名并分设快慢班","培训机构只针对考试科目突击提分"],"answer":0,"explanation":"素质教育的要件是：以提高多方面素质为目标、面向全体学生、促进全面发展与个性发展。「学校组织学生参加志愿服务和劳动实践，培养多方面素质」完全符合上述要件；其余选项分别存在以下问题：唯应试训练与全面发展背道而驰；突击提分不属于素质教育；唯分数做法违背面向全体、全面发展的要求。故选A。"},{"id":"pd-20717","module":"panduan","diff":1,"exam":"国考","prompt":"教师：党员\n下列与题干词项逻辑关系最相近的是：","options":["商人：收藏家","消毒柜：消毒","父：母","天：地"],"answer":0,"explanation":"题干「教师」与「党员」为交叉关系；「商人」与「收藏家」也是交叉关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20718","module":"panduan","diff":2,"exam":"国考","prompt":"纸上谈兵：赵括\n下列与题干词项逻辑关系最相近的是：","options":["辽阔：草原","屏幕：手机","灿烂：文化","乐不思蜀：刘禅"],"answer":3,"explanation":"题干「纸上谈兵」与「赵括」为成语典故与其主人公的对应；「乐不思蜀」与「刘禅」也是成语典故与其主人公的对应，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20719","module":"panduan","diff":2,"exam":"国考","prompt":"某商家以质优价廉、服务周到吸引顾客，客流量稳步上升。正当竞争是指经营者遵守法律和商业道德，通过提高商品质量、降低成本、改进技术等正当手段开展竞争，以争取交易机会的行为。根据上述定义，下列同样属于正当竞争的是：","options":["某商家散布竞争对手产品质量有严重问题的虚假信息","某公司通过改进工艺降低成本，以更优惠的价格参与市场竞争","某企业冒用他人注册商标销售自己的产品","某公司以低于成本的价格倾销商品，意图挤垮对手"],"answer":1,"explanation":"正当竞争的要件是：遵守法律和商业道德、采用正当手段、争取交易机会。「某公司通过改进工艺降低成本，以更优惠的价格参与市场竞争」完全符合上述要件；其余选项分别存在以下问题：散布虚假信息属于商业诋毁，是不正当竞争；冒用注册商标违反法律和商业道德；低于成本倾销属于不正当竞争手段。故选B。"},{"id":"pd-20720","module":"panduan","diff":1,"exam":"事业编","prompt":"秦朝：嬴政\n下列与题干词项逻辑关系最相近的是：","options":["隋朝：杨坚","苹果：水果","医生：听诊器","瓷器：景德镇"],"answer":0,"explanation":"题干「秦朝」与「嬴政」为朝代与其建立者的对应；「隋朝」与「杨坚」也是朝代与其建立者的对应，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20721","module":"panduan","diff":1,"exam":"教师编","prompt":"阻止：阻拦\n下列与题干词项逻辑关系最相近的是：","options":["卧薪尝胆：勾践","理发师：剪刀","繁荣：昌盛","屋顶：房子"],"answer":2,"explanation":"题干「阻止」与「阻拦」为近义关系；「繁荣」与「昌盛」也是近义关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20722","module":"panduan","diff":1,"exam":"事业编","prompt":"甲、乙、丙、丁四人的爱好各不相同，分别是游泳、跑步、读书、摄影。已知：丙的爱好不是摄影；乙的爱好是跑步；甲的爱好是游泳。由此可以推出，丙的爱好是：","options":["跑步","读书","摄影","游泳"],"answer":1,"explanation":"由题干条件逐一排除可得：甲的爱好是游泳；乙的爱好是跑步；丙的爱好是读书；丁的爱好是摄影。因此丙的爱好是读书。故选B。"},{"id":"pd-20723","module":"panduan","diff":2,"exam":"省考","prompt":"增加：减少\n下列与题干词项逻辑关系最相近的是：","options":["公开：秘密","轮胎：汽车","豆浆：饮品","梅：兰"],"answer":0,"explanation":"题干「增加」与「减少」为反义关系；「公开」与「秘密」也是反义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20724","module":"panduan","diff":2,"exam":"国考","prompt":"师：生\n下列与题干词项逻辑关系最相近的是：","options":["水彩画：绘画","完璧归赵：蔺相如","江：河","茅台酒：贵州"],"answer":2,"explanation":"题干「师」与「生」为并列关系；「江」与「河」也是并列关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20725","module":"panduan","diff":2,"exam":"省考","prompt":"如果赛前充分热身，那么运动损伤减少。现已确认运动损伤没有减少。由此可以推出：","options":["赛前没有充分热身","如果赛前没有充分热身，那么运动损伤没有减少","赛前充分热身","赛前充分热身，尽管运动损伤没有减少"],"answer":0,"explanation":"充分条件命题否定后件就要否定前件。由运动损伤没有减少，可以推出赛前没有充分热身；其余选项均不能由题干必然推出。故选A。"},{"id":"pd-20726","module":"panduan","diff":2,"exam":"事业编","prompt":"如果小明坚持锻炼，那么小明身体好；如果小明身体好，那么小明工作效率高。由此可以推出：","options":["如果小明工作效率高，那么小明坚持锻炼","如果小明身体好，那么小明坚持锻炼","如果小明坚持锻炼，那么小明工作效率高","如果小明不坚持锻炼，那么小明工作效率不高"],"answer":2,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果小明坚持锻炼，那么小明工作效率高；其余选项均属无效推理。故选C。"},{"id":"pd-20727","module":"panduan","diff":1,"exam":"事业编","prompt":"甲、乙、丙、丁、戊五人比较跑步速度。已知：乙比戊快；戊比甲快；戊比丙快；乙比丙快；丁不是最快的。这五人的跑步速度从快到慢排序，谁排第一？","options":["丙","乙","甲","丁"],"answer":1,"explanation":"由题干条件逐步推理，可得五人跑步速度从快到慢的完整排序为：乙＞戊＞丁＞丙＞甲。因此排第一的是乙。故选B。"},{"id":"pd-20728","module":"panduan","diff":1,"exam":"医疗编","prompt":"小陈、小杨、小吴、小周、小孙五人比较年龄。已知：小杨比小陈大；小吴比小杨大；小周比小吴大；小周比小陈大；小周不是最大的。这五人的年龄从大到小排序，谁排第四？","options":["小吴","小周","小杨","小孙"],"answer":2,"explanation":"由题干条件逐步推理，可得五人年龄从大到小的完整排序为：小孙＞小周＞小吴＞小杨＞小陈。因此排第四的是小杨。故选C。"},{"id":"pd-20729","module":"panduan","diff":2,"exam":"国考","prompt":"班里发生了一件事：教室里的花瓶被打碎了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“是赵六打碎花瓶的。”；李四说：“不是我打碎花瓶的。”；王五说：“不是我打碎花瓶的。”；赵六说：“是李四打碎花瓶的。”。四人中只有1人说真话。由此可以推出，打碎花瓶的是：","options":["赵六","张三","王五","李四"],"answer":2,"explanation":"只有一人说真话。逐一假设验证：只有假设王五打碎花瓶时，四句话中为真的才恰好1句，符合题干条件，故王五打碎花瓶。故选C。"},{"id":"pd-20730","module":"panduan","diff":2,"exam":"教师编","prompt":"并非（合同依法成立并且合同具有法律约束力）。由此可以推出：","options":["合同未依法成立或者合同不具有法律约束力","如果合同未依法成立，那么合同具有法律约束力","合同未依法成立并且合同不具有法律约束力","合同依法成立或者合同具有法律约束力"],"answer":0,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（合同依法成立并且合同具有法律约束力），等值于“合同未依法成立或者合同不具有法律约束力”；其余选项均不符合德摩根定律。故选A。"},{"id":"pd-20731","module":"panduan","diff":1,"exam":"事业编","prompt":"小赵全日制读完本科后便停止了学习。终身教育是指人们在一生各阶段中所受各种教育的总和，包括正规教育与非正规教育，贯穿人的一生。根据上述定义，下列不属于终身教育的是：","options":["退休后的老周报名老年大学学习书法，此前他也参加过单位组织的各类培训","小学生按照课表上课","在职教师利用假期参加网络研修课程，不断更新教学知识","老李年轻时读夜校学技术，中年参加行业培训，退休后仍坚持上网课"],"answer":1,"explanation":"终身教育的要件是：贯穿一生各阶段、包括正规与非正规教育。「小学生按照课表上课」不符合要件：仅属正规教育的一个片段；其余选项均符合终身教育的全部要件。故选B。"},{"id":"pd-20732","module":"panduan","diff":3,"exam":"国考","prompt":"麻雀：鸟类\n下列与题干词项逻辑关系最相近的是：","options":["轿车：汽车","浙江：杭州","鳞片：鱼","船桨：小船"],"answer":0,"explanation":"题干「麻雀」与「鸟类」为种属包含关系；「轿车」与「汽车」也是种属包含关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20733","module":"panduan","diff":1,"exam":"省考","prompt":"某家庭购买奢侈品的支出大幅增加。恩格尔系数是食品支出总额占个人消费支出总额的比重，通常用于衡量生活水平，系数越低说明生活水平越高。根据上述定义，下列不属于恩格尔系数的是：","options":["某家庭收入提高后，食品支出占消费总支出的比重从百分之四十降至百分之二十五","小赵家消费总支出中食品所占比重持续降低，生活越来越宽裕","某国物价普遍上涨导致消费总支出增加","某地区消费结构升级，食品支出占比逐年下降，生活水平明显提高"],"answer":2,"explanation":"恩格尔系数的要件是：食品支出占消费总支出的比重、反映生活水平。「某国物价普遍上涨导致消费总支出增加」不符合要件：物价上涨影响的是支出总额，不是食品支出占比；其余选项均符合恩格尔系数的全部要件。故选C。"},{"id":"pd-20734","module":"panduan","diff":1,"exam":"国考","prompt":"并非（土壤肥沃并且作物长势良好）。由此可以推出：","options":["土壤贫瘠并且作物长势不好","土壤肥沃或者作物长势良好","如果土壤贫瘠，那么作物长势良好","土壤贫瘠或者作物长势不好"],"answer":3,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（土壤肥沃并且作物长势良好），等值于“土壤贫瘠或者作物长势不好”；其余选项均不符合德摩根定律。故选D。"},{"id":"pd-20735","module":"panduan","diff":2,"exam":"省考","prompt":"经理直接要求员工完成高难度任务。登门槛效应是指一个人一旦接受了他人的一个微小要求后，为避免认知失调或给人前后一致的印象，更可能接受更大要求的现象。根据上述定义，下列不属于登门槛效应的是：","options":["推销员先请住户填写一份小问卷，住户答应后，又同意接受产品试用","募捐者先请路人签名支持环保，路人签名后，再请其捐出少量善款，路人大多同意","小赵先请同事帮忙带一杯咖啡，同事答应后，再请他代为加班整理资料，同事也同意了","小钱断然拒绝了同事的大额借款请求"],"answer":3,"explanation":"登门槛效应的要件是：先提出微小要求被接受、再提出更大要求、更大要求更易被接受。「小钱断然拒绝了同事的大额借款请求」不符合要件：拒绝了请求，未体现由小到大的递进；其余选项均符合登门槛效应的全部要件。故选D。"},{"id":"pd-20736","module":"panduan","diff":1,"exam":"国考","prompt":"小陈、小杨、小吴、小周、小孙五人比较体重。已知：小孙比小陈重；小杨比小周重；小周比小孙重；小吴不是最轻的。这五人的体重从重到轻排序，谁排最后？","options":["小孙","小陈","小周","小杨"],"answer":1,"explanation":"由题干条件逐步推理，可得五人体重从重到轻的完整排序为：小吴＞小杨＞小周＞小孙＞小陈。因此排最后的是小陈。故选B。"},{"id":"pd-20737","module":"panduan","diff":3,"exam":"事业编","prompt":"崭新：陈旧\n下列与题干词项逻辑关系最相近的是：","options":["重阳节：九月初九","《三国演义》：罗贯中","日本：东京","生存：死亡"],"answer":3,"explanation":"题干「崭新」与「陈旧」为反义关系；「生存」与「死亡」也是反义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20738","module":"panduan","diff":2,"exam":"省考","prompt":"如果团队分工明确，那么工作效率提高；如果工作效率提高，那么任务按时完成。由此可以推出：","options":["如果任务按时完成，那么团队分工明确","如果团队分工不明确，那么任务没能按时完成","如果团队分工明确，那么任务按时完成","如果工作效率提高，那么团队分工明确"],"answer":2,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果团队分工明确，那么任务按时完成；其余选项均属无效推理。故选C。"},{"id":"pd-20739","module":"panduan","diff":2,"exam":"国考","prompt":"水稻：粮食作物\n下列与题干词项逻辑关系最相近的是：","options":["手指：手","卡车：机动车","泰国：曼谷","树叶：树木"],"answer":1,"explanation":"题干「水稻」与「粮食作物」为种属包含关系；「卡车」与「机动车」也是种属包含关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20740","module":"panduan","diff":2,"exam":"国考","prompt":"班里发生了一件事：图书角的一本书被弄破了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“是赵六弄破图书的。”；李四说：“不是我弄破图书的。”；王五说：“是张三弄破图书的。”；赵六说：“不是我弄破图书的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["王五","李四","赵六","张三"],"answer":2,"explanation":"只有一人说真话。逐一假设验证可知，赵六的话为真，其余三人的话均为假。故选C。"},{"id":"pd-20741","module":"panduan","diff":1,"exam":"教师编","prompt":"经理通过邮件向各部门布置任务。走动管理是指管理者走出办公室，深入现场、直接与员工和顾客接触，及时了解和解决问题的管理方式。根据上述定义，下列不属于走动管理的是：","options":["总经理每周到车间与一线员工交流，现场协调解决设备问题","公司召开季度总结大会","校长课间到教室和操场走动，及时了解师生的困难并现场解决","店长每日巡视各柜台，直接听取顾客意见并当场处理投诉"],"answer":1,"explanation":"走动管理的要件是：走出办公室、深入现场、直接接触员工和顾客、及时解决问题。「公司召开季度总结大会」不符合要件：会议形式不属于走动管理；其余选项均符合走动管理的全部要件。故选B。"},{"id":"pd-20742","module":"panduan","diff":2,"exam":"国考","prompt":"小钱、小郑、小冯、小许、小何五人比较体重。已知：小冯比小郑重；小郑比小何重；小冯比小何重；小郑比小钱重；小许不是最重的。这五人的体重从重到轻排序，谁排第一？","options":["小许","小钱","小何","小冯"],"answer":3,"explanation":"由题干条件逐步推理，可得五人体重从重到轻的完整排序为：小冯＞小许＞小郑＞小钱＞小何。因此排第一的是小冯。故选D。"},{"id":"pd-20744","module":"panduan","diff":1,"exam":"医疗编","prompt":"小周自己嗜辣，便以为所有客人都爱吃辣，点菜全点辣菜。投射效应是指将自己具有的特质归因到他人身上的心理倾向，即以己度人。根据上述定义，下列同样属于投射效应的是：","options":["小陈设身处地为他人着想，努力理解对方的真实感受","小吴通过问卷调查了解顾客的真实偏好","小钱根据小赵的实际工作表现对他作出评价","老王生性多疑，总认为别人也在背后算计他"],"answer":3,"explanation":"投射效应的要件是：以自己的特质、推测他人也具有同样的特质。「老王生性多疑，总认为别人也在背后算计他」完全符合上述要件；其余选项分别存在以下问题：通过调查了解他人，不是以己度人；共情是理解他人感受，不是把自己的特质加于他人；依据实际表现评价，不属于投射。故选D。"},{"id":"pd-20745","module":"panduan","diff":1,"exam":"省考","prompt":"所有的白菜都是蔬菜，所有的蔬菜都是植物。由此可以推出：","options":["所有的植物都是白菜","有的植物不是白菜","有的白菜不是植物","所有的白菜都是植物"],"answer":3,"explanation":"三段论传递推理：白菜都属于蔬菜，蔬菜都属于植物，所以所有的白菜都是植物；其余选项不能必然推出。故选D。"},{"id":"pd-20746","module":"panduan","diff":1,"exam":"国考","prompt":"如果土壤肥沃，那么作物长势良好。现已确认作物长势不好。由此可以推出：","options":["如果土壤贫瘠，那么作物长势不好","土壤肥沃","土壤肥沃，尽管作物长势不好","土壤贫瘠"],"answer":3,"explanation":"充分条件命题否定后件就要否定前件。由作物长势不好，可以推出土壤贫瘠；其余选项均不能由题干必然推出。故选D。"},{"id":"pd-20747","module":"panduan","diff":2,"exam":"国考","prompt":"小陈、小杨、小吴、小周、小孙五人比较体重。已知：小杨比小孙重；小陈比小杨重；小孙比小吴重；小杨比小周重。这五人的体重从重到轻排序，谁排第一？","options":["小孙","小吴","小周","小陈"],"answer":3,"explanation":"由题干条件逐步推理，可得五人体重从重到轻的完整排序为：小陈＞小杨＞小孙＞小吴＞小周。因此排第一的是小陈。故选D。"},{"id":"pd-20748","module":"panduan","diff":2,"exam":"国考","prompt":"所有的律诗都是诗歌，所有的诗歌都是文学作品。由此可以推出：","options":["所有的律诗都是文学作品","有的律诗不是文学作品","有的文学作品不是律诗","所有的文学作品都是律诗"],"answer":0,"explanation":"三段论传递推理：律诗都属于诗歌，诗歌都属于文学作品，所以所有的律诗都是文学作品；其余选项不能必然推出。故选A。"},{"id":"pd-20749","module":"panduan","diff":2,"exam":"教师编","prompt":"有的工程师是参与过项目建设的人，所有的参与过项目建设的人都是了解施工流程的人。由此可以推出：","options":["所有的工程师都是了解施工流程的人","有的工程师是了解施工流程的人","所有的了解施工流程的人都是工程师","有的工程师不是了解施工流程的人"],"answer":1,"explanation":"有的工程师是参与过项目建设的人，而参与过项目建设的人都属于了解施工流程的人，所以这部分工程师也属于了解施工流程的人，即有的工程师是了解施工流程的人；不能扩大为全称结论，其余选项均不必然成立。故选B。"},{"id":"pd-20750","module":"panduan","diff":2,"exam":"医疗编","prompt":"桌腿：桌子\n下列与题干词项逻辑关系最相近的是：","options":["眼镜：矫正视力","表扬：批评","梅：兰","表盘：手表"],"answer":3,"explanation":"题干「桌腿」与「桌子」为组成关系；「表盘」与「手表」也是组成关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20751","module":"panduan","diff":2,"exam":"医疗编","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问小赵、小钱、小孙、小周四人，四人的说法如下：小赵说：“是小周拿走钥匙的。”；小钱说：“不是我拿走钥匙的。”；小孙说：“不是我拿走钥匙的。”；小周说：“是小钱拿走钥匙的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["小周","小赵","小孙","小钱"],"answer":3,"explanation":"只有一人说真话。逐一假设验证可知，小钱的话为真，其余三人的话均为假。故选D。"},{"id":"pd-20752","module":"panduan","diff":2,"exam":"省考","prompt":"小张、小王、小李、小赵四人的爱好各不相同，分别是游泳、跑步、读书、摄影。已知：小李的爱好不是摄影；小赵的爱好是读书；小李的爱好不是游泳；小张的爱好不是跑步；小王的爱好是游泳。由此可以推出，小张的爱好是：","options":["摄影","游泳","跑步","读书"],"answer":0,"explanation":"由题干条件逐一排除可得：小张的爱好是摄影；小王的爱好是游泳；小李的爱好是跑步；小赵的爱好是读书。因此小张的爱好是摄影。故选A。"},{"id":"pd-20753","module":"panduan","diff":2,"exam":"事业编","prompt":"改善：生活\n下列与题干词项逻辑关系最相近的是：","options":["元朝：忽必烈","大鼓：打击乐器","保护：环境","兄：弟"],"answer":2,"explanation":"题干「改善」与「生活」为动宾关系；「保护」与「环境」也是动宾关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20754","module":"panduan","diff":2,"exam":"省考","prompt":"小张、小王、小李、小赵四人来自的城市各不相同，分别是北京、上海、广州、深圳。已知：小张来自的城市是广州；小李来自的城市不是深圳；小赵来自的城市不是上海；小赵来自的城市不是深圳。由此可以推出，小李来自的城市是：","options":["北京","广州","深圳","上海"],"answer":3,"explanation":"由题干条件逐一排查：小张来自广州；小李不来自深圳；小赵不来自上海；小赵不来自深圳。结合四人城市各不相同，可唯一确定小李来自上海。故选D。"},{"id":"pd-20755","module":"panduan","diff":1,"exam":"教师编","prompt":"澳大利亚：堪培拉\n下列与题干词项逻辑关系最相近的是：","options":["阻止：阻拦","工程师：党员","崎岖：山路","泰国：曼谷"],"answer":3,"explanation":"题干「澳大利亚」与「堪培拉」为国家与其首都的对应；「泰国」与「曼谷」也是国家与其首都的对应，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20756","module":"panduan","diff":3,"exam":"省考","prompt":"赵某被判处有期徒刑八个月，法院认为其情节较轻、有悔罪表现，宣告缓刑考验期一年。缓刑是指人民法院对犯罪分子判处刑罚后，附一定条件暂不执行原判刑罚的制度，适用于被判处拘役或者三年以下有期徒刑，且犯罪情节较轻、有悔罪表现、没有再犯罪的危险等情形。根据上述定义，下列同样属于缓刑的是：","options":["张某因犯罪情节较轻被判处有期徒刑一年，法院宣告两年考验期内暂不执行刑罚","冯某被判处罚金，因经济困难获准暂缓缴纳","吴某因犯罪情节恶劣被判处有期徒刑十年，仍被宣布暂不执行刑罚","郑某被判处管制，办案人员称对其适用了缓刑"],"answer":0,"explanation":"缓刑的要件是：被判处拘役或三年以下有期徒刑、情节较轻、有悔罪表现、暂不执行刑罚。「张某因犯罪情节较轻被判处有期徒刑一年，法院宣告两年考验期内暂不执行刑罚」完全符合上述要件；其余选项分别存在以下问题：刑期超过三年有期徒刑，不符合缓刑适用条件；管制不属于缓刑的适用对象；暂缓缴纳罚金不是缓刑制度。故选A。"},{"id":"pd-20757","module":"panduan","diff":3,"exam":"国考","prompt":"某地开展文明宣传活动后，乱扔垃圾现象明显减少，因此主办方认为宣传活动成效显著。以下哪项如果为真，最能削弱该结论？","options":["宣传材料印制精美","宣传活动持续了一个月","部分志愿者参与了宣传活动","同期该地增设了数百个垃圾桶，并大幅增加了保洁频次"],"answer":3,"explanation":"增设垃圾桶和保洁频次才是乱扔垃圾减少的原因，属于另有他因。故选D。"},{"id":"pd-20758","module":"panduan","diff":2,"exam":"国考","prompt":"有的工人是参加过培训的人，所有的参加过培训的人都是获得证书的人。由此可以推出：","options":["所有的工人都是获得证书的人","有的工人是获得证书的人","所有的获得证书的人都是工人","有的工人不是获得证书的人"],"answer":1,"explanation":"有的工人是参加过培训的人，而参加过培训的人都属于获得证书的人，所以这部分工人也属于获得证书的人，即有的工人是获得证书的人；不能扩大为全称结论，其余选项均不必然成立。故选B。"},{"id":"pd-20759","module":"panduan","diff":3,"exam":"省考","prompt":"只有小华考试通过，才小华认真复习。现已确认小华认真复习。由此可以推出：","options":["小华考试没通过","只有小华认真复习，才小华考试通过","如果小华考试通过，那么小华认真复习","小华考试通过"],"answer":3,"explanation":"「只有小华考试通过，才小华认真复习」中，小华考试通过是小华认真复习的必要条件，肯定后件就要肯定前件。现已确认小华认真复习，属于肯定后件，故小华考试通过必然成立，即小华考试通过；肯定前件不能推出后件，其余选项均不能必然推出。故选D。"},{"id":"pd-20760","module":"panduan","diff":2,"exam":"省考","prompt":"表盘：手表\n下列与题干词项逻辑关系最相近的是：","options":["坚强：顽强","灿烂：文化","章节：小说","端正：态度"],"answer":2,"explanation":"题干「表盘」与「手表」为组成关系；「章节」与「小说」也是组成关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20761","module":"panduan","diff":3,"exam":"国考","prompt":"隋朝：杨坚\n下列与题干词项逻辑关系最相近的是：","options":["护士：注射器","日本：东京","元朝：忽必烈","眼镜：矫正视力"],"answer":2,"explanation":"题干「隋朝」与「杨坚」为朝代与其建立者的对应；「元朝」与「忽必烈」也是朝代与其建立者的对应，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20762","module":"panduan","diff":1,"exam":"省考","prompt":"货车刹车失灵冲下陡坡，司机为避免撞上人群，果断打方向盘撞向路边无人围墙。紧急避险是指为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在发生的危险，不得已采取的损害另一较小合法权益的行为。根据上述定义，下列同样属于紧急避险的是：","options":["杨某家中停电闷热，撬开邻居家的空调房进屋避暑","陈某为省过路费，谎称车内装有危险品强行闯卡，撞坏道口栏杆","刘某为躲避债主催债，跳入他人鱼塘躲藏，造成大量鱼群死亡","货轮遇特大风暴即将倾覆，船长下令抛货减损，保住了全船人员的安全"],"answer":3,"explanation":"紧急避险的要件是：危险正在发生、不得已而为之、损害的是另一较小合法权益。「货轮遇特大风暴即将倾覆，船长下令抛货减损，保住了全船人员的安全」完全符合上述要件；其余选项分别存在以下问题：债务纠纷不属于正在发生的危险；危险系本人虚构，并非真实存在的危险；不存在正在发生的危险，且损害他人合法权益无正当性。故选D。"},{"id":"pd-20763","module":"panduan","diff":2,"exam":"省考","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“是李四拿走钥匙的。”；李四说：“是赵六拿走钥匙的。”；王五说：“不是我拿走钥匙的。”；赵六说：“是李四拿走钥匙的。”。四人中只有1人说真话。由此可以推出，拿走钥匙的是：","options":["赵六","王五","李四","张三"],"answer":3,"explanation":"只有一人说真话。逐一假设验证：只有假设张三拿走钥匙时，四句话中为真的才恰好1句，符合题干条件，故张三拿走钥匙。故选D。"},{"id":"pd-20764","module":"panduan","diff":2,"exam":"国考","prompt":"水彩画：绘画\n下列与题干词项逻辑关系最相近的是：","options":["勤奋：勤恳","含糊：模糊","坚强：顽强","豆浆：饮品"],"answer":3,"explanation":"题干「水彩画」与「绘画」为种属包含关系；「豆浆」与「饮品」也是种属包含关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20765","module":"panduan","diff":1,"exam":"国考","prompt":"班里发生了一件事：桌上的零食不见了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“是乙拿走零食的。”；乙说：“是丁拿走零食的。”；丙说：“是乙拿走零食的。”；丁说：“不是我拿走零食的。”。四人中只有3人说真话。由此可以推出，拿走零食的是：","options":["甲","丙","乙","丁"],"answer":2,"explanation":"只有三人说假话。逐一假设验证：只有假设乙拿走零食时，四句话中为假的才恰好3句，符合题干条件，故乙拿走零食。故选C。"},{"id":"pd-20766","module":"panduan","diff":2,"exam":"国考","prompt":"公司设立质量奖表彰先进员工。全面质量管理是指以质量为中心，全员参与，通过全过程控制来持续改进产品和服务质量的管理方法。根据上述定义，下列不属于全面质量管理的是：","options":["某工厂从原料进厂、生产过程到出厂检验层层把关，全体员工参与质量改进小组","公司组织各部门员工共同分析质量问题的成因，持续优化每个环节","企业扩大生产线以提高产量","服务企业对售前、售中、售后各环节进行质量控制，并鼓励全员提出改进建议"],"answer":2,"explanation":"全面质量管理的要件是：以质量为中心、全员参与、全过程控制、持续改进。「企业扩大生产线以提高产量」不符合要件：扩大产量与质量管理无关；其余选项均符合全面质量管理的全部要件。故选C。"},{"id":"pd-20767","module":"panduan","diff":3,"exam":"省考","prompt":"甲、乙、丙、丁、戊五人比较身高。已知：丙比丁高；乙比丁高；甲比戊高；丁比甲高；丙不是最高的。这五人的身高从高到矮排序，谁排第二？","options":["戊","甲","乙","丙"],"answer":3,"explanation":"由题干条件逐步推理，可得五人身高从高到矮的完整排序为：乙＞丙＞丁＞甲＞戊。因此排第二的是丙。故选D。"},{"id":"pd-20768","module":"panduan","diff":3,"exam":"国考","prompt":"小张、小王、小李、小赵、小刘五人比较跳远成绩。已知：小张比小王远；小张比小赵远；小张比小李远；小张比小刘远。这五人的跳远成绩从远到近排序，谁排第一？","options":["小王","小李","小赵","小张"],"answer":3,"explanation":"由题干条件逐步推理，可得五人跳远成绩从远到近的完整排序为：小张＞小李＞小王＞小刘＞小赵。因此排第一的是小张。故选D。"},{"id":"pd-20769","module":"panduan","diff":3,"exam":"省考","prompt":"教师：学校\n下列与题干词项逻辑关系最相近的是：","options":["军人：军营","日：月","突然：忽然","增加：减少"],"answer":0,"explanation":"题干「教师」与「学校」为职业与其工作场所的对应；「军人」与「军营」也是职业与其工作场所的对应，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20770","module":"panduan","diff":1,"exam":"国考","prompt":"画家：教师\n下列与题干词项逻辑关系最相近的是：","options":["表扬：批评","骏马：奔驰","廉价：昂贵","医生：作家"],"answer":3,"explanation":"题干「画家」与「教师」为交叉关系；「医生」与「作家」也是交叉关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20771","module":"panduan","diff":2,"exam":"国考","prompt":"航空公司头等舱票价高于经济舱。价格歧视是指经营者对相同的商品或服务，向不同的购买者收取不同价格的行为，且这种价格差异并非基于成本差异。根据上述定义，下列不属于价格歧视的是：","options":["同一航班同一舱位，提前一个月购票三百元，临起飞购票一千五百元","超市对临期食品打折促销","视频网站对同一部影片，学生会员半价，普通会员全价","景区对本地游客和外地游客收取不同门票价格"],"answer":1,"explanation":"价格歧视的要件是：相同商品或服务、不同购买者、价格差异并非源于成本差异。「超市对临期食品打折促销」不符合要件：商品状态不同，价格差异基于商品差异；其余选项均符合价格歧视的全部要件。故选B。"},{"id":"pd-20772","module":"panduan","diff":2,"exam":"国考","prompt":"生存：死亡\n下列与题干词项逻辑关系最相近的是：","options":["输入：输出","手指：手","咖啡：饮品","湖北：武汉"],"answer":0,"explanation":"题干「生存」与「死亡」为反义关系；「输入」与「输出」也是反义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20773","module":"panduan","diff":2,"exam":"省考","prompt":"政府减税使居民可支配收入增加。挤出效应是指政府增加支出或发行公债融资时，引起利率上升，导致私人投资或消费减少的现象。根据上述定义，下列不属于挤出效应的是：","options":["企业因市场需求旺盛而扩大投资","政府举债投资大型项目，资金市场趋紧，中小企业贷款难度加大、投资缩减","政府大规模发行国债筹集基建资金，市场利率上升，某民营企业因融资成本过高取消了扩建计划","财政大幅扩大支出后，银行贷款利率上行，居民住房贷款成本增加，购房意愿下降"],"answer":0,"explanation":"挤出效应的要件是：政府支出或发债融资、利率上升、私人投资或消费被挤减。「企业因市场需求旺盛而扩大投资」不符合要件：投资扩大由市场需求驱动，与政府支出无关；其余选项均符合挤出效应的全部要件。故选A。"},{"id":"pd-20774","module":"panduan","diff":1,"exam":"教师编","prompt":"天平：称重\n下列与题干词项逻辑关系最相近的是：","options":["前进：后退","埃及：开罗","空调：制冷","风：雨"],"answer":2,"explanation":"题干「天平」与「称重」为事物与其功能的对应；「空调」与「制冷」也是事物与其功能的对应，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20775","module":"panduan","diff":1,"exam":"国考","prompt":"某中学统一要求学生穿校服后，学生成绩有所提高，校方认为是穿校服提升了学习专注度。以下哪项如果为真，最能削弱校方的观点？","options":["同期学校还聘请了名师团队，并全面改革了教学方法","该校学生的出勤率一直很高","穿校服减少了学生之间的攀比现象","校服的款式由学生代表参与设计"],"answer":0,"explanation":"师资和教学改革才是成绩提高的原因，属于另有他因。故选A。"},{"id":"pd-20776","module":"panduan","diff":1,"exam":"国考","prompt":"并非（坚持练习口语并且口语水平提高）。由此可以推出：","options":["不坚持练习口语或者口语水平没有提高","不坚持练习口语并且口语水平没有提高","如果不坚持练习口语，那么口语水平提高","坚持练习口语或者口语水平提高"],"answer":0,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（坚持练习口语并且口语水平提高），等值于“不坚持练习口语或者口语水平没有提高”；其余选项均不符合德摩根定律。故选A。"},{"id":"pd-20777","module":"panduan","diff":1,"exam":"国考","prompt":"小狗多次尝试跳出隔板均告失败后，即使隔板降低也不再尝试。习得性无助是指个体经历反复失败或挫折后，感到一切都无法控制，从而产生无能为力、放弃努力的心理状态。根据上述定义，下列同样属于习得性无助的是：","options":["小赵多次数学考试不及格后，即使题目很简单也不再尝试作答，认为自己天生学不会","小钱考试失利后总结教训，加倍努力备考","小吴第一次学游泳呛水，有些害怕但仍坚持练习","小孙因身体不适暂停训练，康复后继续投入"],"answer":0,"explanation":"习得性无助的要件是：反复失败或挫折、感到无法控制、放弃努力。「小赵多次数学考试不及格后，即使题目很简单也不再尝试作答，认为自己天生学不会」完全符合上述要件；其余选项分别存在以下问题：失败后积极归因并加倍努力，与放弃努力相反；初次挫折后仍坚持尝试，未形成无助感；暂停训练有客观原因，并非放弃努力。故选A。"},{"id":"pd-20778","module":"panduan","diff":2,"exam":"事业编","prompt":"某公司认为，提高工资水平能够有效留住员工。上述论证最可能基于的前提是：","options":["员工对工作环境较为满意","公司经营状况良好","同行业工资水平差异较大","工资水平是员工选择去留的主要考虑因素"],"answer":3,"explanation":"若员工去留主要取决于其他因素，提高工资便难以留人，该项是论证成立的必要前提。故选D。"},{"id":"pd-20779","module":"panduan","diff":3,"exam":"国考","prompt":"如果坚持储蓄，那么积蓄增加。现已确认积蓄没有增加。由此可以推出：","options":["如果没有坚持储蓄，那么积蓄没有增加","坚持储蓄，尽管积蓄没有增加","坚持储蓄","没有坚持储蓄"],"answer":3,"explanation":"充分条件命题否定后件就要否定前件。由积蓄没有增加，可以推出没有坚持储蓄；其余选项均不能由题干必然推出。故选D。"},{"id":"pd-20780","module":"panduan","diff":2,"exam":"国考","prompt":"班里发生了一件事：桌上的零食不见了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“不是我拿走零食的。”；乙说：“是甲拿走零食的。”；丙说：“不是我拿走零食的。”；丁说：“是甲拿走零食的。”。四人中只有1人说真话。由此可以推出，拿走零食的是：","options":["丁","甲","乙","丙"],"answer":3,"explanation":"只有一人说真话。逐一假设验证：只有假设丙拿走零食时，四句话中为真的才恰好1句，符合题干条件，故丙拿走零食。故选D。"},{"id":"pd-20781","module":"panduan","diff":3,"exam":"国考","prompt":"甲、乙、丙、丁、戊五人比较考试成绩。已知：甲比丙好；甲比戊好；甲比丁好；丙比戊好；甲不是最好的。这五人的考试成绩从好到差排序，谁排第一？","options":["丁","戊","乙","丙"],"answer":2,"explanation":"由题干条件逐步推理，可得五人考试成绩从好到差的完整排序为：乙＞甲＞丙＞丁＞戊。因此排第一的是乙。故选C。"},{"id":"pd-20782","module":"panduan","diff":3,"exam":"医疗编","prompt":"某家庭收入提高后，食品支出占消费总支出的比重从百分之四十降至百分之二十五。恩格尔系数是食品支出总额占个人消费支出总额的比重，通常用于衡量生活水平，系数越低说明生活水平越高。根据上述定义，下列同样属于恩格尔系数的是：","options":["某家庭食品支出的绝对金额逐年增加","某家庭购买奢侈品的支出大幅增加","某地区消费结构升级，食品支出占比逐年下降，生活水平明显提高","某国物价普遍上涨导致消费总支出增加"],"answer":2,"explanation":"恩格尔系数的要件是：食品支出占消费总支出的比重、反映生活水平。「某地区消费结构升级，食品支出占比逐年下降，生活水平明显提高」完全符合上述要件；其余选项分别存在以下问题：食品支出绝对额不等于其占消费总支出的比重；奢侈品支出不属于食品支出占比的范畴；物价上涨影响的是支出总额，不是食品支出占比。故选C。"},{"id":"pd-20783","module":"panduan","diff":3,"exam":"省考","prompt":"鞋带：鞋子\n下列与题干词项逻辑关系最相近的是：","options":["纽扣：衣服","含糊：模糊","陌生：熟悉","端午节：五月初五"],"answer":0,"explanation":"题干「鞋带」与「鞋子」为组成关系；「纽扣」与「衣服」也是组成关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20784","module":"panduan","diff":3,"exam":"国考","prompt":"甲、乙、丙、丁四人的职业各不相同，分别是教师、医生、律师、工程师。已知：丙的职业不是医生；丙的职业是工程师；丙的职业不是教师；乙的职业不是教师；甲的职业是律师。由此可以推出，乙的职业是：","options":["教师","律师","医生","工程师"],"answer":2,"explanation":"由题干条件逐一排除可得：甲的职业是律师；乙的职业是医生；丙的职业是工程师；丁的职业是教师。因此乙的职业是医生。故选C。"},{"id":"pd-20785","module":"panduan","diff":3,"exam":"国考","prompt":"甲、乙、丙、丁四人的爱好各不相同，分别是游泳、跑步、读书、摄影。已知：乙的爱好是读书；丁的爱好不是游泳；甲的爱好不是摄影；丙的爱好是摄影。由此可以推出，甲的爱好是：","options":["读书","跑步","游泳","摄影"],"answer":2,"explanation":"由题干条件逐一排除可得：甲的爱好是游泳；乙的爱好是读书；丙的爱好是摄影；丁的爱好是跑步。因此甲的爱好是游泳。故选C。"},{"id":"pd-20786","module":"panduan","diff":1,"exam":"医疗编","prompt":"一律：全部\n下列与题干词项逻辑关系最相近的是：","options":["美丽：漂亮","横梁：房屋","光明：黑暗","昆虫：节肢动物"],"answer":0,"explanation":"题干「一律」与「全部」为近义关系；「美丽」与「漂亮」也是近义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20787","module":"panduan","diff":2,"exam":"国考","prompt":"某品牌牙膏宣称能显著防蛀，理由是其使用者的蛀牙率明显低于平均水平。以下哪项如果为真，最能削弱该宣称？","options":["该牙膏有多种口味可供选择","该牙膏的价格略高于普通牙膏","使用该牙膏的多为口腔护理意识强、定期检查牙齿的人群","牙膏的主要成分大同小异"],"answer":2,"explanation":"使用者本身口腔护理习惯好才是蛀牙率低的原因，属于另有他因，削弱了牙膏与防蛀的因果联系。故选C。"},{"id":"pd-20788","module":"panduan","diff":1,"exam":"省考","prompt":"桥墩：桥梁\n下列与题干词项逻辑关系最相近的是：","options":["云南：昆明","屋顶：房子","精神：饱满","支持：反对"],"answer":1,"explanation":"题干「桥墩」与「桥梁」为组成关系；「屋顶」与「房子」也是组成关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20789","module":"panduan","diff":3,"exam":"国考","prompt":"街头一位老人摔倒，围观者众多，人人都觉得总会有人去扶，结果无人上前。责任分散效应是指在群体情境中，个体感到责任被分散到他人身上，从而减少个人援助或努力的现象。根据上述定义，下列同样属于责任分散效应的是：","options":["小组作业中，组员们互相观望，都觉得别人会做，结果进度一拖再拖","救援队分工明确，各成员各司其职","值班员小王发现火情后立即报警并组织疏散","小赵独自路过，毫不犹豫扶起摔倒的老人"],"answer":0,"explanation":"责任分散效应的要件是：群体情境、责任被分散到他人身上、个人努力或援助减少。「小组作业中，组员们互相观望，都觉得别人会做，结果进度一拖再拖」完全符合上述要件；其余选项分别存在以下问题：责任明确到人，不存在责任分散；单人情境下没有可分散责任的对象；分工明确使责任落实到个人。故选A。"},{"id":"pd-20790","module":"panduan","diff":2,"exam":"国考","prompt":"甲、乙、丙、丁、戊五人比较考试成绩。已知：甲比戊好；丙比乙好；甲比丙好；丁比甲好。这五人的考试成绩从好到差排序，谁排第二？","options":["戊","丙","甲","乙"],"answer":2,"explanation":"由题干条件逐步推理，可得五人考试成绩从好到差的完整排序为：丁＞甲＞戊＞丙＞乙。因此排第二的是甲。故选C。"},{"id":"pd-20791","module":"panduan","diff":1,"exam":"国考","prompt":"洗衣机：洗涤衣物\n下列与题干词项逻辑关系最相近的是：","options":["农民：企业家","埃及：开罗","四川：成都","钥匙：开锁"],"answer":3,"explanation":"题干「洗衣机」与「洗涤衣物」为事物与其功能的对应；「钥匙」与「开锁」也是事物与其功能的对应，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20792","module":"panduan","diff":2,"exam":"国考","prompt":"并非（团队分工明确并且工作效率提高）。由此可以推出：","options":["团队分工不明确并且工作效率没有提高","团队分工明确或者工作效率提高","团队分工不明确或者工作效率没有提高","如果团队分工不明确，那么工作效率提高"],"answer":2,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（团队分工明确并且工作效率提高），等值于“团队分工不明确或者工作效率没有提高”；其余选项均不符合德摩根定律。故选C。"},{"id":"pd-20793","module":"panduan","diff":2,"exam":"国考","prompt":"崎岖：山路\n下列与题干词项逻辑关系最相近的是：","options":["阳光：明媚","摄影师：相机","诚实：虚伪","崭新：面貌"],"answer":3,"explanation":"题干「崎岖」与「山路」为偏正关系；「崭新」与「面貌」也是偏正关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20794","module":"panduan","diff":2,"exam":"省考","prompt":"小郑酷爱运动，便想当然地认为同事们都喜欢户外活动。投射效应是指将自己具有的特质归因到他人身上的心理倾向，即以己度人。根据上述定义，下列同样属于投射效应的是：","options":["小钱根据小赵的实际工作表现对他作出评价","小吴通过问卷调查了解顾客的真实偏好","小周自己嗜辣，便以为所有客人都爱吃辣，点菜全点辣菜","小陈设身处地为他人着想，努力理解对方的真实感受"],"answer":2,"explanation":"投射效应的要件是：以自己的特质、推测他人也具有同样的特质。「小周自己嗜辣，便以为所有客人都爱吃辣，点菜全点辣菜」完全符合上述要件；其余选项分别存在以下问题：通过调查了解他人，不是以己度人；共情是理解他人感受，不是把自己的特质加于他人；依据实际表现评价，不属于投射。故选C。"},{"id":"pd-20795","module":"panduan","diff":2,"exam":"教师编","prompt":"某工厂从原料进厂、生产过程到出厂检验层层把关，全体员工参与质量改进小组。全面质量管理是指以质量为中心，全员参与，通过全过程控制来持续改进产品和服务质量的管理方法。根据上述定义，下列同样属于全面质量管理的是：","options":["服务企业对售前、售中、售后各环节进行质量控制，并鼓励全员提出改进建议","质检员在成品出厂前进行抽检","公司设立质量奖表彰先进员工","企业扩大生产线以提高产量"],"answer":0,"explanation":"全面质量管理的要件是：以质量为中心、全员参与、全过程控制、持续改进。「服务企业对售前、售中、售后各环节进行质量控制，并鼓励全员提出改进建议」完全符合上述要件；其余选项分别存在以下问题：仅末端检验，未体现全员全过程控制；表彰激励不等于全面质量管理；扩大产量与质量管理无关。故选A。"},{"id":"pd-20796","module":"panduan","diff":2,"exam":"国考","prompt":"长笛：管乐器\n下列与题干词项逻辑关系最相近的是：","options":["洗衣机：洗涤衣物","香蕉：水果","江苏：南京","完整：残缺"],"answer":1,"explanation":"题干「长笛」与「管乐器」为种属包含关系；「香蕉」与「水果」也是种属包含关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20797","module":"panduan","diff":2,"exam":"国考","prompt":"印度：新德里\n下列与题干词项逻辑关系最相近的是：","options":["冰箱：家电","中国：北京","农民：锄头","蝴蝶：昆虫"],"answer":1,"explanation":"题干「印度」与「新德里」为国家与其首都的对应；「中国」与「北京」也是国家与其首都的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20798","module":"panduan","diff":2,"exam":"教师编","prompt":"前进：后退\n下列与题干词项逻辑关系最相近的是：","options":["集中：分散","演员：歌手","普洱茶：云南","冰箱：家电"],"answer":0,"explanation":"题干「前进」与「后退」为反义关系；「集中」与「分散」也是反义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20799","module":"panduan","diff":3,"exam":"省考","prompt":"原材料市场价格普遍上涨导致企业成本上升。规模经济是指随着生产规模扩大，单位产品的平均成本下降的现象。根据上述定义，下列不属于规模经济的是：","options":["某小作坊产量增加一倍，但因管理混乱单位成本不降反升","某汽车厂年产量从十万辆提高到五十万辆后，单辆车分摊的研发和管理成本大幅下降","某工厂扩大生产线后，单位产品分摊的固定费用明显减少","连锁超市统一采购货物，采购量越大，单件商品的进货成本越低"],"answer":0,"explanation":"规模经济的要件是：生产规模扩大、单位产品平均成本下降。「某小作坊产量增加一倍，但因管理混乱单位成本不降反升」不符合要件：规模扩大而单位成本上升，属于规模不经济；其余选项均符合规模经济的全部要件。故选A。"},{"id":"pd-20800","module":"panduan","diff":2,"exam":"国考","prompt":"苹果：水果\n下列与题干词项逻辑关系最相近的是：","options":["裙子：服装","一律：全部","树叶：树木","手电筒：照明"],"answer":0,"explanation":"题干「苹果」与「水果」为种属包含关系；「裙子」与「服装」也是种属包含关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20801","module":"panduan","diff":1,"exam":"教师编","prompt":"某企业租用云端计算资源完成大规模数据运算，按用量付费。云计算是指通过网络以按需、易扩展的方式获取计算资源（服务器、存储、软件等）的服务模式，用户无需自建基础设施。根据上述定义，下列同样属于云计算的是：","options":["公司自建机房并配备专职运维团队","单位在内网搭建共享文件夹供同事下载","小李将文件拷贝到自己的移动硬盘保存","某创业公司按使用量租用云服务器存放数据并运行网站，无需自购机房设备"],"answer":3,"explanation":"云计算的要件是：通过网络按需获取计算资源、无需自建基础设施、易扩展。「某创业公司按使用量租用云服务器存放数据并运行网站，无需自购机房设备」完全符合上述要件；其余选项分别存在以下问题：自建基础设施与云计算模式相反；本地存储未通过网络按需获取资源；局域网共享不属于按需获取云端计算资源。故选D。"},{"id":"pd-20802","module":"panduan","diff":3,"exam":"省考","prompt":"如果坚持练习口语，那么口语水平提高。现已确认口语水平没有提高。由此可以推出：","options":["坚持练习口语","不坚持练习口语","如果不坚持练习口语，那么口语水平没有提高","坚持练习口语，尽管口语水平没有提高"],"answer":1,"explanation":"充分条件命题否定后件就要否定前件。由口语水平没有提高，可以推出不坚持练习口语；其余选项均不能由题干必然推出。故选B。"},{"id":"pd-20803","module":"panduan","diff":2,"exam":"省考","prompt":"所有的篮球都是球类运动，所有的球类运动都是体育运动。由此可以推出：","options":["有的体育运动不是篮球","有的篮球不是体育运动","所有的篮球都是体育运动","所有的体育运动都是篮球"],"answer":2,"explanation":"三段论传递推理：篮球都属于球类运动，球类运动都属于体育运动，所以所有的篮球都是体育运动；其余选项不能必然推出。故选C。"},{"id":"pd-20804","module":"panduan","diff":1,"exam":"教师编","prompt":"大家因为多数人同意而改变了自己的意见。晕轮效应是指对人的某个特征形成印象后，掩盖了其他方面的特征，即以点概面、以偏概全的心理现象。根据上述定义，下列不属于晕轮效应的是：","options":["小钱认为北方人都豪爽大方","小赵见对方谈吐文雅，便认定其必然诚实可靠、能力出众","经理因小吴业绩突出，便认为他品行也一定过硬，委以重任","老李因某人外表出众，便觉得他各方面都很优秀"],"answer":0,"explanation":"晕轮效应的要件是：由某一特征出发、推及并掩盖其他特征、以点概面。「小钱认为北方人都豪爽大方」不符合要件：对群体的固定看法属于刻板印象；其余选项均符合晕轮效应的全部要件。故选A。"},{"id":"pd-20805","module":"panduan","diff":2,"exam":"医疗编","prompt":"某软件通过学习数万份病历，能够辅助医生对影像进行病变识别并给出诊断建议。人工智能是指用计算机系统模拟、延伸和扩展人类的智能活动，使其能够学习、推理、决策并完成通常需要人类智能才能完成的任务的技术。根据上述定义，下列同样属于人工智能的是：","options":["流水线机械臂按预设动作重复搬运货物","智能音箱能理解用户的语音指令，与用户对话并推荐歌曲","电子表格软件自动对数据求和","计算器快速完成四则运算"],"answer":1,"explanation":"人工智能的要件是：计算机系统、模拟人类智能、具备学习推理决策能力。「智能音箱能理解用户的语音指令，与用户对话并推荐歌曲」完全符合上述要件；其余选项分别存在以下问题：计算器按固定程序运算，不具备学习推理能力；机械臂执行预设动作，无智能决策；自动求和是固定功能，不涉及智能活动。故选B。"},{"id":"pd-20806","module":"panduan","diff":3,"exam":"国考","prompt":"某会议购买林业碳汇抵消活动产生的全部碳排放，实现碳中和办会。碳中和是指在一定时期内，通过植树造林、节能减排等方式，抵消自身产生的二氧化碳排放，实现二氧化碳净零排放。根据上述定义，下列同样属于碳中和的是：","options":["企业新增两条高排放生产线","某家庭通过节约用电减少了部分碳排放","某城市通过能源转型与森林碳汇，使全市年度碳排放与吸收相抵","某市推广新能源汽车以减少尾气排放"],"answer":2,"explanation":"碳中和的要件是：一定时期内、以植树造林或节能减排等方式抵消排放、实现净零排放。「某城市通过能源转型与森林碳汇，使全市年度碳排放与吸收相抵」完全符合上述要件；其余选项分别存在以下问题：排放增加，与净零排放目标相反；仅减少部分排放，未实现抵消与净零；减排措施本身不等于实现碳中和。故选C。"},{"id":"pd-20807","module":"panduan","diff":1,"exam":"事业编","prompt":"公开：秘密\n下列与题干词项逻辑关系最相近的是：","options":["七夕节：七月初七","完整：残缺","《雷雨》：曹禺","桌腿：桌子"],"answer":1,"explanation":"题干「公开」与「秘密」为反义关系；「完整」与「残缺」也是反义关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20808","module":"panduan","diff":1,"exam":"省考","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问小陈、小杨、小吴、小郑四人，四人的说法如下：小陈说：“不是我拿走钥匙的。”；小杨说：“是小陈拿走钥匙的。”；小吴说：“是小杨拿走钥匙的。”；小郑说：“不是我拿走钥匙的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["小郑","小吴","小陈","小杨"],"answer":2,"explanation":"只有一人说真话。逐一假设验证可知，小陈的话为真，其余三人的话均为假。故选C。"},{"id":"pd-20809","module":"panduan","diff":2,"exam":"国考","prompt":"小区几户居民自筹资金安装楼道照明灯，未出资的住户同样享受照明便利。搭便车是指不承担任何成本而坐享他人行为所带来的利益的行为。根据上述定义，下列同样属于搭便车的是：","options":["小赵购买了演唱会门票入场观看","物业公司按合同提供保洁服务并收取物业费","会员付费观看网络剧","某企业投入巨资研发新技术并公开专利，同行业未投入的企业直接借鉴该技术获利"],"answer":3,"explanation":"搭便车的要件是：不承担成本、坐享他人行为带来的利益。「某企业投入巨资研发新技术并公开专利，同行业未投入的企业直接借鉴该技术获利」完全符合上述要件；其余选项分别存在以下问题：购票观看支付了成本；服务有合同对价，权利义务对等；付费享受服务，未坐享他人成果。故选D。"},{"id":"pd-20810","module":"panduan","diff":1,"exam":"国考","prompt":"只有积蓄增加，才坚持储蓄。现已确认坚持储蓄。由此可以推出：","options":["积蓄没有增加","如果积蓄增加，那么坚持储蓄","只有坚持储蓄，才积蓄增加","积蓄增加"],"answer":3,"explanation":"「只有积蓄增加，才坚持储蓄」中，积蓄增加是坚持储蓄的必要条件，肯定后件就要肯定前件。现已确认坚持储蓄，属于肯定后件，故积蓄增加必然成立，即积蓄增加；肯定前件不能推出后件，其余选项均不能必然推出。故选D。"},{"id":"pd-20811","module":"panduan","diff":3,"exam":"省考","prompt":"农民：锄头\n下列与题干词项逻辑关系最相近的是：","options":["裁缝：缝纫机","眼镜：矫正视力","沉重：打击","老虎：哺乳动物"],"answer":0,"explanation":"题干「农民」与「锄头」为职业与其专用工具的对应；「裁缝」与「缝纫机」也是职业与其专用工具的对应，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20812","module":"panduan","diff":2,"exam":"医疗编","prompt":"某公司与供货商签订购销合同，约定货物的规格和价款。劳动合同是劳动者与用人单位确立劳动关系、明确双方权利义务的协议，其内容一般包括工作内容、劳动报酬、社会保险等条款。根据上述定义，下列不属于劳动合同的是：","options":["小赵入职某科技公司，双方签订书面协议，约定了岗位职责、工资标准和社会保险","某商场与聘用的营业员签订协议，约定工作内容、工作时间及劳动报酬","某工厂与新招用的工人订立协议，明确了工种、劳动报酬和劳动保护条件","小孙利用业余时间发传单，按次结算报酬"],"answer":3,"explanation":"劳动合同的要件是：劳动者与用人单位之间、确立劳动关系、明确双方权利义务。「小孙利用业余时间发传单，按次结算报酬」不符合要件：按次结算的临时劳务未确立劳动关系；其余选项均符合劳动合同的全部要件。故选D。"},{"id":"pd-20813","module":"panduan","diff":2,"exam":"国考","prompt":"元朝：忽必烈\n下列与题干词项逻辑关系最相近的是：","options":["唐朝：李渊","大闸蟹：阳澄湖","昆虫：节肢动物","飞行员：驾驶舱"],"answer":0,"explanation":"题干「元朝」与「忽必烈」为朝代与其建立者的对应；「唐朝」与「李渊」也是朝代与其建立者的对应，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20814","module":"panduan","diff":2,"exam":"国考","prompt":"赵某向某家具店表示：愿以标价购买该款沙发一张，当场付款。要约是希望与他人订立合同的意思表示，内容具体确定，并表明经受要约人承诺，要约人即受该意思表示约束。根据上述定义，下列同样属于要约的是：","options":["钱某与朋友闲聊时说真想买辆车，未提任何具体条件","甲公司向乙公司询问：你们的水泥多少钱一吨","某公司发布广告称：本月商品一律八折，欢迎选购","某公司向合作方发出订单：订购某型号水泥200吨，单价及交货时间均已明确"],"answer":3,"explanation":"要约的要件是：内容具体确定、表明经承诺即受约束、向希望缔约的相对人发出。「某公司向合作方发出订单：订购某型号水泥200吨，单价及交货时间均已明确」完全符合上述要件；其余选项分别存在以下问题：商业广告内容不具体，属于要约邀请；意思表示内容不具体确定；询价行为不含有订立合同的确定意思。故选D。"},{"id":"pd-20815","module":"panduan","diff":2,"exam":"教师编","prompt":"班里发生了一件事：刚拖过的地面被踩脏了。老师询问小赵、小钱、小孙、小周四人，四人的说法如下：小赵说：“不是我踩脏地面的。”；小钱说：“是小赵踩脏地面的。”；小孙说：“是小赵踩脏地面的。”；小周说：“不是我踩脏地面的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["小钱","小周","小孙","小赵"],"answer":3,"explanation":"只有一人说真话。逐一假设验证可知，小赵的话为真，其余三人的话均为假。故选D。"},{"id":"pd-20816","module":"panduan","diff":2,"exam":"国考","prompt":"小赵见对方谈吐文雅，便认定其必然诚实可靠、能力出众。晕轮效应是指对人的某个特征形成印象后，掩盖了其他方面的特征，即以点概面、以偏概全的心理现象。根据上述定义，下列同样属于晕轮效应的是：","options":["大家因为多数人同意而改变了自己的意见","经理因小吴业绩突出，便认为他品行也一定过硬，委以重任","小钱认为北方人都豪爽大方","面试官因候选人第一印象好而打分偏高"],"answer":1,"explanation":"晕轮效应的要件是：由某一特征出发、推及并掩盖其他特征、以点概面。「经理因小吴业绩突出，便认为他品行也一定过硬，委以重任」完全符合上述要件；其余选项分别存在以下问题：第一印象影响评价属于首因效应；随大流改变意见属于从众；对群体的固定看法属于刻板印象。故选B。"},{"id":"pd-20817","module":"panduan","diff":3,"exam":"国考","prompt":"传播：文化\n下列与题干词项逻辑关系最相近的是：","options":["商量：商议","骄傲：谦虚","羽毛：鸟","承担：责任"],"answer":3,"explanation":"题干「传播」与「文化」为动宾关系；「承担」与「责任」也是动宾关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20818","module":"panduan","diff":3,"exam":"国考","prompt":"小张、小王、小李、小赵、小刘五人比较考试成绩。已知：小李比小张好；小刘比小张好；小赵比小张好；小王比小刘好；小张不是最好的。这五人的考试成绩从好到差排序，谁排最后？","options":["小张","小王","小赵","小李"],"answer":0,"explanation":"由题干条件逐步推理，可得五人考试成绩从好到差的完整排序为：小赵＞小王＞小刘＞小李＞小张。因此排最后的是小张。故选A。"},{"id":"pd-20819","module":"panduan","diff":1,"exam":"国考","prompt":"如果消防设施完好，那么火灾损失减小；如果火灾损失减小，那么人员财产更安全。由此可以推出：","options":["如果人员财产更安全，那么消防设施完好","如果火灾损失减小，那么消防设施完好","如果消防设施完好，那么人员财产更安全","如果消防设施不完好，那么人员财产安全受到威胁"],"answer":2,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果消防设施完好，那么人员财产更安全；其余选项均属无效推理。故选C。"},{"id":"pd-20820","module":"panduan","diff":3,"exam":"事业编","prompt":"张某因犯罪情节较轻被判处有期徒刑一年，法院宣告两年考验期内暂不执行刑罚。缓刑是指人民法院对犯罪分子判处刑罚后，附一定条件暂不执行原判刑罚的制度，适用于被判处拘役或者三年以下有期徒刑，且犯罪情节较轻、有悔罪表现、没有再犯罪的危险等情形。根据上述定义，下列同样属于缓刑的是：","options":["冯某被判处罚金，因经济困难获准暂缓缴纳","郑某被判处管制，办案人员称对其适用了缓刑","吴某因犯罪情节恶劣被判处有期徒刑十年，仍被宣布暂不执行刑罚","李某被判拘役三个月，因其悔罪表现好且没有再犯罪的危险，法院决定对其宣告缓刑"],"answer":3,"explanation":"缓刑的要件是：被判处拘役或三年以下有期徒刑、情节较轻、有悔罪表现、暂不执行刑罚。「李某被判拘役三个月，因其悔罪表现好且没有再犯罪的危险，法院决定对其宣告缓刑」完全符合上述要件；其余选项分别存在以下问题：刑期超过三年有期徒刑，不符合缓刑适用条件；管制不属于缓刑的适用对象；暂缓缴纳罚金不是缓刑制度。故选D。"},{"id":"pd-20821","module":"panduan","diff":2,"exam":"省考","prompt":"货轮遇特大风暴即将倾覆，船长下令抛货减损，保住了全船人员的安全。紧急避险是指为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在发生的危险，不得已采取的损害另一较小合法权益的行为。根据上述定义，下列同样属于紧急避险的是：","options":["陈某为省过路费，谎称车内装有危险品强行闯卡，撞坏道口栏杆","刘某为躲避债主催债，跳入他人鱼塘躲藏，造成大量鱼群死亡","杨某家中停电闷热，撬开邻居家的空调房进屋避暑","山洪冲向村庄，村干部组织挖开低洼空地引流，淹没了闲置农田却保住了村庄"],"answer":3,"explanation":"紧急避险的要件是：危险正在发生、不得已而为之、损害的是另一较小合法权益。「山洪冲向村庄，村干部组织挖开低洼空地引流，淹没了闲置农田却保住了村庄」完全符合上述要件；其余选项分别存在以下问题：债务纠纷不属于正在发生的危险；危险系本人虚构，并非真实存在的危险；不存在正在发生的危险，且损害他人合法权益无正当性。故选D。"},{"id":"pd-20822","module":"panduan","diff":3,"exam":"事业编","prompt":"调查显示，养宠物的人患抑郁的比例更低，因此有人认为养宠物能预防抑郁。以下哪项如果为真，最能削弱该观点？","options":["养宠物需要投入一定的时间和金钱","有些人对动物毛发过敏","性格开朗、心理健康的人本来就更容易选择养宠物","宠物的种类和习性各不相同"],"answer":2,"explanation":"心理健康者更倾向养宠物，说明不是养宠物带来心理健康，属于因果倒置。故选C。"},{"id":"pd-20823","module":"panduan","diff":3,"exam":"省考","prompt":"班里发生了一件事：图书角的一本书被弄破了。老师询问小赵、小钱、小孙、小周四人，四人的说法如下：小赵说：“不是我弄破图书的。”；小钱说：“不是我弄破图书的。”；小孙说：“是小周弄破图书的。”；小周说：“是小钱弄破图书的。”。四人中只有3人说真话。由此可以推出，弄破图书的是：","options":["小赵","小周","小孙","小钱"],"answer":1,"explanation":"只有三人说假话。逐一假设验证：只有假设小周弄破图书时，四句话中为假的才恰好3句，符合题干条件，故小周弄破图书。故选B。"},{"id":"pd-20824","module":"panduan","diff":3,"exam":"医疗编","prompt":"所有的狮子都是猫科动物，所有的犬科动物都不是猫科动物。由此可以推出：","options":["有的狮子是犬科动物","有的犬科动物是狮子","所有的犬科动物都是狮子","所有的犬科动物都不是狮子"],"answer":3,"explanation":"狮子都包含于猫科动物，而犬科动物与猫科动物完全排斥，所以犬科动物与狮子也完全排斥，即所有的犬科动物都不是狮子；其余选项与题干矛盾或不能必然推出。故选D。"},{"id":"pd-20825","module":"panduan","diff":1,"exam":"教师编","prompt":"班里发生了一件事：桌上的零食不见了。老师询问小赵、小钱、小孙、小周四人，四人的说法如下：小赵说：“不是我拿走零食的。”；小钱说：“是小赵拿走零食的。”；小孙说：“是小钱拿走零食的。”；小周说：“不是我拿走零食的。”。四人中只有3人说真话。由此可以推出，拿走零食的是：","options":["小周","小钱","小孙","小赵"],"answer":1,"explanation":"只有三人说假话。逐一假设验证：只有假设小钱拿走零食时，四句话中为假的才恰好3句，符合题干条件，故小钱拿走零食。故选B。"},{"id":"pd-20826","module":"panduan","diff":2,"exam":"教师编","prompt":"服务企业对售前、售中、售后各环节进行质量控制，并鼓励全员提出改进建议。全面质量管理是指以质量为中心，全员参与，通过全过程控制来持续改进产品和服务质量的管理方法。根据上述定义，下列同样属于全面质量管理的是：","options":["质检员在成品出厂前进行抽检","企业扩大生产线以提高产量","公司设立质量奖表彰先进员工","公司组织各部门员工共同分析质量问题的成因，持续优化每个环节"],"answer":3,"explanation":"全面质量管理的要件是：以质量为中心、全员参与、全过程控制、持续改进。「公司组织各部门员工共同分析质量问题的成因，持续优化每个环节」完全符合上述要件；其余选项分别存在以下问题：仅末端检验，未体现全员全过程控制；表彰激励不等于全面质量管理；扩大产量与质量管理无关。故选D。"},{"id":"pd-20827","module":"panduan","diff":1,"exam":"国考","prompt":"某市近十年城镇人口占比从百分之四十升至百分之七十，新城区不断扩展。城市化是指人口向城镇集聚、乡村地区转变为城镇地区，城镇数量增加和规模扩大的过程。根据上述定义，下列同样属于城市化的是：","options":["某县撤县设区，大量农村人口进入城区就业定居，城区面积不断扩大","某乡实施农村危房改造，村容焕然一新","城市居民利用假期到乡村度假","某村发展乡村旅游，村民收入提高但仍从事农业生产"],"answer":0,"explanation":"城市化的要件是：人口向城镇集聚、乡村转变为城镇、城镇规模扩大。「某县撤县设区，大量农村人口进入城区就业定居，城区面积不断扩大」完全符合上述要件；其余选项分别存在以下问题：乡村发展未发生人口向城镇集聚；短期度假不是人口向城镇集聚；乡村建设未改变乡村性质。故选A。"},{"id":"pd-20828","module":"panduan","diff":1,"exam":"事业编","prompt":"某公司认为合作方违约，向仲裁委员会申请仲裁。行政复议是指公民、法人或者其他组织认为行政机关的具体行政行为侵犯其合法权益，依法向法定复议机关提出申请，由复议机关对该行政行为进行审查并作出决定的活动。根据上述定义，下列不属于行政复议的是：","options":["某企业对市场监管部门吊销营业执照的决定不服，向上一级主管部门申请审查该决定","某公司认为规划部门的许可决定侵犯其权益，依法向复议机关提出审查申请","赵某对交管部门作出的吊销驾驶证决定不服，向本级人民政府申请复议","王某向信访部门反映小区物业管理混乱问题"],"answer":3,"explanation":"行政复议的要件是：认为具体行政行为侵权、向法定复议机关申请、由复议机关审查并决定。「王某向信访部门反映小区物业管理混乱问题」不符合要件：信访不属于对具体行政行为的法定复议程序；其余选项均符合行政复议的全部要件。故选D。"},{"id":"pd-20829","module":"panduan","diff":3,"exam":"国考","prompt":"甲、乙、丙、丁、戊五人比较跑步速度。已知：丙比戊快；戊比甲快；甲比丁快；乙比丙快；丁不是最快的。这五人的跑步速度从快到慢排序，谁排第二？","options":["丙","戊","甲","乙"],"answer":0,"explanation":"由题干条件逐步推理，可得五人跑步速度从快到慢的完整排序为：乙＞丙＞戊＞甲＞丁。因此排第二的是丙。故选A。"},{"id":"pd-20830","module":"panduan","diff":2,"exam":"国考","prompt":"某公司投入五百万元研发的项目被证明技术路线错误，该投入属于沉没成本。沉没成本是指已经发生且无法收回的支出，与当前决策无关。根据上述定义，下列同样属于沉没成本的是：","options":["企业决定明年投产新设备，预计支出两百万元","工厂每月支付的水电费","老王花八十元买了电影票，看了半小时发现影片极差，票款无法退回","小李决定退掉尚未使用的健身卡，并获全额退款"],"answer":2,"explanation":"沉没成本的要件是：已经发生、无法收回、与当前决策无关。「老王花八十元买了电影票，看了半小时发现影片极差，票款无法退回」完全符合上述要件；其余选项分别存在以下问题：尚未发生的支出不是沉没成本；水电费是持续发生的可变支出；该支出可以全额收回。故选C。"},{"id":"pd-20831","module":"panduan","diff":1,"exam":"医疗编","prompt":"甲、乙、丙、丁四人的特长各不相同，分别是书法、绘画、围棋、古琴。已知：丁的特长不是绘画；甲的特长不是古琴；乙的特长不是绘画；甲的特长是围棋；乙的特长不是书法。由此可以推出，丁的特长是：","options":["古琴","书法","绘画","围棋"],"answer":1,"explanation":"由题干条件逐一排除可得：甲的特长是围棋；乙的特长是古琴；丙的特长是绘画；丁的特长是书法。因此丁的特长是书法。故选B。"},{"id":"pd-20832","module":"panduan","diff":1,"exam":"教师编","prompt":"蝴蝶：昆虫\n下列与题干词项逻辑关系最相近的是：","options":["咖啡：饮品","桌腿：桌子","沉重：轻盈","卧薪尝胆：勾践"],"answer":0,"explanation":"题干「蝴蝶」与「昆虫」为种属包含关系；「咖啡」与「饮品」也是种属包含关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20833","module":"panduan","diff":2,"exam":"省考","prompt":"某商品降价后销量大增。边际效用递减是指在一定时间内，随着消费者对某种商品消费量的连续增加，其从每增加一单位商品中所获得的效用增量是递减的。根据上述定义，下列不属于边际效用递减的是：","options":["老刘收藏邮票，最初几枚让他兴奋不已，随着数量增多，新增邮票带来的快乐逐渐下降","小郑同时消费面包和牛奶获得的满足感","炎夏口渴时，第一杯冰水让小陈感觉无比畅快，第二杯带来的满足感明显减弱","小吴连吃饺子，第一个觉得最香，越往后越觉得不过如此"],"answer":1,"explanation":"边际效用递减的要件是：连续消费同一商品、每增加一单位带来的效用增量递减。「小郑同时消费面包和牛奶获得的满足感」不符合要件：不同商品的互补消费，不是同一商品连续消费；其余选项均符合边际效用递减的全部要件。故选B。"},{"id":"pd-20834","module":"panduan","diff":3,"exam":"教师编","prompt":"屏幕：手机\n下列与题干词项逻辑关系最相近的是：","options":["勤奋：勤恳","东汉：刘秀","花瓣：花朵","《三国演义》：罗贯中"],"answer":2,"explanation":"题干「屏幕」与「手机」为组成关系；「花瓣」与「花朵」也是组成关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20835","module":"panduan","diff":1,"exam":"国考","prompt":"甲、乙、丙、丁、戊五人比较年龄。已知：甲比丁大；甲比乙大；甲比戊大；戊比乙大；甲不是最大的。这五人的年龄从大到小排序，谁排第一？","options":["丙","乙","戊","甲"],"answer":0,"explanation":"由题干条件逐步推理，可得五人年龄从大到小的完整排序为：丙＞甲＞丁＞戊＞乙。因此排第一的是丙。故选A。"},{"id":"pd-20836","module":"panduan","diff":2,"exam":"国考","prompt":"班里发生了一件事：刚拖过的地面被踩脏了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“是丙踩脏地面的。”；乙说：“不是我踩脏地面的。”；丙说：“是丁踩脏地面的。”；丁说：“是丙踩脏地面的。”。四人中只有1人说真话。由此可以推出，踩脏地面的是：","options":["丙","丁","乙","甲"],"answer":3,"explanation":"只有一人说真话。逐一假设验证：只有假设甲踩脏地面时，四句话中为真的才恰好1句，符合题干条件，故甲踩脏地面。故选D。"},{"id":"pd-20837","module":"panduan","diff":2,"exam":"事业编","prompt":"衬衫：服装\n下列与题干词项逻辑关系最相近的是：","options":["羽毛：鸟","冰箱：冷藏","鲨鱼：鱼类","完整：残缺"],"answer":2,"explanation":"题干「衬衫」与「服装」为种属包含关系；「鲨鱼」与「鱼类」也是种属包含关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20838","module":"panduan","diff":3,"exam":"国考","prompt":"砖块：墙壁\n下列与题干词项逻辑关系最相近的是：","options":["大学生：运动员","鳞片：鱼","西瓜：水果","繁荣：昌盛"],"answer":1,"explanation":"题干「砖块」与「墙壁」为组成关系；「鳞片」与「鱼」也是组成关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20839","module":"panduan","diff":1,"exam":"省考","prompt":"小吴连吃饺子，第一个觉得最香，越往后越觉得不过如此。边际效用递减是指在一定时间内，随着消费者对某种商品消费量的连续增加，其从每增加一单位商品中所获得的效用增量是递减的。根据上述定义，下列同样属于边际效用递减的是：","options":["小周工资上涨后购买的商品总量增加","炎夏口渴时，第一杯冰水让小陈感觉无比畅快，第二杯带来的满足感明显减弱","小郑同时消费面包和牛奶获得的满足感","某商品降价后销量大增"],"answer":1,"explanation":"边际效用递减的要件是：连续消费同一商品、每增加一单位带来的效用增量递减。「炎夏口渴时，第一杯冰水让小陈感觉无比畅快，第二杯带来的满足感明显减弱」完全符合上述要件；其余选项分别存在以下问题：描述的是收入变化对消费总量的影响，不是同一商品连续消费的效用变化；价格变动引起的需求变化，不是边际效用递减；不同商品的互补消费，不是同一商品连续消费。故选B。"},{"id":"pd-20840","module":"panduan","diff":2,"exam":"国考","prompt":"小组作业中，组员们互相观望，都觉得别人会做，结果进度一拖再拖。责任分散效应是指在群体情境中，个体感到责任被分散到他人身上，从而减少个人援助或努力的现象。根据上述定义，下列同样属于责任分散效应的是：","options":["值班员小王发现火情后立即报警并组织疏散","楼道灯坏了，全楼住户都觉得别人会报修，拖了半个月无人处理","小赵独自路过，毫不犹豫扶起摔倒的老人","救援队分工明确，各成员各司其职"],"answer":1,"explanation":"责任分散效应的要件是：群体情境、责任被分散到他人身上、个人努力或援助减少。「楼道灯坏了，全楼住户都觉得别人会报修，拖了半个月无人处理」完全符合上述要件；其余选项分别存在以下问题：责任明确到人，不存在责任分散；单人情境下没有可分散责任的对象；分工明确使责任落实到个人。故选B。"},{"id":"pd-20841","module":"panduan","diff":3,"exam":"省考","prompt":"班里发生了一件事：桌上的零食不见了。老师询问小王、小李、小张、小刘四人，四人的说法如下：小王说：“是小张拿走零食的。”；小李说：“是小张拿走零食的。”；小张说：“是小王拿走零食的。”；小刘说：“不是我拿走零食的。”。四人中只有1人说真话。由此可以推出，拿走零食的是：","options":["小张","小李","小刘","小王"],"answer":1,"explanation":"只有一人说真话。逐一假设验证：只有假设小李拿走零食时，四句话中为真的才恰好1句，符合题干条件，故小李拿走零食。故选B。"},{"id":"pd-20842","module":"panduan","diff":1,"exam":"事业编","prompt":"王某目睹邻居被歹徒持棍追打，冲上前将歹徒推倒并夺下凶器。正当防卫是指为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而对不法侵害人采取的制止不法侵害的行为。根据上述定义，下列同样属于正当防卫的是：","options":["周某误以为有人要偷自己的电动车，冲上去将路过的行人打成重伤","出租车司机张某在乘客突然持刀抢劫时，猛踩刹车并夺下刀具将对方制服","赵某与邻居发生口角，越想越气，当晚携带木棍上门将邻居打伤","孙某被李某追打，挣脱逃跑后，次日纠集多人将李某堵在巷内殴打"],"answer":1,"explanation":"正当防卫的要件是：起因是不法侵害且正在进行、针对不法侵害人本人、具有防卫意图。「出租车司机张某在乘客突然持刀抢劫时，猛踩刹车并夺下刀具将对方制服」完全符合上述要件；其余选项分别存在以下问题：不存在正在进行的不法侵害，属于事前加害；不法侵害已经结束，属于事后报复；针对的不是正在进行的不法侵害人。故选B。"},{"id":"pd-20843","module":"panduan","diff":2,"exam":"事业编","prompt":"横梁：房屋\n下列与题干词项逻辑关系最相近的是：","options":["坚硬：柔软","提高：降低","砖块：墙壁","欣赏：风景"],"answer":2,"explanation":"题干「横梁」与「房屋」为组成关系；「砖块」与「墙壁」也是组成关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20844","module":"panduan","diff":2,"exam":"教师编","prompt":"小王与新同事初次见面时热情周到，同事此后对他印象颇佳。近因效应是指最新出现的刺激物促使印象形成时起更强作用的现象，即最近的表现对他人总体印象的影响更大。根据上述定义，下列不属于近因效应的是：","options":["小钱近期待人热情周到，邻居们对他印象大为改观","老李最近几次会议发言精彩，大家纷纷认为他水平很高，淡忘了此前的平淡表现","小赵近期连续高质量完成项目，同事改变了他此前能力平平的印象","小张因好友极力推荐而对某人产生好感"],"answer":3,"explanation":"近因效应的要件是：最近的表现、对总体印象产生更大影响、改变原有看法。「小张因好友极力推荐而对某人产生好感」不符合要件：好感来自他人评价，与最近表现无关；其余选项均符合近因效应的全部要件。故选D。"},{"id":"pd-20845","module":"panduan","diff":1,"exam":"事业编","prompt":"重阳节：九月初九\n下列与题干词项逻辑关系最相近的是：","options":["悠久：历史","江：河","端午节：五月初五","贫穷：贫困"],"answer":2,"explanation":"题干「重阳节」与「九月初九」为节日与其时间的对应；「端午节」与「五月初五」也是节日与其时间的对应，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20846","module":"panduan","diff":3,"exam":"国考","prompt":"所有的水稻都是粮食作物，所有的棉花都不是粮食作物。由此可以推出：","options":["有的棉花是水稻","所有的棉花都是水稻","所有的棉花都不是水稻","有的水稻是棉花"],"answer":2,"explanation":"水稻都包含于粮食作物，而棉花与粮食作物完全排斥，所以棉花与水稻也完全排斥，即所有的棉花都不是水稻；其余选项与题干矛盾或不能必然推出。故选C。"},{"id":"pd-20847","module":"panduan","diff":2,"exam":"国考","prompt":"局势：稳定\n下列与题干词项逻辑关系最相近的是：","options":["蜜蜂：采蜜","琴弦：吉他","安静：宁静","意大利：罗马"],"answer":0,"explanation":"题干「局势」与「稳定」为主谓关系；「蜜蜂」与「采蜜」也是主谓关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20848","module":"panduan","diff":2,"exam":"国考","prompt":"树枝：树木\n下列与题干词项逻辑关系最相近的是：","options":["中秋节：八月十五","鳞片：鱼","印度：新德里","明朝：朱元璋"],"answer":1,"explanation":"题干「树枝」与「树木」为组成关系；「鳞片」与「鱼」也是组成关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20849","module":"panduan","diff":2,"exam":"教师编","prompt":"班里发生了一件事：图书角的一本书被弄破了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“是丙弄破图书的。”；乙说：“是丙弄破图书的。”；丙说：“不是我弄破图书的。”；丁说：“不是我弄破图书的。”。四人中只有3人说真话。由此可以推出，弄破图书的是：","options":["丙","甲","丁","乙"],"answer":0,"explanation":"只有三人说假话。逐一假设验证：只有假设丙弄破图书时，四句话中为假的才恰好3句，符合题干条件，故丙弄破图书。故选A。"},{"id":"pd-20850","module":"panduan","diff":2,"exam":"国考","prompt":"老字号企业的诚信经营观念代代相传，成为全体店员的自觉行为。企业文化是企业在长期经营中形成的、为全体成员共同遵循的价值观念和行为规范的总和。根据上述定义，下列同样属于企业文化的是：","options":["某科技公司的创新文化深入人心，员工主动提出改进建议蔚然成风","公司墙上的标语口号仅挂在墙上，无人践行","公司印制了精美的产品说明书","公司办公楼进行了豪华装修"],"answer":0,"explanation":"企业文化的要件是：长期经营中形成、全体成员共同遵循、价值观念与行为规范。「某科技公司的创新文化深入人心，员工主动提出改进建议蔚然成风」完全符合上述要件；其余选项分别存在以下问题：口号未被成员共同遵循，未内化为文化；办公环境属于物质层面，不是价值观念；产品说明书是企业产品，不是共同遵循的观念。故选A。"},{"id":"pd-20851","module":"panduan","diff":2,"exam":"国考","prompt":"快递员误将李某的包裹投递给同名的陈某，陈某拆开使用后拒不退还。不当得利是指没有合法根据，使他人受到损失而自己获得利益的事实。根据上述定义，下列同样属于不当得利的是：","options":["吴某因经营有方，商品供不应求，利润大增","银行柜员操作失误，多付给取款人王某一万元，王某发现后拒不归还","郑某购买彩票中奖，依法兑取奖金","周某捡到他人丢弃的废旧纸箱变卖，得款二十元"],"answer":1,"explanation":"不当得利的要件是：一方获利、他方受损、获利与受损有因果关系、获利无合法根据。「银行柜员操作失误，多付给取款人王某一万元，王某发现后拒不归还」完全符合上述要件；其余选项分别存在以下问题：所拾为他人抛弃物，取得无主物不使他人受损；经营获利有合法根据；中奖兑奖有合法根据。故选B。"},{"id":"pd-20852","module":"panduan","diff":1,"exam":"教师编","prompt":"央行降息后企业贷款意愿增强。挤出效应是指政府增加支出或发行公债融资时，引起利率上升，导致私人投资或消费减少的现象。根据上述定义，下列不属于挤出效应的是：","options":["财政大幅扩大支出后，银行贷款利率上行，居民住房贷款成本增加，购房意愿下降","政府减税使居民可支配收入增加","政府大规模发行国债筹集基建资金，市场利率上升，某民营企业因融资成本过高取消了扩建计划","政府举债投资大型项目，资金市场趋紧，中小企业贷款难度加大、投资缩减"],"answer":1,"explanation":"挤出效应的要件是：政府支出或发债融资、利率上升、私人投资或消费被挤减。「政府减税使居民可支配收入增加」不符合要件：减税增加居民收入，不属于挤出效应；其余选项均符合挤出效应的全部要件。故选B。"},{"id":"pd-20853","module":"panduan","diff":2,"exam":"教师编","prompt":"小张、小王、小李、小赵、小刘五人比较年龄。已知：小赵比小王大；小李比小张大；小张比小赵大；小刘比小赵大。这五人的年龄从大到小排序，谁排第四？","options":["小刘","小李","小赵","小张"],"answer":2,"explanation":"由题干条件逐步推理，可得五人年龄从大到小的完整排序为：小李＞小张＞小刘＞小赵＞小王。因此排第四的是小赵。故选C。"},{"id":"pd-20854","module":"panduan","diff":3,"exam":"国考","prompt":"小陈、小杨、小吴、小周、小孙五人比较跑步速度。已知：小吴比小孙快；小吴比小杨快；小杨比小陈快；小吴不是最快的。这五人的跑步速度从快到慢排序，谁排第一？","options":["小吴","小杨","小周","小陈"],"answer":2,"explanation":"由题干条件逐步推理，可得五人跑步速度从快到慢的完整排序为：小周＞小吴＞小杨＞小陈＞小孙。因此排第一的是小周。故选C。"},{"id":"pd-20855","module":"panduan","diff":3,"exam":"省考","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问小陈、小杨、小吴、小郑四人，四人的说法如下：小陈说：“是小郑拿走钥匙的。”；小杨说：“不是我拿走钥匙的。”；小吴说：“是小郑拿走钥匙的。”；小郑说：“是小吴拿走钥匙的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["小吴","小郑","小陈","小杨"],"answer":3,"explanation":"只有一人说真话。逐一假设验证可知，小杨的话为真，其余三人的话均为假。故选D。"},{"id":"pd-20856","module":"panduan","diff":3,"exam":"教师编","prompt":"某小作坊产量增加一倍，但因管理混乱单位成本不降反升。规模经济是指随着生产规模扩大，单位产品的平均成本下降的现象。根据上述定义，下列不属于规模经济的是：","options":["某汽车厂年产量从十万辆提高到五十万辆后，单辆车分摊的研发和管理成本大幅下降","连锁超市统一采购货物，采购量越大，单件商品的进货成本越低","某工厂扩大生产线后，单位产品分摊的固定费用明显减少","企业通过技术改造降低了单位能耗"],"answer":3,"explanation":"规模经济的要件是：生产规模扩大、单位产品平均成本下降。「企业通过技术改造降低了单位能耗」不符合要件：成本下降源于技术进步，不是规模扩大；其余选项均符合规模经济的全部要件。故选D。"},{"id":"pd-20857","module":"panduan","diff":1,"exam":"国考","prompt":"只有旅客按时到达，才航班准点起飞。现已确认航班准点起飞。由此可以推出：","options":["旅客按时到达","旅客没能按时到达","如果旅客按时到达，那么航班准点起飞","只有航班准点起飞，才旅客按时到达"],"answer":0,"explanation":"「只有旅客按时到达，才航班准点起飞」中，旅客按时到达是航班准点起飞的必要条件，肯定后件就要肯定前件。现已确认航班准点起飞，属于肯定后件，故旅客按时到达必然成立，即旅客按时到达；肯定前件不能推出后件，其余选项均不能必然推出。故选A。"},{"id":"pd-20858","module":"panduan","diff":3,"exam":"事业编","prompt":"班里发生了一件事：桌上的零食不见了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“不是我拿走零食的。”；李四说：“是王五拿走零食的。”；王五说：“是赵六拿走零食的。”；赵六说：“是王五拿走零食的。”。四人中只有3人说真话。由此可以推出，拿走零食的是：","options":["赵六","李四","张三","王五"],"answer":3,"explanation":"只有三人说假话。逐一假设验证：只有假设王五拿走零食时，四句话中为假的才恰好3句，符合题干条件，故王五拿走零食。故选D。"},{"id":"pd-20859","module":"panduan","diff":2,"exam":"医疗编","prompt":"小张、小王、小李、小赵四人来自的城市各不相同，分别是北京、上海、广州、深圳。已知：小王来自的城市是广州；小李来自的城市不是北京；小赵来自的城市不是深圳；小李来自的城市不是深圳。由此可以推出，小李来自的城市是：","options":["上海","广州","深圳","北京"],"answer":0,"explanation":"由题干条件逐一排查：小王来自广州；小李不来自北京；小赵不来自深圳；小李不来自深圳。结合四人城市各不相同，可唯一确定小李来自上海。故选A。"},{"id":"pd-20860","module":"panduan","diff":1,"exam":"国考","prompt":"班里发生了一件事：走廊里的盆栽被碰倒了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“是李四碰倒盆栽的。”；李四说：“不是我碰倒盆栽的。”；王五说：“不是我碰倒盆栽的。”；赵六说：“是张三碰倒盆栽的。”。四人中只有1人说真话。由此可以推出，碰倒盆栽的是：","options":["赵六","王五","张三","李四"],"answer":1,"explanation":"只有一人说真话。逐一假设验证：只有假设王五碰倒盆栽时，四句话中为真的才恰好1句，符合题干条件，故王五碰倒盆栽。故选B。"},{"id":"pd-20861","module":"panduan","diff":2,"exam":"省考","prompt":"科学家认为火星在远古时期曾经存在液态水。以下哪项如果为真，最能支持该观点？","options":["火星表面的昼夜温差很大","探测器在火星表面发现了只能在液态水环境下形成的沉积岩层","火星是太阳系中与地球较为相似的行星","人类已多次向火星发射探测器"],"answer":1,"explanation":"沉积岩层是液态水存在的直接地质证据，最能支持原观点。故选B。"},{"id":"pd-20862","module":"panduan","diff":2,"exam":"事业编","prompt":"章节：小说\n下列与题干词项逻辑关系最相近的是：","options":["凿壁偷光：匡衡","香蕉：水果","洗衣机：洗涤衣物","羽毛：鸟"],"answer":3,"explanation":"题干「章节」与「小说」为组成关系；「羽毛」与「鸟」也是组成关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20863","module":"panduan","diff":1,"exam":"国考","prompt":"窗户：房子\n下列与题干词项逻辑关系最相近的是：","options":["纽扣：衣服","加拿大：渥太华","顿时：立刻","提高：水平"],"answer":0,"explanation":"题干「窗户」与「房子」为组成关系；「纽扣」与「衣服」也是组成关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20864","module":"panduan","diff":2,"exam":"省考","prompt":"重复：反复\n下列与题干词项逻辑关系最相近的是：","options":["演员：剧院","灯塔：导航","灿烂：文化","暖和：温暖"],"answer":3,"explanation":"题干「重复」与「反复」为近义关系；「暖和」与「温暖」也是近义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20865","module":"panduan","diff":2,"exam":"国考","prompt":"篮球：球类运动\n下列与题干词项逻辑关系最相近的是：","options":["宽阔：狭窄","护士：注射器","澳大利亚：堪培拉","青蛙：两栖动物"],"answer":3,"explanation":"题干「篮球」与「球类运动」为种属包含关系；「青蛙」与「两栖动物」也是种属包含关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20866","module":"panduan","diff":3,"exam":"国考","prompt":"某慢性病患者与家庭医生团队签约，获得长期用药指导和定期随访。家庭医生签约服务是指居民与家庭医生团队签订服务协议，团队为其提供连续性、综合性的基本医疗卫生服务。根据上述定义，下列同样属于家庭医生签约服务的是：","options":["体检中心为某单位提供一次性集中体检","居民自行到药店购买常用药品","王大爷与社区家庭医生团队签约，医生定期上门随访并提供健康指导","患者深夜到急诊科就诊"],"answer":2,"explanation":"家庭医生签约服务的要件是：签订服务协议、家庭医生团队、提供连续性综合性基本医疗服务。「王大爷与社区家庭医生团队签约，医生定期上门随访并提供健康指导」完全符合上述要件；其余选项分别存在以下问题：购药未签订服务协议，也无团队服务；急诊服务不属于签约的连续性服务；一次性体检不具连续性，且无签约关系。故选C。"},{"id":"pd-20867","module":"panduan","diff":3,"exam":"国考","prompt":"患者乘火车到邻市医院当面就诊。远程医疗是指医疗机构通过通信技术为异地患者提供诊疗指导等医疗服务的方式。根据上述定义，下列不属于远程医疗的是：","options":["县医院通过视频连线请省城专家为患者远程会诊并调整治疗方案","医院电话通知患者复诊的具体时间","医生通过远程系统查看患者检查资料，给出诊断和用药指导","边远地区患者通过远程平台获得上级医院医生的诊疗意见"],"answer":1,"explanation":"远程医疗的要件是：医疗机构借助通信技术、为异地患者、提供诊疗服务。「医院电话通知患者复诊的具体时间」不符合要件：事务性通知不属于诊疗服务；其余选项均符合远程医疗的全部要件。故选B。"},{"id":"pd-20868","module":"panduan","diff":2,"exam":"省考","prompt":"班里发生了一件事：教室里的花瓶被打碎了。老师询问小赵、小钱、小孙、小周四人，四人的说法如下：小赵说：“不是我打碎花瓶的。”；小钱说：“不是我打碎花瓶的。”；小孙说：“是小赵打碎花瓶的。”；小周说：“是小赵打碎花瓶的。”。四人中只有3人说真话。由此可以推出，打碎花瓶的是：","options":["小孙","小赵","小钱","小周"],"answer":1,"explanation":"只有三人说假话。逐一假设验证：只有假设小赵打碎花瓶时，四句话中为假的才恰好3句，符合题干条件，故小赵打碎花瓶。故选B。"},{"id":"pd-20869","module":"panduan","diff":2,"exam":"事业编","prompt":"经理因小吴业绩突出，便认为他品行也一定过硬，委以重任。晕轮效应是指对人的某个特征形成印象后，掩盖了其他方面的特征，即以点概面、以偏概全的心理现象。根据上述定义，下列同样属于晕轮效应的是：","options":["小钱认为北方人都豪爽大方","老李因某人外表出众，便觉得他各方面都很优秀","大家因为多数人同意而改变了自己的意见","面试官因候选人第一印象好而打分偏高"],"answer":1,"explanation":"晕轮效应的要件是：由某一特征出发、推及并掩盖其他特征、以点概面。「老李因某人外表出众，便觉得他各方面都很优秀」完全符合上述要件；其余选项分别存在以下问题：第一印象影响评价属于首因效应；随大流改变意见属于从众；对群体的固定看法属于刻板印象。故选B。"},{"id":"pd-20871","module":"panduan","diff":3,"exam":"教师编","prompt":"聪明：睿智\n下列与题干词项逻辑关系最相近的是：","options":["木匠：刨子","增进：友谊","工程师：党员","顽固：固执"],"answer":3,"explanation":"题干「聪明」与「睿智」为近义关系；「顽固」与「固执」也是近义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20872","module":"panduan","diff":1,"exam":"省考","prompt":"只有压力得到缓解，才保持乐观心态。现已确认保持乐观心态。由此可以推出：","options":["如果压力得到缓解，那么保持乐观心态","压力得到缓解","只有保持乐观心态，才压力得到缓解","压力得不到缓解"],"answer":1,"explanation":"「只有压力得到缓解，才保持乐观心态」中，压力得到缓解是保持乐观心态的必要条件，肯定后件就要肯定前件。现已确认保持乐观心态，属于肯定后件，故压力得到缓解必然成立，即压力得到缓解；肯定前件不能推出后件，其余选项均不能必然推出。故选B。"},{"id":"pd-20873","module":"panduan","diff":2,"exam":"省考","prompt":"甲公司向乙公司发函：愿以每吨5000元购买钢材100吨，10日内答复有效。要约是希望与他人订立合同的意思表示，内容具体确定，并表明经受要约人承诺，要约人即受该意思表示约束。根据上述定义，下列同样属于要约的是：","options":["甲公司向乙公司询问：你们的水泥多少钱一吨","某公司发布广告称：本月商品一律八折，欢迎选购","钱某与朋友闲聊时说真想买辆车，未提任何具体条件","赵某向某家具店表示：愿以标价购买该款沙发一张，当场付款"],"answer":3,"explanation":"要约的要件是：内容具体确定、表明经承诺即受约束、向希望缔约的相对人发出。「赵某向某家具店表示：愿以标价购买该款沙发一张，当场付款」完全符合上述要件；其余选项分别存在以下问题：商业广告内容不具体，属于要约邀请；意思表示内容不具体确定；询价行为不含有订立合同的确定意思。故选D。"},{"id":"pd-20874","module":"panduan","diff":2,"exam":"国考","prompt":"有的职员是参加过进修的人，所有的参加过进修的人都是专业知识得到更新的人。由此可以推出：","options":["所有的职员都是专业知识得到更新的人","所有的专业知识得到更新的人都是职员","有的职员不是专业知识得到更新的人","有的职员是专业知识得到更新的人"],"answer":3,"explanation":"有的职员是参加过进修的人，而参加过进修的人都属于专业知识得到更新的人，所以这部分职员也属于专业知识得到更新的人，即有的职员是专业知识得到更新的人；不能扩大为全称结论，其余选项均不必然成立。故选D。"},{"id":"pd-20875","module":"panduan","diff":1,"exam":"国考","prompt":"观看：观赏\n下列与题干词项逻辑关系最相近的是：","options":["借入：归还","快乐：高兴","乘务员：列车","水稻：粮食作物"],"answer":1,"explanation":"题干「观看」与「观赏」为近义关系；「快乐」与「高兴」也是近义关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20876","module":"panduan","diff":2,"exam":"国考","prompt":"集中：分散\n下列与题干词项逻辑关系最相近的是：","options":["望梅止渴：曹操","大闸蟹：阳澄湖","笔：墨","冷漠：热情"],"answer":3,"explanation":"题干「集中」与「分散」为反义关系；「冷漠」与「热情」也是反义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20877","module":"panduan","diff":3,"exam":"省考","prompt":"只有不必要的失分减少，才考生答题规范。现已确认考生答题规范。由此可以推出：","options":["不必要的失分减少","只有考生答题规范，才不必要的失分减少","不必要的失分没有减少","如果不必要的失分减少，那么考生答题规范"],"answer":0,"explanation":"「只有不必要的失分减少，才考生答题规范」中，不必要的失分减少是考生答题规范的必要条件，肯定后件就要肯定前件。现已确认考生答题规范，属于肯定后件，故不必要的失分减少必然成立，即不必要的失分减少；肯定前件不能推出后件，其余选项均不能必然推出。故选A。"},{"id":"pd-20878","module":"panduan","diff":2,"exam":"事业编","prompt":"京剧：戏曲\n下列与题干词项逻辑关系最相近的是：","options":["玫瑰：花卉","体温计：测量体温","聪明：睿智","《雷雨》：曹禺"],"answer":0,"explanation":"题干「京剧」与「戏曲」为种属包含关系；「玫瑰」与「花卉」也是种属包含关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20879","module":"panduan","diff":2,"exam":"国考","prompt":"局部：整体\n下列与题干词项逻辑关系最相近的是：","options":["桥墩：桥梁","演员：剧院","崭新：陈旧","棒球：球类运动"],"answer":2,"explanation":"题干「局部」与「整体」为反义关系；「崭新」与「陈旧」也是反义关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20880","module":"panduan","diff":1,"exam":"国考","prompt":"小张、小王、小李、小赵、小刘五人比较跑步速度。已知：小张比小李快；小李比小王快；小赵比小张快；小李比小刘快。这五人的跑步速度从快到慢排序，谁排第二？","options":["小刘","小王","小张","小李"],"answer":2,"explanation":"由题干条件逐步推理，可得五人跑步速度从快到慢的完整排序为：小赵＞小张＞小李＞小王＞小刘。因此排第二的是小张。故选C。"},{"id":"pd-20881","module":"panduan","diff":3,"exam":"国考","prompt":"政府大规模发行国债筹集基建资金，市场利率上升，某民营企业因融资成本过高取消了扩建计划。挤出效应是指政府增加支出或发行公债融资时，引起利率上升，导致私人投资或消费减少的现象。根据上述定义，下列同样属于挤出效应的是：","options":["财政大幅扩大支出后，银行贷款利率上行，居民住房贷款成本增加，购房意愿下降","政府减税使居民可支配收入增加","央行降息后企业贷款意愿增强","企业因市场需求旺盛而扩大投资"],"answer":0,"explanation":"挤出效应的要件是：政府支出或发债融资、利率上升、私人投资或消费被挤减。「财政大幅扩大支出后，银行贷款利率上行，居民住房贷款成本增加，购房意愿下降」完全符合上述要件；其余选项分别存在以下问题：降息使投资增加，与挤出效应方向相反；减税增加居民收入，不属于挤出效应；投资扩大由市场需求驱动，与政府支出无关。故选A。"},{"id":"pd-20882","module":"panduan","diff":3,"exam":"国考","prompt":"小钱、小郑、小冯、小许、小何五人比较体重。已知：小何比小钱重；小郑比小许重；小钱比小冯重；小钱比小郑重；小许不是最重的。这五人的体重从重到轻排序，谁排第二？","options":["小何","小冯","小郑","小钱"],"answer":3,"explanation":"由题干条件逐步推理，可得五人体重从重到轻的完整排序为：小何＞小钱＞小郑＞小许＞小冯。因此排第二的是小钱。故选D。"},{"id":"pd-20883","module":"panduan","diff":3,"exam":"省考","prompt":"研究人员认为，深海鱼类的长寿与其体内一种特殊蛋白密切相关。以下哪项如果为真，最能支持这一观点？","options":["该蛋白的结构较为复杂","将该蛋白导入普通实验鼠后，实验鼠的平均寿命显著延长","深海鱼类的种类十分丰富","深海鱼类生活在高压低温环境中"],"answer":1,"explanation":"导入蛋白使寿命延长，直接证明了该蛋白与长寿的因果关系，最能支持原观点。故选B。"},{"id":"pd-20884","module":"panduan","diff":1,"exam":"医疗编","prompt":"企业按季度例会讨论经营计划。危机管理是指组织为应对可能发生或已经发生的危机，进行监测、预警、决策和处置，以减少损失、恢复秩序的过程。根据上述定义，下列不属于危机管理的是：","options":["某企业建立舆情监测机制，在负面事件发酵前及时回应并启动应急预案","台风来临前，社区提前排查隐患、储备物资并组织危险区域居民转移","公司产品被曝光质量问题后，管理层迅速成立专项小组召回产品、安抚客户","办公室统一采购办公用品"],"answer":3,"explanation":"危机管理的要件是：针对可能或已经发生的危机、监测预警、决策处置。「办公室统一采购办公用品」不符合要件：日常采购事务不涉及危机；其余选项均符合危机管理的全部要件。故选D。"},{"id":"pd-20885","module":"panduan","diff":1,"exam":"国考","prompt":"奖励：惩罚\n下列与题干词项逻辑关系最相近的是：","options":["诚实：虚伪","黄河：河流","茅台酒：贵州","洗衣机：洗涤衣物"],"answer":0,"explanation":"题干「奖励」与「惩罚」为反义关系；「诚实」与「虚伪」也是反义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20886","module":"panduan","diff":1,"exam":"医疗编","prompt":"甲、乙、丙、丁四人的养的宠物各不相同，分别是猫、狗、鸟、鱼。已知：乙的养的宠物是鱼；乙的养的宠物不是狗；丁的养的宠物不是狗；甲的养的宠物是狗；丙的养的宠物不是鸟。由此可以推出，丙的养的宠物是：","options":["鸟","鱼","猫","狗"],"answer":2,"explanation":"由题干条件逐一排除可得：甲的养的宠物是狗；乙的养的宠物是鱼；丙的养的宠物是猫；丁的养的宠物是鸟。因此丙的养的宠物是猫。故选C。"},{"id":"pd-20887","module":"panduan","diff":2,"exam":"事业编","prompt":"小钱、小郑、小冯、小许、小何五人比较年龄。已知：小何比小许大；小何比小冯大；小钱比小郑大；小冯比小钱大。这五人的年龄从大到小排序，谁排第一？","options":["小冯","小何","小郑","小许"],"answer":1,"explanation":"由题干条件逐步推理，可得五人年龄从大到小的完整排序为：小何＞小冯＞小钱＞小许＞小郑。因此排第一的是小何。故选B。"},{"id":"pd-20888","module":"panduan","diff":2,"exam":"国考","prompt":"老周家习惯了每周下馆子，虽然最近手头紧张，仍难以改回家做饭的习惯。棘轮效应是指人的消费习惯形成之后具有不可逆性，即消费水平易于向上调整，而难于向下调整。根据上述定义，下列同样属于棘轮效应的是：","options":["小陈收入增加后消费支出随之增加","小李量入为出，每月消费保持稳定","小吴节衣缩食攒钱买房","老张升职加薪后换了大房子，后来收入减少仍不愿降低生活标准，坚持维持原有消费水平"],"answer":3,"explanation":"棘轮效应的要件是：消费习惯已形成、向上调整容易、向下调整困难。「老张升职加薪后换了大房子，后来收入减少仍不愿降低生活标准，坚持维持原有消费水平」完全符合上述要件；其余选项分别存在以下问题：收入增加带动消费属于正常向上调整，未体现难以下降；主动压缩消费并成功执行，与难以下调相反；消费保持稳定，未体现向上易、向下难的特征。故选D。"},{"id":"pd-20889","module":"panduan","diff":2,"exam":"国考","prompt":"某平台认为，优化内容推荐算法能够提高用户的留存率。上述论证最可能基于的前提是：","options":["算法优化需要投入研发资源","平台的内容储备较为充足","用户习惯使用移动端访问","用户流失的主要原因在于推荐内容不够精准"],"answer":3,"explanation":"若用户流失另有主因，优化算法便难以提高留存率，该项是论证成立的必要前提。故选D。"},{"id":"pd-20890","module":"panduan","diff":2,"exam":"事业编","prompt":"班里发生了一件事：桌上的零食不见了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“不是我拿走零食的。”；李四说：“不是我拿走零食的。”；王五说：“是张三拿走零食的。”；赵六说：“是王五拿走零食的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["李四","张三","王五","赵六"],"answer":1,"explanation":"只有一人说真话。逐一假设验证可知，张三的话为真，其余三人的话均为假。故选B。"},{"id":"pd-20891","module":"panduan","diff":3,"exam":"国考","prompt":"并非（文件及时归档并且查找资料方便）。由此可以推出：","options":["文件及时归档或者查找资料方便","如果文件没有及时归档，那么查找资料方便","文件没有及时归档或者查找资料不便","文件没有及时归档并且查找资料不便"],"answer":2,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（文件及时归档并且查找资料方便），等值于“文件没有及时归档或者查找资料不便”；其余选项均不符合德摩根定律。故选C。"},{"id":"pd-20892","module":"panduan","diff":3,"exam":"事业编","prompt":"班里发生了一件事：刚拖过的地面被踩脏了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“是王五踩脏地面的。”；李四说：“不是我踩脏地面的。”；王五说：“不是我踩脏地面的。”；赵六说：“是张三踩脏地面的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["赵六","李四","张三","王五"],"answer":3,"explanation":"只有一人说真话。逐一假设验证可知，王五的话为真，其余三人的话均为假。故选D。"},{"id":"pd-20893","module":"panduan","diff":2,"exam":"国考","prompt":"严肃：随便\n下列与题干词项逻辑关系最相近的是：","options":["干燥：湿润","普洱茶：云南","埃及：开罗","改善：生活"],"answer":0,"explanation":"题干「严肃」与「随便」为反义关系；「干燥」与「湿润」也是反义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20894","module":"panduan","diff":1,"exam":"医疗编","prompt":"班里发生了一件事：桌上的零食不见了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“是王五拿走零食的。”；李四说：“不是我拿走零食的。”；王五说：“不是我拿走零食的。”；赵六说：“是王五拿走零食的。”。四人中只有3人说真话。由此可以推出，拿走零食的是：","options":["赵六","李四","王五","张三"],"answer":2,"explanation":"只有三人说假话。逐一假设验证：只有假设王五拿走零食时，四句话中为假的才恰好3句，符合题干条件，故王五拿走零食。故选C。"},{"id":"pd-20895","module":"panduan","diff":3,"exam":"国考","prompt":"照顾：照料\n下列与题干词项逻辑关系最相近的是：","options":["生存：死亡","隐蔽：隐藏","演员：导演","律诗：诗歌"],"answer":1,"explanation":"题干「照顾」与「照料」为近义关系；「隐蔽」与「隐藏」也是近义关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20896","module":"panduan","diff":3,"exam":"省考","prompt":"只有生产安全得到保障，才员工遵守操作规程。现已确认员工遵守操作规程。由此可以推出：","options":["生产安全没有保障","只有员工遵守操作规程，才生产安全得到保障","生产安全得到保障","如果生产安全得到保障，那么员工遵守操作规程"],"answer":2,"explanation":"「只有生产安全得到保障，才员工遵守操作规程」中，生产安全得到保障是员工遵守操作规程的必要条件，肯定后件就要肯定前件。现已确认员工遵守操作规程，属于肯定后件，故生产安全得到保障必然成立，即生产安全得到保障；肯定前件不能推出后件，其余选项均不能必然推出。故选C。"},{"id":"pd-20897","module":"panduan","diff":3,"exam":"国考","prompt":"承担：责任\n下列与题干词项逻辑关系最相近的是：","options":["卡车：机动车","开阔：视野","教师：党员","厨师：炒勺"],"answer":1,"explanation":"题干「承担」与「责任」为动宾关系；「开阔」与「视野」也是动宾关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20898","module":"panduan","diff":1,"exam":"事业编","prompt":"所有的相声都是曲艺，所有的曲艺都是民间艺术。由此可以推出：","options":["所有的相声都是民间艺术","有的相声不是民间艺术","有的民间艺术不是相声","所有的民间艺术都是相声"],"answer":0,"explanation":"三段论传递推理：相声都属于曲艺，曲艺都属于民间艺术，所以所有的相声都是民间艺术；其余选项不能必然推出。故选A。"},{"id":"pd-20899","module":"panduan","diff":1,"exam":"国考","prompt":"所有的小提琴都是弦乐器，所有的弦乐器都是乐器。由此可以推出：","options":["所有的小提琴都是乐器","有的小提琴不是乐器","有的乐器不是小提琴","所有的乐器都是小提琴"],"answer":0,"explanation":"三段论传递推理：小提琴都属于弦乐器，弦乐器都属于乐器，所以所有的小提琴都是乐器；其余选项不能必然推出。故选A。"},{"id":"pd-20900","module":"panduan","diff":2,"exam":"国考","prompt":"小陈、小杨、小吴、小周、小孙五人比较身高。已知：小杨比小陈高；小杨比小周高；小吴比小孙高；小杨比小吴高。这五人的身高从高到矮排序，谁排第一？","options":["小周","小陈","小孙","小杨"],"answer":3,"explanation":"由题干条件逐步推理，可得五人身高从高到矮的完整排序为：小杨＞小吴＞小孙＞小周＞小陈。因此排第一的是小杨。故选D。"},{"id":"pd-20901","module":"panduan","diff":2,"exam":"事业编","prompt":"司机使用定速巡航功能保持车速。无人驾驶是指车辆在没有人为操作干预的情况下，依靠传感器感知环境、自动规划路线并控制行驶的技术。根据上述定义，下列不属于无人驾驶的是：","options":["园区内无人配送车自动规划路线，将包裹送达指定楼栋","倒车影像辅助司机完成泊车","矿区无人驾驶矿车按系统调度自动完成装载与运输","某测试车辆依靠激光雷达和摄像头感知路况，自动变道、避让行人并按导航行驶，全程无驾驶员操作"],"answer":1,"explanation":"无人驾驶的要件是：无人为操作干预、传感器感知环境、自动规划并控制行驶。「倒车影像辅助司机完成泊车」不符合要件：泊车由司机完成，影像只是辅助；其余选项均符合无人驾驶的全部要件。故选B。"},{"id":"pd-20902","module":"panduan","diff":2,"exam":"省考","prompt":"如果密码设置复杂，那么账号更安全。现已确认账号不够安全。由此可以推出：","options":["如果密码设置简单，那么账号不够安全","密码设置简单","密码设置复杂","密码设置复杂，尽管账号不够安全"],"answer":1,"explanation":"充分条件命题否定后件就要否定前件。由账号不够安全，可以推出密码设置简单；其余选项均不能由题干必然推出。故选B。"},{"id":"pd-20903","module":"panduan","diff":2,"exam":"事业编","prompt":"宽阔：狭窄\n下列与题干词项逻辑关系最相近的是：","options":["木匠：刨子","泰国：曼谷","期望：希望","奖励：惩罚"],"answer":3,"explanation":"题干「宽阔」与「狭窄」为反义关系；「奖励」与「惩罚」也是反义关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20904","module":"panduan","diff":2,"exam":"省考","prompt":"郑某被判处管制，办案人员称对其适用了缓刑。缓刑是指人民法院对犯罪分子判处刑罚后，附一定条件暂不执行原判刑罚的制度，适用于被判处拘役或者三年以下有期徒刑，且犯罪情节较轻、有悔罪表现、没有再犯罪的危险等情形。根据上述定义，下列不属于缓刑的是：","options":["冯某被判处罚金，因经济困难获准暂缓缴纳","赵某被判处有期徒刑八个月，法院认为其情节较轻、有悔罪表现，宣告缓刑考验期一年","张某因犯罪情节较轻被判处有期徒刑一年，法院宣告两年考验期内暂不执行刑罚","李某被判拘役三个月，因其悔罪表现好且没有再犯罪的危险，法院决定对其宣告缓刑"],"answer":0,"explanation":"缓刑的要件是：被判处拘役或三年以下有期徒刑、情节较轻、有悔罪表现、暂不执行刑罚。「冯某被判处罚金，因经济困难获准暂缓缴纳」不符合要件：暂缓缴纳罚金不是缓刑制度；其余选项均符合缓刑的全部要件。故选A。"},{"id":"pd-20905","module":"panduan","diff":2,"exam":"事业编","prompt":"调查显示，吃早餐的学生成绩普遍更好，因此校方要求所有学生必须吃早餐，以提高学习成绩。以下哪项如果为真，最能削弱校方的做法？","options":["早餐的种类多种多样","成绩好的学生作息规律、学习习惯好，也更有可能按时吃早餐","有的学生不喜欢吃早餐","学校食堂的早餐价格较为便宜"],"answer":1,"explanation":"该项说明成绩好才是按时吃早餐的原因，属于因果倒置，说明强制吃早餐未必能提高成绩。故选B。"},{"id":"pd-20906","module":"panduan","diff":2,"exam":"医疗编","prompt":"边远地区患者通过远程平台获得上级医院医生的诊疗意见。远程医疗是指医疗机构通过通信技术为异地患者提供诊疗指导等医疗服务的方式。根据上述定义，下列同样属于远程医疗的是：","options":["药店向顾客销售非处方药品","患者乘火车到邻市医院当面就诊","医院电话通知患者复诊的具体时间","医生通过远程系统查看患者检查资料，给出诊断和用药指导"],"answer":3,"explanation":"远程医疗的要件是：医疗机构借助通信技术、为异地患者、提供诊疗服务。「医生通过远程系统查看患者检查资料，给出诊断和用药指导」完全符合上述要件；其余选项分别存在以下问题：当面就诊未借助通信技术远程实施；事务性通知不属于诊疗服务；药店售药不属于医疗机构诊疗行为。故选D。"},{"id":"pd-20907","module":"panduan","diff":3,"exam":"省考","prompt":"小赵与新同事初次见面时热情周到，同事此后对他印象颇佳。首因效应是指交往双方形成的第一次印象对今后交往关系的影响，即先入为主带来的效果。根据上述定义，下列同样属于首因效应的是：","options":["面试中小李衣着得体、谈吐从容，面试官虽未细看简历，已对其留下能干的好印象","共事多年后，同事对小王形成了全面深入的了解","小张因好友极力推荐而对某人产生好感","小陈最近一次表现出色，大家改变了对他的原有看法"],"answer":0,"explanation":"首因效应的要件是：第一次接触、第一印象、对后续交往产生持续影响。「面试中小李衣着得体、谈吐从容，面试官虽未细看简历，已对其留下能干的好印象」完全符合上述要件；其余选项分别存在以下问题：长期相处形成的认识不是第一印象；好感来自他人评价，不是初次接触的直接印象；最近表现改变印象属于近因效应。故选A。"},{"id":"pd-20908","module":"panduan","diff":1,"exam":"省考","prompt":"某公司发放年终奖后员工工作效率明显提升，管理层认为是年终奖提高了员工积极性。以下哪项如果为真，最能削弱该看法？","options":["该公司员工的平均年龄较为年轻","发放年终奖的同时，公司完成了组织架构改革，流程大幅优化","年终奖的金额因岗位不同而有差异","部分员工对年终奖数额表示满意"],"answer":1,"explanation":"组织架构改革才是效率提升的原因，属于另有他因，削弱了年终奖与效率提升的因果联系。故选B。"},{"id":"pd-20909","module":"panduan","diff":1,"exam":"事业编","prompt":"吴某因经营有方，商品供不应求，利润大增。不当得利是指没有合法根据，使他人受到损失而自己获得利益的事实。根据上述定义，下列不属于不当得利的是：","options":["银行柜员操作失误，多付给取款人王某一万元，王某发现后拒不归还","郑某购买彩票中奖，依法兑取奖金","快递员误将李某的包裹投递给同名的陈某，陈某拆开使用后拒不退还","商场系统故障，原价三千元的手机标价三百元，赵某明知标错仍趁机购买"],"answer":1,"explanation":"不当得利的要件是：一方获利、他方受损、获利与受损有因果关系、获利无合法根据。「郑某购买彩票中奖，依法兑取奖金」不符合要件：中奖兑奖有合法根据；其余选项均符合不当得利的全部要件。故选B。"},{"id":"pd-20910","module":"panduan","diff":1,"exam":"国考","prompt":"王大爷与社区家庭医生团队签约，医生定期上门随访并提供健康指导。家庭医生签约服务是指居民与家庭医生团队签订服务协议，团队为其提供连续性、综合性的基本医疗卫生服务。根据上述定义，下列同样属于家庭医生签约服务的是：","options":["居民自行到药店购买常用药品","李奶奶签约后，家庭医生团队为其建立健康档案并持续跟踪管理","患者深夜到急诊科就诊","体检中心为某单位提供一次性集中体检"],"answer":1,"explanation":"家庭医生签约服务的要件是：签订服务协议、家庭医生团队、提供连续性综合性基本医疗服务。「李奶奶签约后，家庭医生团队为其建立健康档案并持续跟踪管理」完全符合上述要件；其余选项分别存在以下问题：购药未签订服务协议，也无团队服务；急诊服务不属于签约的连续性服务；一次性体检不具连续性，且无签约关系。故选B。"},{"id":"pd-20911","module":"panduan","diff":2,"exam":"省考","prompt":"借入：归还\n下列与题干词项逻辑关系最相近的是：","options":["前进：后退","黄河：河流","观看：观赏","西汉：刘邦"],"answer":0,"explanation":"题干「借入」与「归还」为反义关系；「前进」与「后退」也是反义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20912","module":"panduan","diff":1,"exam":"国考","prompt":"完璧归赵：蔺相如\n下列与题干词项逻辑关系最相近的是：","options":["洗衣机：洗涤衣物","草木皆兵：苻坚","西瓜：水果","崎岖：平坦"],"answer":1,"explanation":"题干「完璧归赵」与「蔺相如」为成语典故与其主人公的对应；「草木皆兵」与「苻坚」也是成语典故与其主人公的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20913","module":"panduan","diff":1,"exam":"省考","prompt":"某厂家认为，采用新生产工艺能够显著降低产品的生产成本。上述论证最可能基于的前提是：","options":["工人能够较快掌握新工艺","新工艺的操作难度适中","新工艺不会在其他环节显著增加额外成本","新工艺符合环保要求"],"answer":2,"explanation":"若新工艺在其他环节大幅增加成本，总成本便不会降低，该项是论证成立的必要前提。故选C。"},{"id":"pd-20914","module":"panduan","diff":2,"exam":"国考","prompt":"如果提前出门，那么按时到校。现已确认没能按时到校。由此可以推出：","options":["没有提前出门","提前出门，尽管没能按时到校","提前出门","如果没有提前出门，那么没能按时到校"],"answer":0,"explanation":"充分条件命题否定后件就要否定前件。由没能按时到校，可以推出没有提前出门；其余选项均不能由题干必然推出。故选A。"},{"id":"pd-20915","module":"panduan","diff":1,"exam":"省考","prompt":"小陈、小杨、小吴、小周、小孙五人比较跑步速度。已知：小杨比小孙快；小吴比小周快；小吴比小陈快；小吴不是最快的。这五人的跑步速度从快到慢排序，谁排第一？","options":["小杨","小陈","小周","小吴"],"answer":0,"explanation":"由题干条件逐步推理，可得五人跑步速度从快到慢的完整排序为：小杨＞小吴＞小陈＞小周＞小孙。因此排第一的是小杨。故选A。"},{"id":"pd-20916","module":"panduan","diff":3,"exam":"医疗编","prompt":"统计表明，读书多的人收入普遍更高，因此有人认为读书能够使人致富。以下哪项如果为真，最能削弱该观点？","options":["图书的种类和价格差异很大","有的读书不多的人收入也很高","收入高的家庭更有条件让子女接受更长时间的教育，读书多是其结果","很多人喜欢利用碎片时间读书"],"answer":2,"explanation":"家庭收入高才是读书多的原因，属于因果倒置，说明读书未必是致富的原因。故选C。"},{"id":"pd-20917","module":"panduan","diff":3,"exam":"医疗编","prompt":"成功：失败\n下列与题干词项逻辑关系最相近的是：","options":["崎岖：平坦","冰箱：家电","笔：墨","履行：义务"],"answer":0,"explanation":"题干「成功」与「失败」为反义关系；「崎岖」与「平坦」也是反义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20918","module":"panduan","diff":2,"exam":"事业编","prompt":"甲、乙、丙、丁、戊五人比较考试成绩。已知：丁比乙好；甲比丙好；甲比戊好；甲比丁好；丙不是最好的。这五人的考试成绩从好到差排序，谁排第一？","options":["丁","乙","甲","丙"],"answer":2,"explanation":"由题干条件逐步推理，可得五人考试成绩从好到差的完整排序为：甲＞丁＞丙＞戊＞乙。因此排第一的是甲。故选C。"},{"id":"pd-20919","module":"panduan","diff":2,"exam":"省考","prompt":"所有的油画都是绘画，所有的绘画都是美术作品。由此可以推出：","options":["有的美术作品不是油画","所有的美术作品都是油画","所有的油画都是美术作品","有的油画不是美术作品"],"answer":2,"explanation":"三段论传递推理：油画都属于绘画，绘画都属于美术作品，所以所有的油画都是美术作品；其余选项不能必然推出。故选C。"},{"id":"pd-20920","module":"panduan","diff":3,"exam":"国考","prompt":"只有审计顺利进行，才账目清晰。现已确认账目清晰。由此可以推出：","options":["审计难以顺利进行","如果审计顺利进行，那么账目清晰","审计顺利进行","只有账目清晰，才审计顺利进行"],"answer":2,"explanation":"「只有审计顺利进行，才账目清晰」中，审计顺利进行是账目清晰的必要条件，肯定后件就要肯定前件。现已确认账目清晰，属于肯定后件，故审计顺利进行必然成立，即审计顺利进行；肯定前件不能推出后件，其余选项均不能必然推出。故选C。"},{"id":"pd-20921","module":"panduan","diff":2,"exam":"省考","prompt":"班里发生了一件事：走廊里的盆栽被碰倒了。老师询问小陈、小杨、小吴、小郑四人，四人的说法如下：小陈说：“不是我碰倒盆栽的。”；小杨说：“不是我碰倒盆栽的。”；小吴说：“是小杨碰倒盆栽的。”；小郑说：“是小杨碰倒盆栽的。”。四人中只有3人说真话。由此可以推出，碰倒盆栽的是：","options":["小杨","小吴","小郑","小陈"],"answer":0,"explanation":"只有三人说假话。逐一假设验证：只有假设小杨碰倒盆栽时，四句话中为假的才恰好3句，符合题干条件，故小杨碰倒盆栽。故选A。"},{"id":"pd-20922","module":"panduan","diff":2,"exam":"国考","prompt":"小吴通过问卷调查了解顾客的真实偏好。投射效应是指将自己具有的特质归因到他人身上的心理倾向，即以己度人。根据上述定义，下列不属于投射效应的是：","options":["小郑酷爱运动，便想当然地认为同事们都喜欢户外活动","小陈设身处地为他人着想，努力理解对方的真实感受","小周自己嗜辣，便以为所有客人都爱吃辣，点菜全点辣菜","老王生性多疑，总认为别人也在背后算计他"],"answer":1,"explanation":"投射效应的要件是：以自己的特质、推测他人也具有同样的特质。「小陈设身处地为他人着想，努力理解对方的真实感受」不符合要件：共情是理解他人感受，不是把自己的特质加于他人；其余选项均符合投射效应的全部要件。故选B。"},{"id":"pd-20923","module":"panduan","diff":2,"exam":"事业编","prompt":"昆虫：节肢动物\n下列与题干词项逻辑关系最相近的是：","options":["日本：东京","理发师：剪刀","黄河：河流","灯泡：台灯"],"answer":2,"explanation":"题干「昆虫」与「节肢动物」为种属包含关系；「黄河」与「河流」也是种属包含关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20924","module":"panduan","diff":1,"exam":"国考","prompt":"班里发生了一件事：走廊里的盆栽被碰倒了。老师询问小赵、小钱、小孙、小周四人，四人的说法如下：小赵说：“是小钱碰倒盆栽的。”；小钱说：“不是我碰倒盆栽的。”；小孙说：“是小钱碰倒盆栽的。”；小周说：“不是我碰倒盆栽的。”。四人中只有1人说真话。由此可以推出，碰倒盆栽的是：","options":["小孙","小周","小钱","小赵"],"answer":1,"explanation":"只有一人说真话。逐一假设验证：只有假设小周碰倒盆栽时，四句话中为真的才恰好1句，符合题干条件，故小周碰倒盆栽。故选B。"},{"id":"pd-20925","module":"panduan","diff":1,"exam":"国考","prompt":"居民自行到药店购买常用药品。家庭医生签约服务是指居民与家庭医生团队签订服务协议，团队为其提供连续性、综合性的基本医疗卫生服务。根据上述定义，下列不属于家庭医生签约服务的是：","options":["王大爷与社区家庭医生团队签约，医生定期上门随访并提供健康指导","李奶奶签约后，家庭医生团队为其建立健康档案并持续跟踪管理","某慢性病患者与家庭医生团队签约，获得长期用药指导和定期随访","患者深夜到急诊科就诊"],"answer":3,"explanation":"家庭医生签约服务的要件是：签订服务协议、家庭医生团队、提供连续性综合性基本医疗服务。「患者深夜到急诊科就诊」不符合要件：急诊服务不属于签约的连续性服务；其余选项均符合家庭医生签约服务的全部要件。故选D。"},{"id":"pd-20926","module":"panduan","diff":3,"exam":"教师编","prompt":"吴某因犯罪情节恶劣被判处有期徒刑十年，仍被宣布暂不执行刑罚。缓刑是指人民法院对犯罪分子判处刑罚后，附一定条件暂不执行原判刑罚的制度，适用于被判处拘役或者三年以下有期徒刑，且犯罪情节较轻、有悔罪表现、没有再犯罪的危险等情形。根据上述定义，下列不属于缓刑的是：","options":["赵某被判处有期徒刑八个月，法院认为其情节较轻、有悔罪表现，宣告缓刑考验期一年","张某因犯罪情节较轻被判处有期徒刑一年，法院宣告两年考验期内暂不执行刑罚","郑某被判处管制，办案人员称对其适用了缓刑","李某被判拘役三个月，因其悔罪表现好且没有再犯罪的危险，法院决定对其宣告缓刑"],"answer":2,"explanation":"缓刑的要件是：被判处拘役或三年以下有期徒刑、情节较轻、有悔罪表现、暂不执行刑罚。「郑某被判处管制，办案人员称对其适用了缓刑」不符合要件：管制不属于缓刑的适用对象；其余选项均符合缓刑的全部要件。故选C。"},{"id":"pd-20927","module":"panduan","diff":2,"exam":"国考","prompt":"甲、乙、丙、丁、戊五人比较考试成绩。已知：丁比戊好；丁比甲好；丙比乙好；戊比丙好；乙不是最好的。这五人的考试成绩从好到差排序，谁排第一？","options":["丁","乙","丙","甲"],"answer":0,"explanation":"由题干条件逐步推理，可得五人考试成绩从好到差的完整排序为：丁＞戊＞丙＞甲＞乙。因此排第一的是丁。故选A。"},{"id":"pd-20928","module":"panduan","diff":1,"exam":"省考","prompt":"梅：兰\n下列与题干词项逻辑关系最相近的是：","options":["德国：柏林","辽阔：草原","传播：文化","琴：棋"],"answer":3,"explanation":"题干「梅」与「兰」为并列关系；「琴」与「棋」也是并列关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20929","module":"panduan","diff":2,"exam":"国考","prompt":"理发师：剪刀\n下列与题干词项逻辑关系最相近的是：","options":["暖和：温暖","教师：粉笔","飞行员：驾驶舱","从容：镇定"],"answer":1,"explanation":"题干「理发师」与「剪刀」为职业与其专用工具的对应；「教师」与「粉笔」也是职业与其专用工具的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20930","module":"panduan","diff":2,"exam":"省考","prompt":"周末小张选择加班获得加班费，放弃了外出旅游的愉快体验。机会成本是指为了得到某种东西而所要放弃的其他选择中价值最高的那一个。根据上述定义，下列同样属于机会成本的是：","options":["小赵开店实际支出的房租、水电和进货费用","小李用一笔钱读研，放弃了年薪十万元的工作机会，这十万元是他读研的机会成本","公司购买设备实际支付的价款","小李贷款买车每月偿还的本息"],"answer":1,"explanation":"机会成本的要件是：面临多种选择、放弃其他选择、以其中价值最高者计。「小李用一笔钱读研，放弃了年薪十万元的工作机会，这十万元是他读研的机会成本」完全符合上述要件；其余选项分别存在以下问题：实际支出属于会计成本，不是放弃的选择；购买设备的支出是实际花费，不是机会成本；偿还本息是实际支出，不是被放弃的最优选择。故选B。"},{"id":"pd-20931","module":"panduan","diff":2,"exam":"国考","prompt":"某餐饮公司向市场监管部门申请食品经营许可证，经审查合格后获颁证照。行政许可是指行政机关根据公民、法人或者其他组织的申请，经依法审查，准予其从事特定活动的行为。根据上述定义，下列同样属于行政许可的是：","options":["民政部门向低收入家庭发放最低生活保障金","税务机关依法向某企业征收上一年度的税款","赵某向公安机关申请普通护照，经审核符合条件后获发","市场监管部门对销售假冒商品的商店作出罚款决定"],"answer":2,"explanation":"行政许可的要件是：依申请、行政机关依法审查、准予从事特定活动。「赵某向公安机关申请普通护照，经审核符合条件后获发」完全符合上述要件；其余选项分别存在以下问题：征税属于行政征收，不是准予从事特定活动；罚款属于行政处罚；发放低保属于行政给付。故选C。"},{"id":"pd-20933","module":"panduan","diff":2,"exam":"国考","prompt":"小赵先请同事帮忙带一杯咖啡，同事答应后，再请他代为加班整理资料，同事也同意了。登门槛效应是指一个人一旦接受了他人的一个微小要求后，为避免认知失调或给人前后一致的印象，更可能接受更大要求的现象。根据上述定义，下列同样属于登门槛效应的是：","options":["老师一次性布置了全部假期作业","募捐者先请路人签名支持环保，路人签名后，再请其捐出少量善款，路人大多同意","经理直接要求员工完成高难度任务","小钱断然拒绝了同事的大额借款请求"],"answer":1,"explanation":"登门槛效应的要件是：先提出微小要求被接受、再提出更大要求、更大要求更易被接受。「募捐者先请路人签名支持环保，路人签名后，再请其捐出少量善款，路人大多同意」完全符合上述要件；其余选项分别存在以下问题：没有先提出微小要求作为铺垫；拒绝了请求，未体现由小到大的递进；一次性提出要求，不存在渐进过程。故选B。"},{"id":"pd-20934","module":"panduan","diff":2,"exam":"国考","prompt":"只有小明身体好，才小明坚持锻炼。现已确认小明坚持锻炼。由此可以推出：","options":["只有小明坚持锻炼，才小明身体好","如果小明身体好，那么小明坚持锻炼","小明身体好","小明身体不好"],"answer":2,"explanation":"「只有小明身体好，才小明坚持锻炼」中，小明身体好是小明坚持锻炼的必要条件，肯定后件就要肯定前件。现已确认小明坚持锻炼，属于肯定后件，故小明身体好必然成立，即小明身体好；肯定前件不能推出后件，其余选项均不能必然推出。故选C。"},{"id":"pd-20935","module":"panduan","diff":3,"exam":"国考","prompt":"某保健品厂商宣称其产品能增强免疫力，理由是长期服用者的感冒次数明显减少。以下哪项如果为真，最能削弱该宣称？","options":["服用该保健品的人普遍更注重锻炼身体和规律作息","该保健品的口感得到不少消费者认可","该保健品的价格高于同类产品","感冒的诱因有很多种"],"answer":0,"explanation":"锻炼和作息才是感冒减少的原因，属于另有他因，削弱了保健品与免疫力的因果联系。故选A。"},{"id":"pd-20936","module":"panduan","diff":1,"exam":"事业编","prompt":"糊涂：明白\n下列与题干词项逻辑关系最相近的是：","options":["劳动节：五月一日","缓慢：迅速","阳光：明媚","《家》：巴金"],"answer":1,"explanation":"题干「糊涂」与「明白」为反义关系；「缓慢」与「迅速」也是反义关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20937","module":"panduan","diff":2,"exam":"事业编","prompt":"只有查找资料方便，才文件及时归档。现已确认文件及时归档。由此可以推出：","options":["如果查找资料方便，那么文件及时归档","查找资料不便","查找资料方便","只有文件及时归档，才查找资料方便"],"answer":2,"explanation":"「只有查找资料方便，才文件及时归档」中，查找资料方便是文件及时归档的必要条件，肯定后件就要肯定前件。现已确认文件及时归档，属于肯定后件，故查找资料方便必然成立，即查找资料方便；肯定前件不能推出后件，其余选项均不能必然推出。故选C。"},{"id":"pd-20938","module":"panduan","diff":1,"exam":"国考","prompt":"西瓜：水果\n下列与题干词项逻辑关系最相近的是：","options":["国庆节：十月一日","电视机：家电","诚实：虚伪","教师：党员"],"answer":1,"explanation":"题干「西瓜」与「水果」为种属包含关系；「电视机」与「家电」也是种属包含关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20939","module":"panduan","diff":1,"exam":"国考","prompt":"部门经理把某项目的日常决策权交给组长，并提供经费支持，由组长自主安排。授权是指管理者将职权委授给下属，并为其提供必要的条件，使下属能在职权范围内自主处理事务的过程。根据上述定义，下列同样属于授权的是：","options":["校长将社团活动审批权授予德育主任，由其按既定标准自行审批","公司实行总经理一人拍板制，大小事项均由其决定","领导临时出差，委托同事代为收发文件","经理把琐碎事务交给助理，但所有决定仍须逐级请示"],"answer":0,"explanation":"授权的要件是：授予职权、提供必要条件、下属可自主处理事务。「校长将社团活动审批权授予德育主任，由其按既定标准自行审批」完全符合上述要件；其余选项分别存在以下问题：下属无自主决定权，属于事务分派而非授权；权力集中于一人，与授权相反；委托代理事务未授予职权。故选A。"},{"id":"pd-20940","module":"panduan","diff":2,"exam":"国考","prompt":"并非（今年风调雨顺并且庄稼丰收）。由此可以推出：","options":["今年没有风调雨顺并且庄稼歉收","今年没有风调雨顺或者庄稼歉收","今年风调雨顺或者庄稼丰收","如果今年没有风调雨顺，那么庄稼丰收"],"answer":1,"explanation":"联言命题的负命题等值于相应的选言命题（德摩根定律）：并非（今年风调雨顺并且庄稼丰收），等值于“今年没有风调雨顺或者庄稼歉收”；其余选项均不符合德摩根定律。故选B。"},{"id":"pd-20941","module":"panduan","diff":2,"exam":"事业编","prompt":"含糊：模糊\n下列与题干词项逻辑关系最相近的是：","options":["顽固：固执","服从：反抗","摄影师：相机","严肃：随便"],"answer":0,"explanation":"题干「含糊」与「模糊」为近义关系；「顽固」与「固执」也是近义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20942","module":"panduan","diff":2,"exam":"医疗编","prompt":"车轮：自行车\n下列与题干词项逻辑关系最相近的是：","options":["袖子：衣服","珍贵：宝贵","疲惫：困倦","京剧：戏曲"],"answer":0,"explanation":"题干「车轮」与「自行车」为组成关系；「袖子」与「衣服」也是组成关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20943","module":"panduan","diff":2,"exam":"国考","prompt":"校长课间到教室和操场走动，及时了解师生的困难并现场解决。走动管理是指管理者走出办公室，深入现场、直接与员工和顾客接触，及时了解和解决问题的管理方式。根据上述定义，下列同样属于走动管理的是：","options":["主管在办公室审阅财务报表","总经理每周到车间与一线员工交流，现场协调解决设备问题","公司召开季度总结大会","经理通过邮件向各部门布置任务"],"answer":1,"explanation":"走动管理的要件是：走出办公室、深入现场、直接接触员工和顾客、及时解决问题。「总经理每周到车间与一线员工交流，现场协调解决设备问题」完全符合上述要件；其余选项分别存在以下问题：远程布置任务，未深入现场；会议形式不属于走动管理；案头工作未与员工顾客直接接触。故选B。"},{"id":"pd-20944","module":"panduan","diff":2,"exam":"省考","prompt":"班里发生了一件事：刚拖过的地面被踩脏了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“是丁踩脏地面的。”；乙说：“不是我踩脏地面的。”；丙说：“是丁踩脏地面的。”；丁说：“不是我踩脏地面的。”。四人中只有3人说真话。由此可以推出，踩脏地面的是：","options":["丁","乙","丙","甲"],"answer":0,"explanation":"只有三人说假话。逐一假设验证：只有假设丁踩脏地面时，四句话中为假的才恰好3句，符合题干条件，故丁踩脏地面。故选A。"},{"id":"pd-20945","module":"panduan","diff":3,"exam":"国考","prompt":"某国物价指数持续上涨。基尼系数是衡量收入分配公平程度的指标，数值介于零和一之间，数值越大表示收入差距越大。根据上述定义，下列不属于基尼系数的是：","options":["某国收入高度集中于少数人手中，基尼系数接近零点六","某地区通过测算发现居民收入差距缩小，基尼系数下降","某国收入分配差距扩大，高收入群体与低收入群体差距拉大，基尼系数上升","某家庭收入明显增加"],"answer":3,"explanation":"基尼系数的要件是：衡量收入分配差距、数值越大差距越大。「某家庭收入明显增加」不符合要件：个体收入变化不能反映整体收入差距；其余选项均符合基尼系数的全部要件。故选D。"},{"id":"pd-20946","module":"panduan","diff":2,"exam":"国考","prompt":"班里发生了一件事：刚拖过的地面被踩脏了。老师询问小王、小李、小张、小刘四人，四人的说法如下：小王说：“不是我踩脏地面的。”；小李说：“不是我踩脏地面的。”；小张说：“是小王踩脏地面的。”；小刘说：“是小王踩脏地面的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["小刘","小张","小李","小王"],"answer":3,"explanation":"只有一人说真话。逐一假设验证可知，小王的话为真，其余三人的话均为假。故选D。"},{"id":"pd-20947","module":"panduan","diff":1,"exam":"国考","prompt":"顽固：固执\n下列与题干词项逻辑关系最相近的是：","options":["江苏：南京","图书管理员：图书馆","勇敢：英勇","心情：舒畅"],"answer":2,"explanation":"题干「顽固」与「固执」为近义关系；「勇敢」与「英勇」也是近义关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20948","module":"panduan","diff":1,"exam":"国考","prompt":"班里发生了一件事：教室里的花瓶被打碎了。老师询问小赵、小钱、小孙、小周四人，四人的说法如下：小赵说：“是小周打碎花瓶的。”；小钱说：“不是我打碎花瓶的。”；小孙说：“是小赵打碎花瓶的。”；小周说：“不是我打碎花瓶的。”。四人中只有1人说真话。由此可以推出，打碎花瓶的是：","options":["小孙","小赵","小周","小钱"],"answer":3,"explanation":"只有一人说真话。逐一假设验证：只有假设小钱打碎花瓶时，四句话中为真的才恰好1句，符合题干条件，故小钱打碎花瓶。故选D。"},{"id":"pd-20949","module":"panduan","diff":1,"exam":"医疗编","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问张三、李四、王五、赵六四人，四人的说法如下：张三说：“是赵六拿走钥匙的。”；李四说：“不是我拿走钥匙的。”；王五说：“不是我拿走钥匙的。”；赵六说：“是王五拿走钥匙的。”。四人中只有3人说真话。由此可以推出，拿走钥匙的是：","options":["张三","王五","李四","赵六"],"answer":3,"explanation":"只有三人说假话。逐一假设验证：只有假设赵六拿走钥匙时，四句话中为假的才恰好3句，符合题干条件，故赵六拿走钥匙。故选D。"},{"id":"pd-20950","module":"panduan","diff":2,"exam":"国考","prompt":"手电筒：照明\n下列与题干词项逻辑关系最相近的是：","options":["河南：郑州","空调：制冷","拉面：兰州","攻克：难关"],"answer":1,"explanation":"题干「手电筒」与「照明」为事物与其功能的对应；「空调」与「制冷」也是事物与其功能的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20951","module":"panduan","diff":3,"exam":"事业编","prompt":"小钱、小郑、小冯、小许、小何五人比较考试成绩。已知：小冯比小何好；小何比小许好；小何比小钱好；小冯比小郑好；小许不是最好的。这五人的考试成绩从好到差排序，谁排第一？","options":["小郑","小冯","小许","小钱"],"answer":1,"explanation":"由题干条件逐步推理，可得五人考试成绩从好到差的完整排序为：小冯＞小何＞小钱＞小郑＞小许。因此排第一的是小冯。故选B。"},{"id":"pd-20952","module":"panduan","diff":3,"exam":"国考","prompt":"某银行采用量子加密专线传输核心数据，一旦有人窃听，通信双方立即察觉。量子通信是利用量子纠缠等量子力学原理进行信息传递或密钥分发的通信方式，具有窃听可被感知等特性。根据上述定义，下列同样属于量子通信的是：","options":["运营商升级基站提升移动网络速度","公司使用光纤专线传输数据","卫星转发电视信号覆盖城乡","两地实验室通过量子纠缠完成密钥分发，任何窃听行为都会留下痕迹"],"answer":3,"explanation":"量子通信的要件是：利用量子力学原理、传递信息或分发密钥、窃听可被感知。「两地实验室通过量子纠缠完成密钥分发，任何窃听行为都会留下痕迹」完全符合上述要件；其余选项分别存在以下问题：基站升级属于传统移动通信；光纤传输未利用量子力学原理；卫星转发属于传统通信方式。故选D。"},{"id":"pd-20954","module":"panduan","diff":1,"exam":"事业编","prompt":"小张、小王、小李、小赵四人来自的城市各不相同，分别是北京、上海、广州、深圳。已知：小张来自的城市不是深圳；小赵来自的城市不是上海；小张来自的城市不是北京；小王来自北京；小张来自的城市不是上海。由此可以推出，小赵来自：","options":["北京","广州","深圳","上海"],"answer":2,"explanation":"由题干条件逐一排除可得：小张来自广州；小王来自北京；小李来自上海；小赵来自深圳。因此小赵来自深圳。故选C。"},{"id":"pd-20955","module":"panduan","diff":2,"exam":"事业编","prompt":"司机：方向盘\n下列与题干词项逻辑关系最相近的是：","options":["干燥：湿润","教师：粉笔","小提琴：弦乐器","增加：减少"],"answer":1,"explanation":"题干「司机」与「方向盘」为职业与其专用工具的对应；「教师」与「粉笔」也是职业与其专用工具的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20956","module":"panduan","diff":1,"exam":"事业编","prompt":"某市在主干道安装大量摄像头后，交通事故发生率下降了百分之三十，交管部门认为是摄像头使司机减速行驶所致。以下哪项如果为真，最能削弱上述结论？","options":["同期该市开展了为期半年的交通安全宣传月活动，且机动车总量明显减少","该市交通事故的认定标准没有发生变化","该市安装的摄像头清晰度很高，能拍到车牌","周边城市也陆续安装了交通摄像头"],"answer":0,"explanation":"该项指出事故下降另有宣传教育和车辆减少等原因，属于另有他因，削弱了摄像头与事故下降的因果联系。故选A。"},{"id":"pd-20957","module":"panduan","diff":3,"exam":"医疗编","prompt":"班里发生了一件事：班级的钥匙不见了。老师询问小赵、小钱、小孙、小周四人，四人的说法如下：小赵说：“不是我拿走钥匙的。”；小钱说：“是小孙拿走钥匙的。”；小孙说：“不是我拿走钥匙的。”；小周说：“是小钱拿走钥匙的。”。四人中只有3人说真话。由此可以推出，拿走钥匙的是：","options":["小孙","小周","小赵","小钱"],"answer":3,"explanation":"只有三人说假话。逐一假设验证：只有假设小钱拿走钥匙时，四句话中为假的才恰好3句，符合题干条件，故小钱拿走钥匙。故选D。"},{"id":"pd-20958","module":"panduan","diff":2,"exam":"国考","prompt":"面试官因候选人第一印象好而打分偏高。晕轮效应是指对人的某个特征形成印象后，掩盖了其他方面的特征，即以点概面、以偏概全的心理现象。根据上述定义，下列不属于晕轮效应的是：","options":["经理因小吴业绩突出，便认为他品行也一定过硬，委以重任","大家因为多数人同意而改变了自己的意见","老李因某人外表出众，便觉得他各方面都很优秀","小赵见对方谈吐文雅，便认定其必然诚实可靠、能力出众"],"answer":1,"explanation":"晕轮效应的要件是：由某一特征出发、推及并掩盖其他特征、以点概面。「大家因为多数人同意而改变了自己的意见」不符合要件：随大流改变意见属于从众；其余选项均符合晕轮效应的全部要件。故选B。"},{"id":"pd-20959","module":"panduan","diff":2,"exam":"国考","prompt":"班里发生了一件事：教室里的花瓶被打碎了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“是丙打碎花瓶的。”；乙说：“是丙打碎花瓶的。”；丙说：“不是我打碎花瓶的。”；丁说：“不是我打碎花瓶的。”。四人中只有3人说真话。由此可以推出，打碎花瓶的是：","options":["丙","甲","丁","乙"],"answer":0,"explanation":"只有三人说假话。逐一假设验证：只有假设丙打碎花瓶时，四句话中为假的才恰好3句，符合题干条件，故丙打碎花瓶。故选A。"},{"id":"pd-20960","module":"panduan","diff":2,"exam":"国考","prompt":"《边城》：沈从文\n下列与题干词项逻辑关系最相近的是：","options":["羽毛：鸟","《家》：巴金","美国：华盛顿","东汉：刘秀"],"answer":1,"explanation":"题干「《边城》」与「沈从文」为作品与其作者的对应；「《家》」与「巴金」也是作品与其作者的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20961","module":"panduan","diff":2,"exam":"事业编","prompt":"电视机：家电\n下列与题干词项逻辑关系最相近的是：","options":["翅膀：鸟","精确：粗略","完整：残缺","棒球：球类运动"],"answer":3,"explanation":"题干「电视机」与「家电」为种属包含关系；「棒球」与「球类运动」也是种属包含关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20962","module":"panduan","diff":2,"exam":"事业编","prompt":"农民：田间\n下列与题干词项逻辑关系最相近的是：","options":["春：秋","乘务员：列车","美丽：漂亮","提高：降低"],"answer":1,"explanation":"题干「农民」与「田间」为职业与其工作场所的对应；「乘务员」与「列车」也是职业与其工作场所的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20963","module":"panduan","diff":3,"exam":"国考","prompt":"如果老王坚持早睡，那么老王精神饱满；如果老王精神饱满，那么老王工作状态良好。由此可以推出：","options":["如果老王工作状态良好，那么老王坚持早睡","如果老王坚持早睡，那么老王工作状态良好","如果老王精神饱满，那么老王坚持早睡","如果老王不坚持早睡，那么老王工作状态不佳"],"answer":1,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果老王坚持早睡，那么老王工作状态良好；其余选项均属无效推理。故选B。"},{"id":"pd-20964","module":"panduan","diff":3,"exam":"国考","prompt":"繁荣：昌盛\n下列与题干词项逻辑关系最相近的是：","options":["理发师：剪刀","梅：兰","安静：宁静","松树：树木"],"answer":2,"explanation":"题干「繁荣」与「昌盛」为近义关系；「安静」与「宁静」也是近义关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20965","module":"panduan","diff":1,"exam":"事业编","prompt":"大闸蟹：阳澄湖\n下列与题干词项逻辑关系最相近的是：","options":["木匠：刨子","茅台酒：贵州","京剧：戏曲","勤劳：懒惰"],"answer":1,"explanation":"题干「大闸蟹」与「阳澄湖」为产品与其产地的对应；「茅台酒」与「贵州」也是产品与其产地的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20966","module":"panduan","diff":3,"exam":"省考","prompt":"某创业公司按使用量租用云服务器存放数据并运行网站，无需自购机房设备。云计算是指通过网络以按需、易扩展的方式获取计算资源（服务器、存储、软件等）的服务模式，用户无需自建基础设施。根据上述定义，下列同样属于云计算的是：","options":["学校通过云平台为师生提供在线存储和课件服务，随需求扩容","小李将文件拷贝到自己的移动硬盘保存","单位在内网搭建共享文件夹供同事下载","公司自建机房并配备专职运维团队"],"answer":0,"explanation":"云计算的要件是：通过网络按需获取计算资源、无需自建基础设施、易扩展。「学校通过云平台为师生提供在线存储和课件服务，随需求扩容」完全符合上述要件；其余选项分别存在以下问题：自建基础设施与云计算模式相反；本地存储未通过网络按需获取资源；局域网共享不属于按需获取云端计算资源。故选A。"},{"id":"pd-20967","module":"panduan","diff":1,"exam":"事业编","prompt":"楼道卫生由热心住户轮流打扫，个别住户从不参与却同样享受整洁环境。搭便车是指不承担任何成本而坐享他人行为所带来的利益的行为。根据上述定义，下列同样属于搭便车的是：","options":["物业公司按合同提供保洁服务并收取物业费","小区几户居民自筹资金安装楼道照明灯，未出资的住户同样享受照明便利","小赵购买了演唱会门票入场观看","会员付费观看网络剧"],"answer":1,"explanation":"搭便车的要件是：不承担成本、坐享他人行为带来的利益。「小区几户居民自筹资金安装楼道照明灯，未出资的住户同样享受照明便利」完全符合上述要件；其余选项分别存在以下问题：购票观看支付了成本；服务有合同对价，权利义务对等；付费享受服务，未坐享他人成果。故选B。"},{"id":"pd-20968","module":"panduan","diff":2,"exam":"国考","prompt":"甲、乙、丙、丁、戊五人比较跑步速度。已知：戊比乙快；丁比丙快；戊比丁快；丁比甲快；乙不是最快的。这五人的跑步速度从快到慢排序，谁排第一？","options":["丙","丁","戊","乙"],"answer":2,"explanation":"由题干条件逐步推理，可得五人跑步速度从快到慢的完整排序为：戊＞丁＞乙＞甲＞丙。因此排第一的是戊。故选C。"},{"id":"pd-20969","module":"panduan","diff":1,"exam":"省考","prompt":"有人一提到某地区的人就认为他们精明，不问具体是谁。刻板印象是指人们对某个群体形成概括而固定的看法，并把这种看法推及该群体中的每一个体。根据上述定义，下列同样属于刻板印象的是：","options":["小王认定学艺术的学生都不拘小节，见到学美术的新生便觉得他一定散漫","小吴与小李初次见面便觉得对方可靠","小孙通过与每位同事逐一接触来了解他们","小郑因某人一次失误而全盘否定他"],"answer":0,"explanation":"刻板印象的要件是：针对群体的固定看法、不加区分地推及群体中的个体。「小王认定学艺术的学生都不拘小节，见到学美术的新生便觉得他一定散漫」完全符合上述要件；其余选项分别存在以下问题：逐一了解个体情况，未把群体看法套到个体身上；由个体表现推及其整体，属于晕轮效应；初次见面形成的印象属于首因效应。故选A。"},{"id":"pd-20970","module":"panduan","diff":2,"exam":"国考","prompt":"所有的哈士奇都是犬类，所有的犬类都是哺乳动物。由此可以推出：","options":["所有的哺乳动物都是哈士奇","所有的哈士奇都是哺乳动物","有的哺乳动物不是哈士奇","有的哈士奇不是哺乳动物"],"answer":1,"explanation":"三段论传递推理：哈士奇都属于犬类，犬类都属于哺乳动物，所以所有的哈士奇都是哺乳动物；其余选项不能必然推出。故选B。"},{"id":"pd-20971","module":"panduan","diff":2,"exam":"国考","prompt":"甲、乙、丙、丁、戊五人比较考试成绩。已知：乙比丙好；戊比丁好；甲比乙好；戊不是最好的。这五人的考试成绩从好到差排序，谁排第一？","options":["甲","乙","丁","戊"],"answer":0,"explanation":"由题干条件逐步推理，可得五人考试成绩从好到差的完整排序为：甲＞戊＞乙＞丁＞丙。因此排第一的是甲。故选A。"},{"id":"pd-20972","module":"panduan","diff":1,"exam":"国考","prompt":"油画：绘画\n下列与题干词项逻辑关系最相近的是：","options":["琴弦：吉他","龙井：杭州","棒球：球类运动","阻止：阻拦"],"answer":2,"explanation":"题干「油画」与「绘画」为种属包含关系；「棒球」与「球类运动」也是种属包含关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20973","module":"panduan","diff":2,"exam":"教师编","prompt":"培训机构只针对考试科目突击提分。素质教育是指以提高受教育者多方面素质为目标的教育模式，注重德智体美劳全面发展，强调面向全体学生、促进个性发展。根据上述定义，下列不属于素质教育的是：","options":["某中学开设劳动、艺术、体育等课程，组织社会实践，注重学生全面发展和个性培养","小学开展社团活动，鼓励每个学生至少参加一项兴趣活动，促进多元发展","学校按分数给学生排名并分设快慢班","学校组织学生参加志愿服务和劳动实践，培养多方面素质"],"answer":2,"explanation":"素质教育的要件是：以提高多方面素质为目标、面向全体学生、促进全面发展与个性发展。「学校按分数给学生排名并分设快慢班」不符合要件：唯分数做法违背面向全体、全面发展的要求；其余选项均符合素质教育的全部要件。故选C。"},{"id":"pd-20974","module":"panduan","diff":3,"exam":"国考","prompt":"某企业通过技术改造减少排放，并植树造林抵消剩余排放量，实现年度净零排放。碳中和是指在一定时期内，通过植树造林、节能减排等方式，抵消自身产生的二氧化碳排放，实现二氧化碳净零排放。根据上述定义，下列同样属于碳中和的是：","options":["某会议购买林业碳汇抵消活动产生的全部碳排放，实现碳中和办会","某市推广新能源汽车以减少尾气排放","企业新增两条高排放生产线","某家庭通过节约用电减少了部分碳排放"],"answer":0,"explanation":"碳中和的要件是：一定时期内、以植树造林或节能减排等方式抵消排放、实现净零排放。「某会议购买林业碳汇抵消活动产生的全部碳排放，实现碳中和办会」完全符合上述要件；其余选项分别存在以下问题：排放增加，与净零排放目标相反；仅减少部分排放，未实现抵消与净零；减排措施本身不等于实现碳中和。故选A。"},{"id":"pd-20975","module":"panduan","diff":1,"exam":"事业编","prompt":"某互联网企业取消中间管理层，实行项目小组直接对决策层负责。扁平化管理是指减少管理层级、扩大管理幅度，使组织结构趋于扁平的管理模式。根据上述定义，下列同样属于扁平化管理的是：","options":["公司增设多个管理层级，逐级审批","公司扩大招聘规模，员工总数翻倍","公司调整了工资结构","连锁企业精简区域管理机构，门店店长可直接与总部沟通"],"answer":3,"explanation":"扁平化管理的要件是：减少管理层级、扩大管理幅度。「连锁企业精简区域管理机构，门店店长可直接与总部沟通」完全符合上述要件；其余选项分别存在以下问题：层级增加与扁平化方向相反；人员规模变化不等于层级变化；薪酬调整与组织层级无关。故选D。"},{"id":"pd-20976","module":"panduan","diff":1,"exam":"省考","prompt":"班里发生了一件事：刚拖过的地面被踩脏了。老师询问甲、乙、丙、丁四人，四人的说法如下：甲说：“不是我踩脏地面的。”；乙说：“是甲踩脏地面的。”；丙说：“不是我踩脏地面的。”；丁说：“是乙踩脏地面的。”。四人中只有1人说真话。由此可以推出，踩脏地面的是：","options":["丁","甲","丙","乙"],"answer":2,"explanation":"只有一人说真话。逐一假设验证：只有假设丙踩脏地面时，四句话中为真的才恰好1句，符合题干条件，故丙踩脏地面。故选C。"},{"id":"pd-20977","module":"panduan","diff":3,"exam":"事业编","prompt":"赵某受物业公司聘用看管车辆，按合同约定收取看管费。无因管理是指没有法定或者约定的义务，为避免他人利益受损失而自愿管理他人事务或者为他人提供服务的行为。根据上述定义，下列不属于无因管理的是：","options":["李某拾到一只走失的宠物狗，喂养三天并张贴寻主启事","台风夜，王某发现路人昏倒在地，将其送医并垫付挂号费","钱某擅自将邻居堆放的旧家具当作废品卖掉，钱款归自己所有","邻居出差在外，其家中水管爆裂，张某破门而入修理水管并垫付费用"],"answer":2,"explanation":"无因管理的要件是：无法定或约定义务、为他人利益、主动管理他人事务或提供服务。「钱某擅自将邻居堆放的旧家具当作废品卖掉，钱款归自己所有」不符合要件：并非为他人利益，而是侵害他人利益；其余选项均符合无因管理的全部要件。故选C。"},{"id":"pd-20978","module":"panduan","diff":2,"exam":"事业编","prompt":"埃及：开罗\n下列与题干词项逻辑关系最相近的是：","options":["微波炉：家电","印度：新德里","西瓜：水果","国庆节：十月一日"],"answer":1,"explanation":"题干「埃及」与「开罗」为国家与其首都的对应；「印度」与「新德里」也是国家与其首都的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20979","module":"panduan","diff":2,"exam":"省考","prompt":"班里发生了一件事：刚拖过的地面被踩脏了。老师询问小王、小李、小张、小刘四人，四人的说法如下：小王说：“不是我踩脏地面的。”；小李说：“不是我踩脏地面的。”；小张说：“是小王踩脏地面的。”；小刘说：“是小张踩脏地面的。”。四人中只有1人说真话。由此可以推出，说真话的是：","options":["小李","小王","小刘","小张"],"answer":1,"explanation":"只有一人说真话。逐一假设验证可知，小王的话为真，其余三人的话均为假。故选B。"},{"id":"pd-20980","module":"panduan","diff":2,"exam":"国考","prompt":"如果广泛阅读，那么知识面拓宽。现已确认知识面没有拓宽。由此可以推出：","options":["没有广泛阅读","广泛阅读，尽管知识面没有拓宽","如果没有广泛阅读，那么知识面没有拓宽","广泛阅读"],"answer":0,"explanation":"充分条件命题否定后件就要否定前件。由知识面没有拓宽，可以推出没有广泛阅读；其余选项均不能由题干必然推出。故选A。"},{"id":"pd-20981","module":"panduan","diff":1,"exam":"事业编","prompt":"经理把琐碎事务交给助理，但所有决定仍须逐级请示。授权是指管理者将职权委授给下属，并为其提供必要的条件，使下属能在职权范围内自主处理事务的过程。根据上述定义，下列不属于授权的是：","options":["校长将社团活动审批权授予德育主任，由其按既定标准自行审批","公司实行总经理一人拍板制，大小事项均由其决定","部门经理把某项目的日常决策权交给组长，并提供经费支持，由组长自主安排","总经理授权区域经理在一定额度内自主决定促销方案"],"answer":1,"explanation":"授权的要件是：授予职权、提供必要条件、下属可自主处理事务。「公司实行总经理一人拍板制，大小事项均由其决定」不符合要件：权力集中于一人，与授权相反；其余选项均符合授权的全部要件。故选B。"},{"id":"pd-20982","module":"panduan","diff":2,"exam":"国考","prompt":"长篇小说：小说\n下列与题干词项逻辑关系最相近的是：","options":["兄：弟","清晰：模糊","木匠：刨子","玫瑰：花卉"],"answer":3,"explanation":"题干「长篇小说」与「小说」为种属包含关系；「玫瑰」与「花卉」也是种属包含关系，其余选项的关系与题干不一致。故选D。"},{"id":"pd-20983","module":"panduan","diff":2,"exam":"国考","prompt":"某企业建立舆情监测机制，在负面事件发酵前及时回应并启动应急预案。危机管理是指组织为应对可能发生或已经发生的危机，进行监测、预警、决策和处置，以减少损失、恢复秩序的过程。根据上述定义，下列同样属于危机管理的是：","options":["办公室统一采购办公用品","台风来临前，社区提前排查隐患、储备物资并组织危险区域居民转移","公司在年会上表彰优秀员工","企业按季度例会讨论经营计划"],"answer":1,"explanation":"危机管理的要件是：针对可能或已经发生的危机、监测预警、决策处置。「台风来临前，社区提前排查隐患、储备物资并组织危险区域居民转移」完全符合上述要件；其余选项分别存在以下问题：表彰活动与危机应对无关；常规经营计划不属于危机管理；日常采购事务不涉及危机。故选B。"},{"id":"pd-20984","module":"panduan","diff":2,"exam":"事业编","prompt":"如果提前出门，那么按时到校；如果按时到校，那么不耽误早读。由此可以推出：","options":["如果按时到校，那么提前出门","如果不耽误早读，那么提前出门","如果提前出门，那么不耽误早读","如果没有提前出门，那么耽误了早读"],"answer":2,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果提前出门，那么不耽误早读；其余选项均属无效推理。故选C。"},{"id":"pd-20985","module":"panduan","diff":2,"exam":"省考","prompt":"周某捡到他人丢弃的废旧纸箱变卖，得款二十元。不当得利是指没有合法根据，使他人受到损失而自己获得利益的事实。根据上述定义，下列不属于不当得利的是：","options":["吴某因经营有方，商品供不应求，利润大增","银行柜员操作失误，多付给取款人王某一万元，王某发现后拒不归还","快递员误将李某的包裹投递给同名的陈某，陈某拆开使用后拒不退还","商场系统故障，原价三千元的手机标价三百元，赵某明知标错仍趁机购买"],"answer":0,"explanation":"不当得利的要件是：一方获利、他方受损、获利与受损有因果关系、获利无合法根据。「吴某因经营有方，商品供不应求，利润大增」不符合要件：经营获利有合法根据；其余选项均符合不当得利的全部要件。故选A。"},{"id":"pd-20986","module":"panduan","diff":1,"exam":"国考","prompt":"羞愧：惭愧\n下列与题干词项逻辑关系最相近的是：","options":["闻鸡起舞：祖逖","三顾茅庐：刘备","询问：打听","破釜沉舟：项羽"],"answer":2,"explanation":"题干「羞愧」与「惭愧」为近义关系；「询问」与「打听」也是近义关系，其余选项的关系与题干不一致。故选C。"},{"id":"pd-20987","module":"panduan","diff":1,"exam":"省考","prompt":"共事多年后，同事对小王形成了全面深入的了解。首因效应是指交往双方形成的第一次印象对今后交往关系的影响，即先入为主带来的效果。根据上述定义，下列不属于首因效应的是：","options":["小张因好友极力推荐而对某人产生好感","新老师第一次上课妙语连珠，学生此后一直认为他学识渊博","面试中小李衣着得体、谈吐从容，面试官虽未细看简历，已对其留下能干的好印象","小赵与新同事初次见面时热情周到，同事此后对他印象颇佳"],"answer":0,"explanation":"首因效应的要件是：第一次接触、第一印象、对后续交往产生持续影响。「小张因好友极力推荐而对某人产生好感」不符合要件：好感来自他人评价，不是初次接触的直接印象；其余选项均符合首因效应的全部要件。故选A。"},{"id":"pd-20988","module":"panduan","diff":1,"exam":"国考","prompt":"王某作案后潜逃，在通缉期间向当地派出所投案，并如实供述了罪行。自首是指犯罪以后自动投案，如实供述自己的罪行的行为。根据上述定义，下列同样属于自首的是：","options":["孙某自动投案，但只交代部分罪行，隐瞒了主要犯罪事实","钱某作案后被公安机关抓获，在审讯中交代了罪行","周某因交通肇事被现场查获，谎称车辆是他人驾驶","赵某犯罪后委托家人代为报警，本人在原地等候，到案后如实交代罪行"],"answer":3,"explanation":"自首的要件是：自动投案、如实供述自己的罪行。「赵某犯罪后委托家人代为报警，本人在原地等候，到案后如实交代罪行」完全符合上述要件；其余选项分别存在以下问题：被抓获后被动交代，不属于自动投案；未如实供述主要犯罪事实；未如实供述自己的罪行。故选D。"},{"id":"pd-20989","module":"panduan","diff":2,"exam":"国考","prompt":"如果天下雨，那么地面变湿。现已确认地面没变湿。由此可以推出：","options":["天下雨","天下雨，尽管地面没变湿","如果天没下雨，那么地面没变湿","天没下雨"],"answer":3,"explanation":"充分条件命题否定后件就要否定前件。由地面没变湿，可以推出天没下雨；其余选项均不能由题干必然推出。故选D。"},{"id":"pd-20990","module":"panduan","diff":2,"exam":"国考","prompt":"甲、乙、丙、丁四人的职业各不相同，分别是教师、医生、律师、工程师。已知：丙的职业不是律师；丙的职业是工程师；乙的职业是律师；丁的职业不是工程师；丁的职业不是教师。由此可以推出，甲的职业是：","options":["工程师","律师","医生","教师"],"answer":3,"explanation":"由题干条件逐一排除可得：甲的职业是教师；乙的职业是律师；丙的职业是工程师；丁的职业是医生。因此甲的职业是教师。故选D。"},{"id":"pd-20991","module":"panduan","diff":2,"exam":"省考","prompt":"小张、小王、小李、小赵、小刘五人比较考试成绩。已知：小王比小张好；小李比小赵好；小李比小刘好；小王比小李好。这五人的考试成绩从好到差排序，谁排第一？","options":["小刘","小王","小赵","小李"],"answer":1,"explanation":"由题干条件逐步推理，可得五人考试成绩从好到差的完整排序为：小王＞小张＞小李＞小刘＞小赵。因此排第一的是小王。故选B。"},{"id":"pd-20992","module":"panduan","diff":2,"exam":"国考","prompt":"曹禺：《雷雨》：周朴园\n下列与题干词项逻辑关系最相近的是：","options":["生物：动物：大熊猫","曹雪芹：《红楼梦》：贾宝玉","克：千克：吨","交通工具：汽车：轿车"],"answer":1,"explanation":"题干三个词为作者、作品与其主人公的对应关系；「曹雪芹：《红楼梦》：贾宝玉」也是作者、作品与其主人公的对应关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20993","module":"panduan","diff":3,"exam":"省考","prompt":"法官：法院\n下列与题干词项逻辑关系最相近的是：","options":["崭新：面貌","飞行员：驾驶舱","《红楼梦》：曹雪芹","《雷雨》：曹禺"],"answer":1,"explanation":"题干「法官」与「法院」为职业与其工作场所的对应；「飞行员」与「驾驶舱」也是职业与其工作场所的对应，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20994","module":"panduan","diff":3,"exam":"省考","prompt":"财政大幅扩大支出后，银行贷款利率上行，居民住房贷款成本增加，购房意愿下降。挤出效应是指政府增加支出或发行公债融资时，引起利率上升，导致私人投资或消费减少的现象。根据上述定义，下列同样属于挤出效应的是：","options":["政府举债投资大型项目，资金市场趋紧，中小企业贷款难度加大、投资缩减","央行降息后企业贷款意愿增强","企业因市场需求旺盛而扩大投资","政府减税使居民可支配收入增加"],"answer":0,"explanation":"挤出效应的要件是：政府支出或发债融资、利率上升、私人投资或消费被挤减。「政府举债投资大型项目，资金市场趋紧，中小企业贷款难度加大、投资缩减」完全符合上述要件；其余选项分别存在以下问题：降息使投资增加，与挤出效应方向相反；减税增加居民收入，不属于挤出效应；投资扩大由市场需求驱动，与政府支出无关。故选A。"},{"id":"pd-20995","module":"panduan","diff":2,"exam":"省考","prompt":"优良：传统\n下列与题干词项逻辑关系最相近的是：","options":["负荆请罪：廉颇","崎岖：山路","农民：田间","快乐：高兴"],"answer":1,"explanation":"题干「优良」与「传统」为偏正关系；「崎岖」与「山路」也是偏正关系，其余选项的关系与题干不一致。故选B。"},{"id":"pd-20996","module":"panduan","diff":2,"exam":"省考","prompt":"甲、乙、丙、丁、戊五人比较体重。已知：甲比戊重；丙比戊重；戊比乙重；丁比甲重；丙不是最轻的。这五人的体重从重到轻排序，谁排第四？","options":["丙","丁","乙","戊"],"answer":3,"explanation":"由题干条件逐步推理，可得五人体重从重到轻的完整排序为：丙＞丁＞甲＞戊＞乙。因此排第四的是戊。故选D。"},{"id":"pd-20997","module":"panduan","diff":2,"exam":"国考","prompt":"如果饮食规律，那么肠胃健康；如果肠胃健康，那么营养吸收良好。由此可以推出：","options":["如果饮食规律，那么营养吸收良好","如果肠胃健康，那么饮食规律","如果营养吸收良好，那么饮食规律","如果饮食不规律，那么营养吸收不好"],"answer":0,"explanation":"充分条件命题具有传递性。由前两个命题连锁可得：如果饮食规律，那么营养吸收良好；其余选项均属无效推理。故选A。"},{"id":"pd-20998","module":"panduan","diff":2,"exam":"事业编","prompt":"廉价：昂贵\n下列与题干词项逻辑关系最相近的是：","options":["诚实：虚伪","明亮：敞亮","崎岖：山路","疲惫：困倦"],"answer":0,"explanation":"题干「廉价」与「昂贵」为反义关系；「诚实」与「虚伪」也是反义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-20999","module":"panduan","diff":1,"exam":"事业编","prompt":"服从：反抗\n下列与题干词项逻辑关系最相近的是：","options":["局部：整体","江：河","军人：党员","明亮：敞亮"],"answer":0,"explanation":"题干「服从」与「反抗」为反义关系；「局部」与「整体」也是反义关系，其余选项的关系与题干不一致。故选A。"},{"id":"pd-21000","module":"panduan","diff":2,"exam":"省考","prompt":"只有按时到校，才提前出门。现已确认提前出门。由此可以推出：","options":["只有提前出门，才按时到校","没能按时到校","按时到校","如果按时到校，那么提前出门"],"answer":2,"explanation":"「只有按时到校，才提前出门」中，按时到校是提前出门的必要条件，肯定后件就要肯定前件。现已确认提前出门，属于肯定后件，故按时到校必然成立，即按时到校；肯定前件不能推出后件，其余选项均不能必然推出。故选C。"}]);